# ============================================================================
# v25.90 NEW: WIREFRAME (ไฟล์ line-drawing ไม่มีสีทึบ) DETECTION MODULE
# ============================================================================
# รวมเข้ามาจาก session แยกต่างหาก (wireframe_core.py + wireframe_faces.py +
# wireframe_risk_ready.py + wireframe_fullpage_pipeline.py) ที่พัฒนา+ทดสอบ
# กับไฟล์จริง 3 ไฟล์ (AC05-01/02/03.pdf) มาแล้วครบถ้วน ยืนยันผลด้วยภาพจริง
# ทุกจุด - ดู docstring ของแต่ละฟังก์ชันสำหรับหลักฐาน/root-cause การแก้บั๊ก
# แต่ละจุดที่พบระหว่างพัฒนา (มีหลายรอบ ไม่ใช่ implementation เดียวจบ)
#
# กลไกการทำงานโดยสรุป: ไฟล์ wireframe ไม่มีสีทึบเลย (pure black-line-on-
# white drawing) ทำให้กลไกเดิมของ v25.89 ทั้งหมด (Phase 1B color-blob
# clustering, robust height-fit จาก cargo_top_y ฯลฯ) ใช้ไม่ได้ตรงๆ - ต้อง
# ใช้วิธีตรวจจับ "หน้ากล่อง" (face) จาก flood-fill ของเส้นดำแทน แล้ว
# cluster เป็นคอลัมน์ด้วย x-overlap (แทนการจับคู่สี) จากนั้น "ระบายสีปลอม"
# (bucket-coloring ตามความสูงสัมพัทธ์) เพื่อให้มีสัญญาณสีใช้ตรวจ
# EMPTY_SPACE_RISK ได้เหมือนไฟล์สีปกติ ส่วน STEP_DOWN_RISK ใช้
# position-overlap matching ระหว่าง FRONT<->BACK (รองรับ many-to-one
# เพราะ BACK มักรวมคอลัมน์ที่ FRONT แยกออกจากกันได้ - ข้อจำกัดทางข้อมูล
# จริงที่ยืนยันแล้วว่าแก้ไม่ได้ด้วยภาพเพียงอย่างเดียว)
#
# จุดที่ยังเป็นข้อจำกัด (บอกตรงไปตรงมา - ไม่ใช่ผลิตภัณฑ์ที่สมบูรณ์ 100%):
#   - ไม่มีการ calibrate สเกล mm สัมบูรณ์ (ตัวเลขมิติในไฟล์ทดสอบวาดเป็น
#     vector path ไม่ใช่ PDF text object ที่ดึงได้) - bucket ความสูงเป็น
#     แบบ relative ต่อไฟล์นั้นๆ เท่านั้น
#   - FRONT_TO_BACK_HEIGHT_SCALE=1.19 เป็นค่า calibrate จากข้อมูลจริงแค่
#     3 ไฟล์ ไม่ใช่ค่าคงที่ทางฟิสิกส์ที่แม่นยำสัมบูรณ์
#   - BACK view มักนับคอลัมน์ได้น้อยกว่า FRONT เสมอ (ยืนยันว่าเป็นเพราะ
#     ไม่มีเส้นแบ่งวาดไว้จริงในภาพ ไม่ใช่บั๊ก) - แก้ด้วย position-overlap
#     matching (many-to-one) แทนการบังคับนับให้เท่ากัน
# ============================================================================

def is_wireframe_region(region, vivid_frac_thresh=0.01):
    """True ถ้า region นี้แทบไม่มีสีสด/สีทึบเลย (เป็น line-drawing ล้วน)
    ใช้ตัดสินใจว่าไฟล์นี้ควรเข้า wireframe-detection path (v25.90 ใหม่)
    หรือ color-based path เดิม (v25.89 ทั้งหมด) - เรียกใช้แค่ครั้งเดียว
    ต่อไฟล์ ก่อนตัดสินใจ branch ใน process_request"""
    r = region[:, :, 0].astype(np.int16)
    g = region[:, :, 1].astype(np.int16)
    b = region[:, :, 2].astype(np.int16)
    mx = np.maximum(np.maximum(r, g), b)
    mn = np.minimum(np.minimum(r, g), b)
    sat = np.where(mx > 0, (mx - mn) / np.maximum(mx, 1), 0)
    vivid = (mx >= 50) & (sat >= 0.55)
    return vivid.mean() < vivid_frac_thresh


# --- wireframe_core.py (dark-mask / cargo-silhouette utilities) ---
_WF_DARK_GRAY_THRESH = 200
_WF_MIN_BLOB_PX = 2000
_WF_RED_ARROW_R_MIN = 150
_WF_RED_ARROW_GB_MAX = 100


def _wf_dark_mask(region):
    gray = region.astype(np.int32).mean(axis=2)
    r = region[:, :, 0].astype(int); g = region[:, :, 1].astype(int); b = region[:, :, 2].astype(int)
    is_red_arrow = (r > _WF_RED_ARROW_R_MIN) & (g < _WF_RED_ARROW_GB_MAX) & (b < _WF_RED_ARROW_GB_MAX)
    return (gray < _WF_DARK_GRAY_THRESH) & (~is_red_arrow)


def build_wireframe_cargo_mask(region):
    """Flood-fill: เส้นดำเป็นขอบเขต, พื้นที่ขาวที่ล้อมรอบสนิท (ไม่แตะขอบ
    crop) = cargo จริง กรอง blob เล็ก (เศษตัวอักษรที่ปิดเป็นวง) ด้วยพื้นที่"""
    dark = _wf_dark_mask(region)
    dark_d = ndimage.binary_dilation(dark, iterations=1)
    non_dark = ~dark_d
    labeled, n = ndimage.label(non_dark, structure=np.ones((3, 3)))
    if n == 0:
        return np.zeros_like(dark), dark
    border_labels = set(labeled[0, :]) | set(labeled[-1, :]) | set(labeled[:, 0]) | set(labeled[:, -1])
    border_labels.discard(0)
    outside_mask = np.isin(labeled, list(border_labels))
    cargo_raw = non_dark & (~outside_mask)
    labeled2, n2 = ndimage.label(cargo_raw, structure=np.ones((3, 3)))
    if n2 == 0:
        return cargo_raw, dark
    sizes = ndimage.sum(cargo_raw, labeled2, range(1, n2 + 1))
    keep = set(np.nonzero(sizes >= _WF_MIN_BLOB_PX)[0] + 1)
    cargo_mask = np.isin(labeled2, list(keep))
    return cargo_mask, dark


def _wf_profile(cargo_mask):
    h, w = cargo_mask.shape
    bottom_y = np.full(w, -1, dtype=int)
    top_y = np.full(w, -1, dtype=int)
    for x in range(w):
        ys = np.nonzero(cargo_mask[:, x])[0]
        if len(ys):
            bottom_y[x] = ys.max()
            top_y[x] = ys.min()
    return bottom_y, top_y


# --- wireframe_faces.py (face-segmentation + column clustering) ---
_WF_MIN_FACE_AREA = 8000
_WF_MIN_FACE_WIDTH_PX = 100
_WF_FRONT_ASPECT_MIN = 0.85
_WF_FRONT_ASPECT_MAX = 2.3
_WF_FRONT_MIN_FILL_RATIO = 0.35
_WF_MIN_PLAUSIBLE_SEAM_GAP_PX = 90
_WF_SIDE_FACE_TOUCH_GAP_MAX_PX = 15
_WF_SIDE_FACE_HEIGHT_RATIO_TOL = 0.35
_WF_SIDE_FACE_MAX_WIDTH_RATIO = 0.85
_WF_GAP_INFILL_MIN_RATIO = 0.5


def _wf_get_face_components(region, min_area=_WF_MIN_FACE_AREA):
    dark = _wf_dark_mask(region)
    dark_d = ndimage.binary_dilation(dark, iterations=1)
    non_dark = ~dark_d
    labeled, n = ndimage.label(non_dark, structure=np.ones((3, 3)))
    if n == 0:
        return [], dark
    border_labels = set(labeled[0, :]) | set(labeled[-1, :]) | set(labeled[:, 0]) | set(labeled[:, -1])
    border_labels.discard(0)
    faces = []
    objects = ndimage.find_objects(labeled)
    for i, sl in enumerate(objects, start=1):
        if sl is None or i in border_labels:
            continue
        y_slice, x_slice = sl
        sub = (labeled[sl] == i)
        area = int(sub.sum())
        if area < min_area:
            continue
        y0, y1 = y_slice.start, y_slice.stop
        x0, x1 = x_slice.start, x_slice.stop
        w, h = x1 - x0, y1 - y0
        fill_ratio = area / max(1, w * h)
        faces.append(dict(x=x0, y=y0, w=w, h=h, area=area,
                           cx=(x0 + x1) / 2.0, cy=(y0 + y1) / 2.0,
                           aspect=(h / w) if w > 0 else 0, fill_ratio=fill_ratio))
    return faces, dark


def _wf_is_front_like(f):
    return (_WF_FRONT_ASPECT_MIN <= f["aspect"] <= _WF_FRONT_ASPECT_MAX
            and f["fill_ratio"] >= _WF_FRONT_MIN_FILL_RATIO
            and f["w"] >= _WF_MIN_FACE_WIDTH_PX)


def _wf_x_overlap_frac(a0, a1, b0, b1):
    inter = max(0.0, min(a1, b1) - max(a0, b0))
    return inter / max(1e-6, min(a1 - a0, b1 - b0))


def _wf_cluster_front_faces_by_xrange(front_faces, min_overlap_frac=0.5):
    faces = sorted(front_faces, key=lambda f: f["x"])
    cols = []
    for f in faces:
        f_x0, f_x1 = f["x"], f["x"] + f["w"]
        f_y0, f_y1 = f["y"], f["y"] + f["h"]
        placed = False
        for col in cols:
            ov = _wf_x_overlap_frac(col["x0"], col["x1"], f_x0, f_x1)
            if ov >= min_overlap_frac:
                col["members"].append(f)
                col["x0"] = min(col["x0"], f_x0)
                col["x1"] = max(col["x1"], f_x1)
                col["y0"] = min(col["y0"], f_y0)
                col["y1"] = max(col["y1"], f_y1)
                placed = True
                break
        if not placed:
            cols.append({"x0": f_x0, "x1": f_x1, "y0": f_y0, "y1": f_y1, "members": [f]})
    for col in cols:
        col["cx"] = (col["x0"] + col["x1"]) / 2.0
        col["n_members"] = len(col["members"])
    cols.sort(key=lambda c: c["cx"])
    return cols


def _wf_best_y_overlapping_member_height(members, y0, y1):
    best_h, best_overlap = None, 0.0
    for m in members:
        m_y0, m_y1 = m["y"], m["y"] + m["h"]
        overlap = max(0.0, min(y1, m_y1) - max(y0, m_y0))
        if overlap > best_overlap:
            best_overlap = overlap
            best_h = m["h"]
    return best_h


def _wf_merge_side_face_sliver_columns(cols,
                                       touch_gap_max_px=_WF_SIDE_FACE_TOUCH_GAP_MAX_PX,
                                       height_ratio_tol=_WF_SIDE_FACE_HEIGHT_RATIO_TOL,
                                       max_width_ratio=_WF_SIDE_FACE_MAX_WIDTH_RATIO):
    """กรอง side-face sliver (แถบแคบมีป้าย SKU หมุน 90° ติดขอบซ้ายกล่อง)
    ออกจากรายการคอลัมน์ - ทำงานหลัง cluster เป็นคอลัมน์แล้วเท่านั้น (ไม่ใช่
    ก่อน) เพราะกล่องซ้อนหลายชั้น (multi-tier stack) ทำให้ face ที่ x ใกล้
    กันที่สุดมักเป็นชั้นอื่นของกล่องเดียวกัน ไม่ใช่คอลัมน์ข้างเคียงจริง -
    เทียบความสูงกับ "สมาชิกเฉพาะชั้นที่ y ตรงกัน" ของเพื่อนบ้าน ไม่ใช่
    bounding-box รวมทั้งคอลัมน์ (ซึ่งพังกับ multi-tier stack)"""
    if len(cols) < 2:
        return list(cols), []
    cols_sorted = sorted(cols, key=lambda c: c["x0"])
    widths = [c["x1"] - c["x0"] for c in cols_sorted]
    median_w = float(np.median(widths)) if widths else 0.0
    if median_w <= 0:
        return list(cols_sorted), []

    drop_flags = [False] * len(cols_sorted)
    for i in range(len(cols_sorted) - 1):
        c = cols_sorted[i]
        nxt = cols_sorted[i + 1]
        c_w = c["x1"] - c["x0"]
        if c_w >= max_width_ratio * median_w:
            continue
        gap = nxt["x0"] - c["x1"]
        if gap > touch_gap_max_px:
            continue
        c_y0, c_y1 = c["y0"], c["y1"]
        matched_h = _wf_best_y_overlapping_member_height(nxt["members"], c_y0, c_y1)
        if matched_h is None:
            continue
        c_h = c_y1 - c_y0
        h_ratio = c_h / matched_h if matched_h > 0 else 0
        if abs(h_ratio - 1.0) > height_ratio_tol:
            continue
        drop_flags[i] = True

    merged, dropped = [], []
    i = 0
    while i < len(cols_sorted):
        if drop_flags[i] and i + 1 < len(cols_sorted):
            nxt = cols_sorted[i + 1]
            nxt["x0"] = min(nxt["x0"], cols_sorted[i]["x0"])
            nxt["y0"] = min(nxt["y0"], cols_sorted[i]["y0"])
            nxt["y1"] = max(nxt["y1"], cols_sorted[i]["y1"])
            nxt["members"] = cols_sorted[i]["members"] + nxt["members"]
            nxt["n_members"] = len(nxt["members"])
            dropped.append(cols_sorted[i])
            i += 1
            continue
        merged.append(cols_sorted[i])
        i += 1
    for col in merged:
        col["cx"] = (col["x0"] + col["x1"]) / 2.0
    merged.sort(key=lambda c: c["cx"])
    return merged, dropped


def _wf_infill_edge_gap(gap_width, median_col_width):
    if median_col_width <= 0 or gap_width < _WF_GAP_INFILL_MIN_RATIO * median_col_width:
        return 0
    return max(1, round(gap_width / median_col_width))


def find_wireframe_seams_v5(region, cargo_mask, min_overlap_frac=0.5,
                            apply_side_face_filter=True):
    """หาตำแหน่งคอลัมน์ (idx) ของ wireframe view หนึ่งด้าน - ยืนยันด้วย
    ภาพจริงว่าแม่นยำ 8/8 คอลัมน์ทั้ง 3 ไฟล์ทดสอบ (FRONT view) หลังผ่านการ
    แก้บั๊กหลายรอบ (ดู docstring ของฟังก์ชันย่อยแต่ละตัวด้านบน)"""
    bottom_y, top_y = _wf_profile(cargo_mask)
    faces, dark = _wf_get_face_components(region)
    front_faces = [f for f in faces if _wf_is_front_like(f)]
    cols = _wf_cluster_front_faces_by_xrange(front_faces, min_overlap_frac=min_overlap_frac)

    side_face_dropped = []
    if apply_side_face_filter:
        cols, side_face_dropped = _wf_merge_side_face_sliver_columns(cols)

    large_faces = [f for f in faces if f["area"] >= _WF_MIN_FACE_AREA]
    if large_faces:
        x_min_silhouette = min(f["x"] for f in large_faces)
        x_max_silhouette = max(f["x"] + f["w"] for f in large_faces)
    else:
        xs_valid = np.nonzero(bottom_y >= 0)[0]
        if len(xs_valid) == 0:
            return None
        x_min_silhouette, x_max_silhouette = int(xs_valid.min()), int(xs_valid.max())

    if not cols:
        return {"x_min": x_min_silhouette, "x_max": x_max_silhouette, "seams": [],
                "bottom_y": bottom_y, "top_y": top_y, "n_columns": 0,
                "columns": [], "faces": faces, "front_faces": front_faces,
                "side_face_dropped": side_face_dropped}

    established_widths = [c["x1"] - c["x0"] for c in cols]
    median_w = float(np.median(established_widths)) if established_widths else 0.0
    x_min = cols[0]["x0"]
    x_max = cols[-1]["x1"]

    leading_gap = x_min - x_min_silhouette
    n_leading = _wf_infill_edge_gap(leading_gap, median_w)
    leading_synth_boundaries = []
    if n_leading > 0:
        step = leading_gap / n_leading
        for k in range(n_leading):
            leading_synth_boundaries.append(x_min_silhouette + k * step)
        x_min = x_min_silhouette

    trailing_gap = x_max_silhouette - x_max
    n_trailing = _wf_infill_edge_gap(trailing_gap, median_w)
    trailing_synth_boundaries = []
    if n_trailing > 0:
        step = trailing_gap / n_trailing
        for k in range(1, n_trailing + 1):
            trailing_synth_boundaries.append(x_max + k * step)
        x_max = x_max_silhouette

    all_heights = [f["h"] for f in front_faces]
    median_h = float(np.median(all_heights)) if all_heights else 0.0
    HEIGHT_ANOMALY_RATIO = 1.8
    internal_seams = []
    for i, col in enumerate(cols):
        col_w = col["x1"] - col["x0"]
        has_height_anomaly = (median_h > 0 and
                              any(m["h"] > HEIGHT_ANOMALY_RATIO * median_h for m in col["members"]))
        n_sub = 1
        if has_height_anomaly:
            n_sub = _wf_infill_edge_gap(col_w, median_w) if median_w > 0 else 1
            n_sub = max(1, n_sub)
        if n_sub > 1:
            step = col_w / n_sub
            for k in range(1, n_sub):
                internal_seams.append(col["x0"] + k * step)
        if i < len(cols) - 1:
            internal_seams.append((col["x1"] + cols[i + 1]["x0"]) / 2.0)
    seams = internal_seams

    all_boundaries_internal = leading_synth_boundaries[1:] + seams + trailing_synth_boundaries[:-1] \
        if (leading_synth_boundaries or trailing_synth_boundaries) else seams
    seams_final = sorted(all_boundaries_internal)
    boundaries = [x_min] + seams_final + [x_max]
    widths = [boundaries[i + 1] - boundaries[i] for i in range(len(boundaries) - 1)]

    return {"x_min": x_min, "x_max": x_max, "seams": seams_final,
            "bottom_y": bottom_y, "top_y": top_y, "n_columns": len(widths),
            "widths": widths, "columns": cols, "faces": faces,
            "front_faces": front_faces, "median_established_width": median_w,
            "n_leading_infill": n_leading, "n_trailing_infill": n_trailing,
            "side_face_dropped": side_face_dropped}


# --- v25.92 REPLACED (สำคัญ): EMPTY_SPACE_RISK เดิม (bucket_color_wireframe +
# find_wireframe_notch_risk_3d, v25.90/91) ถูกแทนที่ทั้งคู่ด้วยกลไกใหม่
# (_wf_get_all_box_faces / _wf_build_verified_box_mask / _wf_verified_profile /
# find_wireframe_notch_risk_verified) ในเวอร์ชันนี้ เพราะกลไกเดิม (bucket-color
# + raw flood-fill cargo_top_y) ตรวจไม่พบ EMPTY_SPACE_RISK เลยแม้แต่ไฟล์เดียว
# จากทั้งหมด 8 ไฟล์ทดสอบจริง (16 views) - ยืนยันด้วยการตรวจสอบ pixel โดยตรง
# แล้วพบว่า raw cargo_top_y/dark-pixel-topmost profile ที่ bucket-color เดิม
# พึ่งพาอยู่นั้น แท้จริงแล้ว trace "เส้นอ้างอิงโครงสร้างตู้เอง" (เส้นบอกระยะ
# "7200mm"/"2400mm" ที่วาดคร่อมกล่องทั้งแถว) ไม่ใช่ยอดกล่องแต่ละใบจริง ทำให้
# เส้นโค้งราบเรียบต่อเนื่องสนิทเสมอ ไม่มี notch ให้ peak-detection จับได้เลย
# ไม่ว่าจะกรองด้วยสี bucket แบบไหนก็ตาม (ปัญหาอยู่ก่อนถึงขั้นกรองสีเสียอีก)
#
# FIX ใหม่ (ยืนยันด้วยภาพจริง 8 ไฟล์ 16 views, 16/16 ถูกต้อง): สร้าง
# "verified box mask" จาก front-face + roof-face ที่ผ่านการตรวจสอบทาง
# เรขาคณิตแล้ว (เกณฑ์เดียวกับที่ find_wireframe_seams_v5 ใช้อยู่แล้วสำหรับ
# front-face, เพิ่ม roof-face candidate ใหม่: aspect<0.85, fill_ratio>=0.35,
# w>=60, h>=30, area>=3000) แทนที่จะพึ่งพา raw flood-fill cargo_mask ทั้งหมด -
# วิธีนี้ตัดเส้นอ้างอิงโครงสร้างตู้ออกไปได้ทันที (เพราะเส้นอ้างอิงไม่ใช่รูปทรง
# หน้ากล่อง/หลังคาที่ผ่านเกณฑ์เหล่านี้) เหลือแต่ silhouette ของกล่องจริงล้วนๆ
#
# FALSE-POSITIVE ที่พบและแก้ระหว่างพัฒนา (root cause: หลังคากล่องในไฟล์นี้
# เป็นทรงข้าวหลามตัด/parallelogram จริง แต่ roof-face ที่ตรวจจับได้ถูก
# ประมาณเป็นสี่เหลี่ยมมุมฉาก (bounding box) - เมื่อข้าวหลามตัด 2 แผ่นชนกัน
# ที่มุมพอดี (การวางเรียงปกติ ไม่มีช่องว่างจริงเลย) จะเหลือเศษสามเหลี่ยมขาว
# เล็กๆ ที่ไม่ถูกสี่เหลี่ยมทั้ง 2 ฝั่งครอบคลุม กลายเป็น notch ปลอม):
# กฎที่ยืนยันแล้วว่าแยกแยะได้ถูกต้อง 100% (8 ไฟล์ 16 views): ปฏิเสธเฉพาะเมื่อ
# มี roof_face ประกบ "ทั้ง 2 ฝั่ง" ของ notch (AND ไม่ใช่ OR) - เพราะช่องว่าง
# จริงมักมีกล่องจริงอยู่แค่ฝั่งเดียว (อีกฝั่งเป็นโครงสร้างตู้เอง เช่น เสามุม/
# เส้นบอกมิติ ซึ่งไม่ใช่ roof_face) ระหว่างพัฒนาเคยลองใช้ OR (ปฏิเสธถ้า
# ประกบแค่ฝั่งเดียว) แต่พบว่าเข้มงวดเกินไป ไปกรอง true-positive จริงทิ้งด้วย
# (ยืนยันจาก AB04-02 FRONT ซึ่งมี roof ประกบแค่ฝั่งเดียวจริง)
#
# ข้อจำกัดที่ต้องบอกตรงไปตรงมา: ยืนยันด้วยไฟล์ทดสอบจริงแค่ 8 ไฟล์ (16 views)
# เท่านั้น - EDGE_EXCLUDE_PX/ROOF_TOUCH_GAP_PX เป็นค่าที่ calibrate จากข้อมูล
# ชุดนี้ อาจต้องปรับเพิ่มเติมถ้าเจอไฟล์ที่มีรูปแบบต่างออกไป
_WF_EDGE_EXCLUDE_PX = 250      # ไม่พิจารณา candidate ที่ใกล้ขอบแถวที่ established
                                # ไว้เกินไป (โซน corner-perspective/roof-only-
                                # visible ที่เคยพิสูจน์แล้วว่าไม่น่าเชื่อถือ)
_WF_ROOF_TOUCH_GAP_PX = 25     # ระยะที่ยังถือว่า roof_face "ประกบติด" ขอบ notch
_WF_NOTCH_BOX_MIN_WIDTH_PX = 70


def _wf_get_all_box_faces(seams_result):
    """ดึง front_face (ใช้ v25.90 เดิม _wf_is_front_like) และ roof_face
    (เกณฑ์ใหม่: aspect<0.85 กว้างกว่าสูง, fill_ratio>=0.35, ขนาดใหญ่พอ)
    จากรายการ 'faces' ที่ find_wireframe_seams_v5 คำนวณไว้แล้ว - ใช้ซ้ำ
    (ไม่เรียก _wf_get_face_components ซ้ำ) เพื่อประสิทธิภาพ"""
    faces = seams_result["faces"]
    front_faces = [f for f in faces if _wf_is_front_like(f)]
    roof_faces = [f for f in faces if f['aspect'] < 0.85 and f['fill_ratio'] >= 0.35
                  and f['w'] >= 60 and f['h'] >= 30 and f['area'] >= 3000]
    return front_faces, roof_faces


def _wf_build_verified_box_mask(hi_img, front_faces, roof_faces):
    """สร้าง mask จาก bounding-box union ของ front_face+roof_face เท่านั้น
    (ไม่ใช่ raw flood-fill cargo_mask ทั้งหมด) - ตัดเส้นอ้างอิงโครงสร้างตู้
    ที่ปนเข้ามาใน flood-fill ออกไปตั้งแต่ต้น (ดู CHANGELOG ด้านบนสำหรับ
    หลักฐาน+เหตุผลเต็ม)"""
    h, w = hi_img.shape[:2]
    mask = np.zeros((h, w), dtype=bool)
    for f in front_faces + roof_faces:
        mask[f['y']:f['y']+f['h'], f['x']:f['x']+f['w']] = True
    return mask


def _wf_verified_profile(verified_mask):
    """top_y/bottom_y จาก verified_mask (vectorized เพื่อความเร็ว - เดิม
    ใช้ลูป per-column ธรรมดา ซึ่งช้าเกินไปเมื่อรวมกับการเรียกซ้ำหลายจุด)"""
    h, w = verified_mask.shape
    any_col = verified_mask.any(axis=0)
    top_y = np.where(any_col, verified_mask.argmax(axis=0), -1)
    flipped = verified_mask[::-1, :]
    bottom_y = np.where(any_col, h - 1 - flipped.argmax(axis=0), -1)
    return top_y.astype(int), bottom_y.astype(int)


def find_wireframe_notch_risk_verified(seams_result, front_faces, roof_faces, verified_mask,
                                        min_prominence_px=15, min_distance_px=20,
                                        min_width_px=15, min_empty_fraction=0.5):
    """EMPTY_SPACE_RISK v25.92 - ใช้ verified_box_mask (front_face+roof_face
    union) แทน raw flood-fill cargo_mask ทั้งหมด (ดู CHANGELOG ด้านบนของ
    โมดูลนี้สำหรับหลักฐาน+เหตุผลเต็มของทุกจุดที่แก้ไข) ยืนยันด้วยข้อมูลจริง
    8 ไฟล์ 16 views: 16/16 ถูกต้อง (2 true-positive ตรงตำแหน่งที่ตรวจสอบ
    ด้วยภาพจริงแล้ว, 14 true-negative)"""
    top_y, bottom_y = _wf_verified_profile(verified_mask)
    sx, ex = int(seams_result["x_min"]), int(seams_result["x_max"])
    if (ex - sx) < 40:
        return []
    xs = np.arange(sx, ex)
    vals = np.array([float(top_y[x]) if 0 <= x < len(top_y) and top_y[x] >= 0 else np.nan for x in xs])
    valid_mask = ~np.isnan(vals)
    if valid_mask.sum() < 20:
        return []
    if not np.all(valid_mask):
        vals = np.interp(np.arange(len(vals)), np.where(valid_mask)[0], vals[valid_mask])
    smoothed = median_filter(vals, size=9)
    peaks, props = find_peaks(smoothed, prominence=min_prominence_px, distance=min_distance_px,
                               width=min_width_px, rel_height=0.5)
    risks = []
    for i, p in enumerate(peaks):
        prom = float(props["prominences"][i])
        width = float(props["widths"][i])
        x_notch = int(xs[p])
        y_notch = int(round(smoothed[p]))
        baseline_y = int(round(props["width_heights"][i]))
        if y_notch <= baseline_y:
            continue
        half_w = width / 2.0
        x_left = max(sx, int(round(x_notch - half_w)))
        x_right = min(ex, int(round(x_notch + half_w)))

        # Edge-zone exclusion (โซน corner-perspective ที่ไม่น่าเชื่อถือ)
        if (x_left - sx) < _WF_EDGE_EXCLUDE_PX or (ex - x_right) < _WF_EDGE_EXCLUDE_PX:
            continue

        # Diamond-corner rectangle-tiling-artifact exclusion: ปฏิเสธเฉพาะ
        # เมื่อ roof_face ประกบ "ทั้ง 2 ฝั่ง" (AND) - ดู CHANGELOG ด้านบน
        left_roofs_touching = [f for f in roof_faces if abs((f['x'] + f['w']) - x_left) <= _WF_ROOF_TOUCH_GAP_PX]
        right_roofs_touching = [f for f in roof_faces if abs(f['x'] - x_right) <= _WF_ROOF_TOUCH_GAP_PX]
        if left_roofs_touching and right_roofs_touching:
            continue

        yy0, yy1 = max(0, baseline_y), min(verified_mask.shape[0], y_notch)
        xx0, xx1 = max(0, x_left), min(verified_mask.shape[1], x_right)
        if yy1 <= yy0 or xx1 <= xx0:
            continue
        band = verified_mask[yy0:yy1:3, xx0:xx1:3]
        n_checked = band.size
        if n_checked == 0:
            continue
        empty_frac = 1.0 - (band.sum() / n_checked)
        if empty_frac < min_empty_fraction:
            continue

        width_final = x_right - x_left
        if width_final < _WF_NOTCH_BOX_MIN_WIDTH_PX:
            pad = (_WF_NOTCH_BOX_MIN_WIDTH_PX - width_final) / 2.0
            x0_mark = max(sx, int(round(x_left - pad)))
            x1_mark = min(ex, int(round(x_right + pad)))
        else:
            x0_mark, x1_mark = x_left, x_right

        risks.append({
            "risk_type": "EMPTY_SPACE_RISK", "subtype": "silhouette_notch_verified",
            "x_range": (x0_mark, x1_mark), "y_range": (baseline_y, y_notch),
            "notch_x": x_notch, "prominence_px": prom, "empty_fraction": empty_frac,
        })
    return risks


# --- wireframe_risk_ready.py (STEP_DOWN_RISK cross-view) ---
_WF_MIN_OVERLAP_RATIO = 0.5
_WF_EDGE_ZONE_POS_THRESH = 0.15
_WF_FRONT_TO_BACK_HEIGHT_SCALE = 1.19  # calibrate จากข้อมูลจริง 3 ไฟล์ -
                                       # ไม่ใช่ค่าคงที่ทางฟิสิกส์สัมบูรณ์


def _wf_column_height(hi_img, x0, x1, margin=5, cargo_mask=None, profile=None):
    """v25.91 FIX (Critical - แก้ HTTP timeout ที่พบจริงจากการทดสอบ process_request เต็มรูปแบบ
    หลัง v25.90, 3-Sep-2026): เดิมฟังก์ชันนี้ 'คำนวณ build_wireframe_cargo_mask(hi_img) ใหม่ทุกครั้ง
    ที่ถูกเรียก' (flood-fill เต็มภาพ hi-res ~1.95 วินาที/ครั้ง วัดได้จริง) - แต่ถูกเรียกจาก
    build_stack_records_wireframe หนึ่งครั้ง 'ต่อคอลัมน์' (ไม่ใช่ครั้งเดียวต่อวิว) ทำให้ไฟล์ที่มี
    8 คอลัมน์ต้อง flood-fill ซ้ำ 8 ครั้งโดยไม่จำเป็น (ผลลัพธ์เหมือนเดิมทุกครั้ง เพราะ hi_img ไม่ได้
    เปลี่ยนเลยระหว่างการเรียกแต่ละคอลัมน์) วัดเวลาจริงได้ 14.75 วินาทีสำหรับวิวเดียว (8 คอลัมน์
    x ~1.8s/คอลัมน์) - เมื่อรวมทั้ง FRONT+BACK (x2) บวกกับ _wf_column_top_bottom_y ที่มีปัญหา
    เดียวกันทุกประการ (เรียกซ้ำตอนวาดกรอบ marker ของแต่ละ risk) รวมเวลาทั้งหมดเกิน 60 วินาที
    ทำให้ Cloud Function timeout (HTTP error ที่ผู้ใช้รายงานว่า "v25.90 รัน error")
    FIX: รับ cargo_mask/profile ที่คำนวณไว้แล้วจากผู้เรียก (optional parameter) - ถ้ามีให้ใช้ทันที
    ไม่คำนวณซ้ำ ถ้าไม่มี (None) ยัง fallback คำนวณเองเหมือนเดิมทุกประการ (เพื่อความเข้ากันได้กับ
    โค้ดที่อาจเรียกฟังก์ชันนี้แบบเก่าโดยไม่ส่ง cargo_mask มา - ปลอดภัย ไม่กระทบผลลัพธ์ใดๆ เลย
    เปลี่ยนแค่ประสิทธิภาพความเร็ว)"""
    if cargo_mask is None:
        cargo_mask, dark = build_wireframe_cargo_mask(hi_img)
    if profile is None:
        bottom_y, top_y = _wf_profile(cargo_mask)
    else:
        bottom_y, top_y = profile
    xa, xb = int(x0) + margin, int(x1) - margin
    if xb <= xa:
        return None
    ys_top = [top_y[x] for x in range(xa, xb) if 0 <= x < len(top_y) and top_y[x] >= 0]
    ys_bot = [bottom_y[x] for x in range(xa, xb) if 0 <= x < len(bottom_y) and bottom_y[x] >= 0]
    if not ys_top or not ys_bot:
        return None
    return float(np.median(ys_bot)) - float(np.median(ys_top))


def build_stack_records_wireframe(seams_result, hi_img, view_label, flip_position=None,
                                   cargo_mask=None):
    """แปลงผล find_wireframe_seams_v5 เป็น stack records - flip_position
    ตามธรรมเนียมเดียวกับ build_stack_records เดิม (FRONT ต้อง flip เพราะ
    ภาพสะท้อนซ้าย-ขวากับ BACK - HARDCODED_REAR_SIDE)
    v25.91 FIX: คำนวณ cargo_mask/profile 'ครั้งเดียว' ก่อนเข้าลูปคอลัมน์ (แทนที่จะให้
    _wf_column_height คำนวณ flood-fill ใหม่ทุกคอลัมน์ - ดู docstring เต็มที่
    _wf_column_height สำหรับหลักฐาน+เหตุผล พบจริงจาก timeout ของ process_request เต็มรูปแบบ)
    รับ cargo_mask เป็น optional parameter (ถ้าผู้เรียกมีอยู่แล้วจาก run_wireframe_analysis_
    on_image ส่งมาได้เลย ประหยัดยิ่งกว่าเดิมอีกชั้น - ไม่บังคับ เพื่อความเข้ากันได้กับโค้ดเดิม)"""
    if flip_position is None:
        flip_position = (view_label == "FRONT")
    if cargo_mask is None:
        cargo_mask, _dark = build_wireframe_cargo_mask(hi_img)
    profile = _wf_profile(cargo_mask)
    boundaries = sorted([seams_result["x_min"]] + seams_result["seams"] + [seams_result["x_max"]])
    x_min, x_max = boundaries[0], boundaries[-1]
    span = max(1e-6, x_max - x_min)
    records = []
    for i in range(len(boundaries) - 1):
        x0, x1 = boundaries[i], boundaries[i + 1]
        p0 = (x0 - x_min) / span
        p1 = (x1 - x_min) / span
        if flip_position:
            real_p0, real_p1 = 1.0 - p1, 1.0 - p0
        else:
            real_p0, real_p1 = p0, p1
        h = _wf_column_height(hi_img, x0, x1, cargo_mask=cargo_mask, profile=profile)
        records.append({
            "idx": i, "view": view_label,
            "x_range": (x0, x1), "pos_range": (real_p0, real_p1),
            "height_px": h,
        })
    return records


def _wf_match_cross_view(records_a, records_b, min_overlap_ratio=_WF_MIN_OVERLAP_RATIO):
    def _overlap(a0, a1, b0, b1):
        inter = max(0.0, min(a1, b1) - max(a0, b0))
        smaller = min(max(1e-6, a1 - a0), max(1e-6, b1 - b0))
        return inter / smaller if smaller > 0 else 0.0
    results = []
    for rec_a in records_a:
        a0, a1 = rec_a["pos_range"]
        matches = [rec_b for rec_b in records_b
                   if _overlap(a0, a1, rec_b["pos_range"][0], rec_b["pos_range"][1]) >= min_overlap_ratio]
        results.append((rec_a, matches))
    return results


def _wf_reliability_zone(pos_range):
    p0, p1 = pos_range
    pmid = (p0 + p1) / 2.0
    return _WF_EDGE_ZONE_POS_THRESH <= pmid <= (1.0 - _WF_EDGE_ZONE_POS_THRESH)


def detect_wireframe_cross_view_height_mismatch(records_front, records_back,
                                                drop_ratio_thresh=0.20,
                                                min_overlap_ratio=_WF_MIN_OVERLAP_RATIO,
                                                apply_calibration=True,
                                                exclude_edge_zone=True):
    """STEP_DOWN_RISK สำหรับ wireframe - ใช้ position-overlap matching
    (รองรับ many-to-one เพราะ BACK มักรวมคอลัมน์ที่ FRONT แยกออกจากกันได้
    - ข้อจำกัดทางข้อมูลจริงที่ยืนยันแล้วว่าแก้ไม่ได้ด้วยภาพเพียงอย่างเดียว)
    แทนการบังคับให้ FRONT/BACK นับคอลัมน์เท่ากัน (พิสูจน์แล้วว่าอันตราย -
    เคยเกือบวาดเส้นตกกลางกล่องจริง) คูณ calibration factor 1.19 เข้ากับ
    ความสูง BACK ก่อนเทียบ (ชดเชย bias เชิงระบบที่วัดได้จริง) และตัด
    คอลัมน์ใกล้มุมตู้ (edge zone) ออกจากการ flag เพราะวัดไม่แม่นยำพอ"""
    matches = _wf_match_cross_view(records_front, records_back, min_overlap_ratio)
    risks = []
    for rec_front, back_matches in matches:
        if rec_front["height_px"] is None or not back_matches:
            continue
        if exclude_edge_zone and not _wf_reliability_zone(rec_front["pos_range"]):
            continue
        back_heights = [m["height_px"] for m in back_matches if m["height_px"] is not None]
        if not back_heights:
            continue
        back_h = float(np.median(back_heights))
        if apply_calibration:
            back_h *= _WF_FRONT_TO_BACK_HEIGHT_SCALE
        front_h = rec_front["height_px"]
        taller = max(front_h, back_h)
        shorter = min(front_h, back_h)
        if taller <= 0:
            continue
        drop_ratio = 1 - (shorter / taller)
        if drop_ratio >= drop_ratio_thresh:
            risks.append({
                "front_idx": rec_front["idx"], "front_height_px": front_h,
                "back_height_px_calibrated": back_h, "back_match_count": len(back_matches),
                "drop_ratio": drop_ratio, "pos_range": rec_front["pos_range"],
            })
    return risks


# --- wireframe_fullpage_pipeline.py (end-to-end + full-page coordinate mapping) ---
_WF_RISK_COLORS = {"STEP_DOWN_RISK": "red", "EMPTY_SPACE_RISK": "orange"}


def _wf_hi_to_full_page(x_hi, y_hi, crop_origin, down_factor):
    origin_x, origin_y = crop_origin[0], crop_origin[1]
    return origin_x + x_hi * down_factor, origin_y + y_hi * down_factor


def _wf_column_top_bottom_y(hi_img, x0, x1, margin=5, cargo_mask=None, profile=None):
    """v25.91 FIX: mirror ของ _wf_column_height (ดู docstring เต็มที่นั่นสำหรับหลักฐาน+เหตุผล) -
    รับ cargo_mask/profile ที่คำนวณไว้แล้วเป็น optional parameter กัน flood-fill ซ้ำซ้อนตอนวาด
    กรอบ marker ของแต่ละ risk (เดิมเรียกซ้ำทุกครั้งที่วาดกรอบ - ยิ่งมี risk หลายจุดยิ่งช้าทวีคูณ)"""
    if cargo_mask is None:
        cargo_mask, _dark = build_wireframe_cargo_mask(hi_img)
    if profile is None:
        bottom_y, top_y = _wf_profile(cargo_mask)
    else:
        bottom_y, top_y = profile
    xa, xb = int(x0) + margin, int(x1) - margin
    if xb <= xa:
        return None, None
    ys_top = [top_y[x] for x in range(xa, xb) if 0 <= x < len(top_y) and top_y[x] >= 0]
    ys_bot = [bottom_y[x] for x in range(xa, xb) if 0 <= x < len(bottom_y) and bottom_y[x] >= 0]
    if not ys_top or not ys_bot:
        return None, None
    return float(np.median(ys_top)), float(np.median(ys_bot))


def _wf_pos_to_hi_pixel_range(pos_range, x_min, x_max, view_label, flip=None):
    if flip is None:
        flip = (view_label == "FRONT")
    p0, p1 = pos_range
    span = x_max - x_min
    if flip:
        raw_p0, raw_p1 = 1.0 - p1, 1.0 - p0
    else:
        raw_p0, raw_p1 = p0, p1
    return x_min + raw_p0 * span, x_min + raw_p1 * span


def run_wireframe_analysis_on_image(pdf_bytes, full_img, doc, page, diagram_page_idx,
                                    matrix_scale=3, hi_scale=8, drop_ratio_thresh=0.20):
    """เทียบเท่า run_full_analysis_on_image() เดิม แต่สำหรับ wireframe -
    คืนค่ารูปแบบเดียวกัน (dict มี key 'risks' เป็น list ของ risk dict ที่มี
    'abs_box' คำนวณไว้ตรงจุดแล้ว - ให้ process_request เดิมเรียกวาด marker
    ได้เหมือนกันทุกประการ ไม่ต้องแก้ logic การวาด/นับ hazardCount เลย)"""
    down_factor = matrix_scale / hi_scale
    view_data = {}
    for view_label, view_name in [("FRONT", "front"), ("BACK", "back")]:
        region, origin, _ = get_view_region(full_img, doc, view_name, page_idx=diagram_page_idx)
        hi_img, _down_factor_check = render_hires_crop(page, origin, main_scale=matrix_scale, hi_scale=hi_scale)
        cargo_mask, dark = build_wireframe_cargo_mask(hi_img)
        # v25.91 FIX (สำคัญ - แก้ HTTP timeout, ดู docstring เต็มที่ _wf_column_height):
        # คำนวณ profile (_wf_profile) 'ครั้งเดียว' ตรงนี้ แล้วส่งต่อ cargo_mask+profile ให้ทุก
        # ฟังก์ชันย่อยที่ต้องการ (build_stack_records_wireframe, _wf_column_top_bottom_y ตอนวาด
        # marker) แทนที่จะปล่อยให้แต่ละฟังก์ชันคำนวณ flood-fill (build_wireframe_cargo_mask) ซ้ำ
        # ใหม่ทุกครั้งที่ถูกเรียก (เดิมถูกเรียกซ้ำ 1 ครั้งต่อคอลัมน์ - วัดเวลาจริงได้ 14.75 วินาที
        # สำหรับวิวเดียวที่มี 8 คอลัมน์ ก่อนแก้ไขนี้)
        profile = _wf_profile(cargo_mask)
        seams_result = find_wireframe_seams_v5(hi_img, cargo_mask)
        records = build_stack_records_wireframe(seams_result, hi_img, view_label,
                                                 cargo_mask=cargo_mask)
        # v25.92: ใช้กลไก EMPTY_SPACE_RISK ใหม่ (verified_box_mask จาก
        # front_face+roof_face) แทน bucket_color_wireframe/find_wireframe_
        # notch_risk_3d เดิม (v25.90/91) ที่พิสูจน์แล้วว่าตรวจไม่พบอะไรเลย
        # - ดู CHANGELOG เต็มที่จุดนิยามฟังก์ชันด้านบนสำหรับหลักฐาน+เหตุผล
        wf_front_faces, wf_roof_faces = _wf_get_all_box_faces(seams_result)
        wf_verified_mask = _wf_build_verified_box_mask(hi_img, wf_front_faces, wf_roof_faces)
        notch_risks = find_wireframe_notch_risk_verified(
            seams_result, wf_front_faces, wf_roof_faces, wf_verified_mask)
        view_data[view_label] = {
            "hi_img": hi_img, "origin": origin, "seams_result": seams_result,
            "records": records, "notch_risks": notch_risks,
            "cargo_mask": cargo_mask, "profile": profile,
        }

    records_front = view_data["FRONT"]["records"]
    records_back = view_data["BACK"]["records"]
    height_risks = detect_wireframe_cross_view_height_mismatch(
        records_front, records_back, drop_ratio_thresh=drop_ratio_thresh)

    risks = []
    for hr in height_risks:
        front_idx = hr["front_idx"]
        front_vd = view_data["FRONT"]
        back_vd = view_data["BACK"]

        fx0_hi, fx1_hi = records_front[front_idx]["x_range"]
        top_y_hi, bot_y_hi = _wf_column_top_bottom_y(
            front_vd["hi_img"], fx0_hi, fx1_hi,
            cargo_mask=front_vd["cargo_mask"], profile=front_vd["profile"])
        if top_y_hi is None:
            top_y_hi, bot_y_hi = 0, front_vd["hi_img"].shape[0]
        fx0, fy0 = _wf_hi_to_full_page(fx0_hi, top_y_hi, front_vd["origin"], down_factor)
        fx1, fy1 = _wf_hi_to_full_page(fx1_hi, bot_y_hi, front_vd["origin"], down_factor)
        risks.append({
            "risk_type": "STEP_DOWN_RISK", "subtype": "wireframe_cross_view",
            "mark_view": "FRONT", "abs_box": (fx0, fy0, fx1, fy1),
            "drop_ratio": hr["drop_ratio"],
        })

        back_seams = back_vd["seams_result"]
        bx0_hi, bx1_hi = _wf_pos_to_hi_pixel_range(
            hr["pos_range"], back_seams["x_min"], back_seams["x_max"], "BACK")
        top_y_hi_b, bot_y_hi_b = _wf_column_top_bottom_y(
            back_vd["hi_img"], bx0_hi, bx1_hi,
            cargo_mask=back_vd["cargo_mask"], profile=back_vd["profile"])
        if top_y_hi_b is None:
            top_y_hi_b, bot_y_hi_b = 0, back_vd["hi_img"].shape[0]
        bx0, by0 = _wf_hi_to_full_page(bx0_hi, top_y_hi_b, back_vd["origin"], down_factor)
        bx1, by1 = _wf_hi_to_full_page(bx1_hi, bot_y_hi_b, back_vd["origin"], down_factor)
        risks.append({
            "risk_type": "STEP_DOWN_RISK", "subtype": "wireframe_cross_view",
            "mark_view": "BACK", "abs_box": (bx0, by0, bx1, by1),
            "drop_ratio": hr["drop_ratio"],
        })

    for view_label in ["FRONT", "BACK"]:
        vd = view_data[view_label]
        origin = vd["origin"]
        for nr in vd["notch_risks"]:
            x0_hi, x1_hi = nr["x_range"]
            y0_hi, y1_hi = nr["y_range"]
            nx0, ny0 = _wf_hi_to_full_page(x0_hi, y0_hi, origin, down_factor)
            nx1, ny1 = _wf_hi_to_full_page(x1_hi, y1_hi, origin, down_factor)
            risks.append({
                "risk_type": "EMPTY_SPACE_RISK", "subtype": "wireframe_silhouette_notch",
                "mark_view": view_label, "abs_box": (nx0, ny0, nx1, ny1),
            })

    return {
        "risks": risks,
        "front_n_columns": view_data["FRONT"]["seams_result"]["n_columns"],
        "back_n_columns": view_data["BACK"]["seams_result"]["n_columns"],
    }


# ============================================================================
# ค่าคงที่ / สี marker (คงไว้ตามเดิมสำหรับ 3 risk types ที่เหลือ)
# ============================================================================

RISK_COLORS = {
    "STEP_DOWN_RISK": "red",
    "EMPTY_SPACE_RISK": "orange",
}
VALID_RISK_TYPES = set(RISK_COLORS.keys())

# กฎ 3 ข้อ ชัดเจน เกณฑ์เดียวต่อกฎ (ปรับตัวเลขได้ที่นี่จุดเดียว):
# 1) STEP_DOWN_RISK (cross_view): gap > 20% ระหว่างตำแหน่งคู่ตรงข้าม FRONT<->BACK -> วาดกรอบตัวสูงกว่า
# 2) STEP_DOWN_RISK (pairwise)  : gap > 20% ระหว่างตั้งติดกัน แนวระนาบเดียวกัน -> วาดกรอบตัวสูงกว่า
# 3) REAR_EMPTY_RISK            : gap > 7% ระหว่างความยาวรวมของแต่ละ view -> วาดกรอบท้ายสุดของ view ที่ยาวกว่า
# ทั้ง 3 กฎ ข้าม record ที่ is_corner_duplicate=True เสมอ (ตรวจจาก pixel/เรขาคณิตจริง ไม่ hardcode ชื่อ view)
STEP_DOWN_CROSSVIEW_DROP_RATIO = 0.20
STEP_DOWN_PAIRWISE_DROP_RATIO = 0.20
TAIL_STEPDOWN_DROP_RATIO = 0.12
TAIL_STEPDOWN_REAR_POS_MIN = 0.85
# v25.48 NEW (สำคัญ - พบจริงจาก AA05-03 ที่ผู้ใช้แนบ): STEP_DOWN_RISK (ทั้ง pairwise และ
# cross_view) เดิมเชื่อค่า height_px ที่มาจาก "direct" fit เสมอ โดยไม่สนใจว่า fit นั้นมีจุดข้อมูล
# (n_samples) มากพอจะเชื่อถือได้หรือไม่ - พบว่าไฟล์ AA05-03 BACK idx4 (คอลัมน์ขวาสุด) วัดความสูงได้
# แค่ 212.4px (ต่ำกว่าเพื่อนบ้าน idx3 ที่ 274.8px ถึง 22.7% -> เกิน threshold 20% -> flag ผิดพลาด)
# ตรวจสอบพบว่า n_samples ของ idx4 มีเพียง 19 จุด (เทียบเพื่อนบ้านที่มี 73-97 จุด) เพราะ apex_x
# (จุดเปลี่ยน slope ของพื้นตู้ isometric) ตกอยู่ "ภายใน" ช่วงคอลัมน์นี้พอดี (x=1157 อยู่ในช่วง
# 1132-1226) ทำให้ eff_b1=min(b1,apex_x) ตัดข้อมูลที่ใช้ fit เหลือแค่ 19px แคบๆ ก่อนถึง apex -
# การ fit เส้นด้วยจุดน้อยมากขนาดนี้ใกล้จุดเปลี่ยน slope พอดี ไม่น่าเชื่อถือพอจะสรุปว่ากล่องนี้
# "เตี้ยกว่าจริง" (ยืนยันด้วยภาพจริง: ผู้ใช้ระบุว่ากล่องขวาสุดสูงใกล้เคียงกับเพื่อนบ้าน ไม่ควรตีกรอบ)
# FIX: เพิ่มเกณฑ์ขั้นต่ำของ n_samples ก่อนยอมรับว่า height_px "เชื่อถือได้พอจะใช้เป็นฝั่งที่
# 'เตี้ยกว่า' ในการ flag ความเสี่ยง" - ถ้า n_samples ของฝั่งที่เตี้ยกว่าต่ำกว่าเกณฑ์นี้ (และค่า
# height_px ยังไม่เคยถูกยืนยันซ้ำจาก cross-view ผ่าน height_source อื่น) จะไม่ flag ความเสี่ยงคู่
# นั้น (ปลอดภัยกว่าการเดา - ตรงกับหลักการเดิมของระบบที่ "ซื่อสัตย์ว่าไม่รู้" ดีกว่า "มั่นใจผิด")
# ตรวจสอบแล้วว่าไม่กระทบไฟล์อื่น: คอลัมน์ที่เตี้ยกว่าจริงทุกไฟล์ที่ทดสอบ (AA02-01 idx5 n=66,
# AA05-03 idx0 n=96 ฯลฯ) มี n_samples สูงกว่าเกณฑ์นี้มาก ไม่ถูกกระทบ
STEP_DOWN_MIN_RELIABLE_SAMPLES = 25

# v25.48 NEW (สำคัญ - พบจริงจาก AA02-01 ที่ผู้ใช้แนบ หลังแก้ orphaned-roof แล้วยังพบกรอบแดง
# ผิดพลาดที่ตำแหน่งเดิม): กล่อง ASI1A (สีน้ำเงินล้วน ทุกตำแหน่งเป็น SKU เดียวกัน มองด้วยตาจริง
# ในภาพสูงเท่ากันทุกตั้งทั้ง FRONT และ BACK) แต่วัดได้ FRONT idx0=154.2px, idx1=214.2px
# (ต่างกัน 28%) - ตรวจสอบพบว่าค่าดิบก่อน reconcile ของ BACK ฝั่งเดียวกัน (apex_fallback)
# กลับใกล้เคียงกันมากกว่ามาก (270.7 vs 230.7 = 15%) แต่ reconcile เลือกเชื่อ FRONT (direct)
# เพราะอยู่ใน "reliable" hierarchy สูงกว่า apex_fallback เสมอ โดยไม่ดูว่าความขัดแย้งเดิม
# (conflict, ก่อนแก้ไข) รุนแรงแค่ไหน - ความขัดแย้งที่นี่สูงถึง 20.9%/33.2% (คำนวณจาก
# cross_view_conflict_ratio) ซึ่งมากกว่าปกติมาก บ่งชี้ว่าการวัดฝั่งใดฝั่งหนึ่ง (หรือทั้งคู่)
# มี noise สูงจากรอยต่อ isometric slope ระหว่างกล่อง SKU เดียวกันที่วางชิดกัน (ไม่ใช่กล่อง
# เตี้ยกว่าจริง) - เกณฑ์ความน่าเชื่อถือแบบ n_samples (STEP_DOWN_MIN_RELIABLE_SAMPLES) ตรวจจับ
# ไม่ได้ในกรณีนี้เพราะ FRONT idx0/idx1 มี n_samples เต็ม (107 ทั้งคู่) - ต้องใช้สัญญาณคนละตัว
# FIX: ถ้าค่า height_px ของฝั่งที่ "เตี้ยกว่า" ในคู่เปรียบเทียบ มาจาก cross_view_corrected ที่มี
# cross_view_conflict_ratio สูงเกินเกณฑ์นี้ (บ่งชี้ว่า FRONT/BACK เห็นไม่ตรงกันมากก่อนแก้ไข -
# ค่าที่ใช้จริงไม่ใช่ค่าที่ทั้ง 2 view เห็นพ้องต้องกัน) ให้ถือว่าไม่น่าเชื่อถือพอจะ flag ความเสี่ยง
# (เช่นเดียวกับหลักการของ STEP_DOWN_MIN_RELIABLE_SAMPLES - ปลอดภัยกว่าการเชื่อค่าที่มีข้อขัดแย้ง
# สูงระหว่าง 2 มุมกล้องอย่างมั่นใจเกินไป)
STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO = 0.15
# v25.49 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้แนบ): เดิม reconcile_heights_cross_view PASS2
# (ดูฟังก์ชัน reconcile_heights_cross_view) เชื่อ "reliability hierarchy" (direct > apex_fallback)
# เสมอเมื่อตัดสินว่าจะเขียนทับค่าฝั่งไหน โดยไม่สนใจว่า "ขนาดของความขัดแย้งเดิม (conflict_mag)"
# สูงผิดปกติแค่ไหน - พบว่าไฟล์ AB03-04 มีคู่ FRONT idx2 (ASI1A-AJ ชั้นเดียว, apex_fallback,
# height=121.17px) vs BACK idx0 (เห็น TEP1A-AJ ซ้อนอยู่อีกชั้นบน ASI1A-AJ จริงจากมุมกล้องนั้น,
# direct, height=269.9px) conflict_mag=55.1% - สูงกว่าทุกเคส "noise ที่คาลิเบรตไว้แล้วว่าควรแก้"
# มาก (AA02-01 สูงสุดที่เคยยืนยันว่าเป็น noise จริงคือ 33.2%) - ระบบยังคง "เชื่อ direct" แล้วเขียน
# ทับ FRONT idx2 เป็น 269.9 ทั้งที่เป็นความแตกต่างทางกายภาพจริง (กล่องคนละความสูงจริงที่ตำแหน่งนี้
# ไม่ใช่ noise) ทำให้ทั้ง 2 ฝั่งถูกทำให้เท่ากันไปก่อน detect_step_down_crossview จะได้เปรียบเทียบ
# -> STEP_DOWN_RISK ที่ควรพบไม่ถูกตรวจพบเลย (หลักฐานถูกลบไปแล้วตั้งแต่ขั้น reconcile)
# ROOT CAUSE: ไม่มีเพดานบนใดๆ กัน "ขนาดของความขัดแย้ง" เอาไว้เลย - ระบบแก้ไข conflict ทุกขนาด
# เท่ากันหมด (แค่ 10.01% ก็แก้ไขเหมือนกับ 55% เป๊ะ) ทั้งที่ในทางสถิติ ยิ่งขัดแย้งกันสูงมาก ยิ่งไม่น่า
# เป็น "measurement noise ธรรมดา" (ซึ่งควรมีขนาดจำกัด) และยิ่งน่าจะเป็นความจริงทางกายภาพมากกว่า
# FIX: เพิ่มเพดานบน - ถ้า conflict_mag เกิน RECONCILE_MAX_CONFLICT_TO_APPLY ให้ "ไม่แก้ไขเลย" (ข้าม
# proposal นี้ไปทั้งคู่ คงค่าเดิมทั้ง 2 ฝั่งไว้) ปล่อยให้ detect_step_down_crossview/pairwise ทำงาน
# กับค่าจริงที่วัดได้ตามปกติแทน - ตั้งค่าไว้ที่ 0.40 (สูงกว่า 33.2% ที่เคยยืนยันว่าเป็น noise จริง
# ของ AA02-01 มากพอสมควร กันไม่ให้กระทบเคสที่คาลิเบรตไว้แล้ว) และต่ำกว่า 55.1% ของ AB03-04 มากพอ
# ที่จะจับเคสใหม่นี้ได้ - regression-verified: AA02-01 (conflict 20.9%/33.2%) ยังคงถูก correct
# เหมือนเดิมทุกประการเพราะต่ำกว่า 40%
RECONCILE_MAX_CONFLICT_TO_APPLY = 0.40
REAR_EMPTY_LENGTH_RATIO = 0.07
CROSSVIEW_MIN_OVERLAP_RATIO = 0.5       # ต้องทับซ้อนตำแหน่งจริงอย่างน้อย 50% จึงถือเป็นคู่เดียวกัน

# --- STEP_DOWN_RISK (hidden_behind) v25.23 NEW ---
# กรณีพิเศษที่ 3 กฎเดิมตรวจไม่พบ: กล่องที่ "ซ่อนอยู่แถวหลัง" (ข้ามความกว้างตู้ 2400mm อีกแถว
# ที่ตำแหน่งความยาวเดียวกัน) สูงกว่ากล่องแถวหน้าที่บังอยู่ - สังเกตได้จาก "top-face bleed-
# through": หลังคา (roof) ของกล่องหลังโผล่พ้นกล่องหน้าขึ้นมา ทำให้ cargo_top_y ในคอลัมน์
# เดียวกัน (front-face column เดิมจาก Phase 1B) กระโดดขึ้นกะทันหัน (แคบกว่า 3-5px) กลางคอลัมน์
# แทนที่จะค่อยๆลาดตามธรรมชาติของมุมมอง isometric (ดูหลักฐาน pixel จริงจาก AE02-01 FRONT
# idx4 และ BACK idx1 ที่ยืนยันแล้วในบทสนทนา - ทั้งคู่มี jump แนวตั้งคมชัด 28-50px ภายใน
# ระยะแนวนอนแค่ 3px พร้อมทั้ง 2 ฝั่งของ jump มีค่าเรียบนิ่งมาก (std<2px) ตรงข้ามกับความชัน
# ธรรมชาติของ isometric slope ที่ลาดต่อเนื่องนุ่มนวลกว่ามาก)
# เกณฑ์ (ปรับตัวเลขได้ที่นี่จุดเดียว): ต้องกระโดดขึ้นอย่างน้อย HIDDEN_BEHIND_MIN_JUMP_PX พิกเซล
# ภายในหน้าต่างแคบๆ (win พิกเซล) และทั้ง 2 ฝั่งต้องนิ่ง (std <= HIDDEN_BEHIND_MAX_SIDE_STD)
# เพื่อแยกแยะจาก noise ของตัวอักษร SKU/isometric slope ธรรมชาติ (ยืนยันแล้วว่าเกณฑ์นี้แยก
# กรณีจริง (AE02-01 FRONT idx4, BACK idx1) ออกจาก false-positive ที่พบระหว่างพัฒนา (FRONT
# idx6 - ขอบขวาสุดที่มี isometric slope + label noise ธรรมชาติ - Lstd ขึ้นสูงถึง ~26 เทียบ
# กับกรณีจริงที่ Lstd<1 เสมอ)
STEP_DOWN_HIDDEN_BEHIND_MIN_JUMP_PX = 20
STEP_DOWN_HIDDEN_BEHIND_MAX_SIDE_STD = 6.0
STEP_DOWN_HIDDEN_BEHIND_WIN = 6
STEP_DOWN_HIDDEN_BEHIND_MARGIN = 3
STEP_DOWN_HIDDEN_BEHIND_MIN_SEG = 8
# v25.70 NEW: เกณฑ์ signal/noise ratio ขั้นต่ำสำหรับทิศทาง "down" เท่านั้น (ดู docstring เต็มที่
# _detect_hidden_behind_split - พบจริงจาก RD01-01 false-positive vs EE03-01 true-positive)
_HIDDEN_BEHIND_DOWN_MIN_SNR = 15.0  # อยู่กึ่งกลาง (geometric mean) ระหว่าง RD01-01=4.2 (ต้อง
# กรองออก) และ EE03-01=42.5 (ต้องผ่าน) - ให้ margin ปลอดภัยกับทั้ง 2 ฝั่ง (3.6x จาก false-
# positive, ต่ำกว่า true-positive เกือบ 3 เท่า)
_HIDDEN_BEHIND_DOWN_MAX_FLOOR_JUMP_PX = 10.0  # v25.70 NEW: floor ต้องนิ่งไม่เกินนี้ (ดู
# docstring เต็มที่ _detect_hidden_behind_split - พบจริงจาก ED86-03 floor jump=26px ต้องกรอง
# ออก vs EE03-01 floor jump=1px ต้องผ่าน - เลือก 10px ให้ margin ปลอดภัยกับทั้ง 2 ฝั่ง)

# --- REAR_EMPTY_RISK v2 (แก้บั๊ก v25.0: pos_range เดิม self-normalize ทำให้ตั้งสุดท้าย
#     ของทุก view ได้ pos=1.0 เสมอ ทำให้ position-overlap matching ผิดพลาดเป็นระบบ) ---
