_INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES = 25


def _recheck_stack_height_via_color(view_result, x_range, expected_color,
                                     margin=_RECHECK_COLOR_MARGIN_PX,
                                     min_points=_RECHECK_COLOR_MIN_POINTS,
                                     max_resid_std=_RECHECK_COLOR_MAX_RESID_STD):
    """ตรวจสอบซ้ำ (recheck) ความสูงของคอลัมน์ที่ตำแหน่ง x_range โดยกรองเฉพาะ pixel ที่สีตรงกับ
    expected_color เท่านั้น (สแกนทั้งความกว้างคอลัมน์ หาจุดบนสุดที่สีตรงในแต่ละ x แล้ว fit เส้นตรง
    ทนทาน - เทคนิคเดียวกับ _scan_full_column ใน detect_step_down_topface_jump) คืนค่า
    (height_px, n_points, resid_std) ถ้า fit น่าเชื่อถือ หรือ None ถ้าไม่พอจะเชื่อผล (fail-safe)
    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก AB03-04)"""
    region = view_result.get("region")
    cargo_mask = view_result.get("cargo_mask")
    local_floor_y = view_result.get("local_floor_y")
    if region is None or cargo_mask is None or local_floor_y is None:
        return None
    norm_expected = _stack_color_normalize(np.array(expected_color, dtype=np.float64))
    if norm_expected is None:
        return None
    x0, x1 = x_range
    lo = max(0, x0 + margin)
    hi = min(region.shape[1], x1 - margin)
    xs, ys = [], []
    for x in range(lo, hi):
        col_ys = np.nonzero(cargo_mask[:, x])[0]
        if len(col_ys) == 0:
            continue
        best_y = None
        for y in col_ys:
            pixel = region[y, x]
            if is_arrow_color(pixel):
                continue
            cur = _stack_color_normalize(pixel)
            if cur is None:
                continue
            if float(np.sqrt(np.sum((cur - norm_expected) ** 2))) <= _STACK_COLOR_MATCH_HUE_TOL:
                if best_y is None or y < best_y:
                    best_y = int(y)
        if best_y is not None:
            xs.append(x)
            ys.append(best_y)
    if len(xs) < min_points:
        return None
    fit = _robust_local_line_fit(xs, ys)
    if fit is None or fit["resid_std"] > max_resid_std:
        return None
    xm = (x0 + x1) // 2
    top_y = fit["a"] * xm + fit["b"]
    if xm < 0 or xm >= len(local_floor_y) or local_floor_y[xm] < 0:
        return None
    floor_y = float(local_floor_y[xm])
    h = floor_y - top_y
    if h <= 0:
        return None
    return h, len(fit["xs"]), fit["resid_std"]


def _robust_local_line_fit(xs, ys, mad_floor=2.0, n_iter=3):
    """Fit เส้นตรง y=a*x+b แบบทนทานต่อ outlier (label/ลูกศร) โดยใช้ iterative
    MAD-based rejection - mad_floor ป้องกันกรณีข้อมูลเรียบสมบูรณ์แบบ (MAD~0)"""
    xs = np.asarray(xs, dtype=float)
    ys = np.asarray(ys, dtype=float)
    if len(xs) < 3:
        if len(xs) == 0:
            return None
        return {"a": 0.0, "b": float(np.mean(ys)), "resid_std": 0.0, "xs": xs, "ys": ys}
    a, b = 0.0, float(np.mean(ys))
    for _ in range(n_iter):
        if len(xs) < 3:
            break
        A = np.vstack([xs, np.ones_like(xs)]).T
        a, b = np.linalg.lstsq(A, ys, rcond=None)[0]
        resid = ys - (a * xs + b)
        mad = max(mad_floor, np.median(np.abs(resid - np.median(resid))))
        keep = np.abs(resid) < 3 * mad
        if keep.sum() < 3 or keep.sum() == len(xs):
            break
        xs, ys = xs[keep], ys[keep]
    resid = ys - (a * xs + b)
    return {"a": float(a), "b": float(b), "resid_std": float(resid.std()), "xs": xs, "ys": ys}


def detect_isometric_apex(cargo_top_y, local_floor_y, start_x, end_x, search_margin_ratio=0.15,
                           smooth_window=11, slope_thresh=0.15):
    """หาตำแหน่ง 'จุดยอด (apex)' ของ silhouette กองกล่องในมุมมอง isometric - ก่อนจุดยอด
    cargo_top_y คือขอบบน-หลัง (ขนานพื้น, height ถูกต้อง) หลังจุดยอดกลายเป็นขอบบน-หน้า (เอียง
    คนละทิศ, height ผิดเพี้ยนเป็นระบบ) ยืนยันด้วยภาพจริงและ cross-view ในไฟล์ทดสอบ

    v25.21 FIX (Critical - "Apex Hijack by Elevated Stack"):
    เดิมใช้ argmin(cargo_top_y) ซึ่งเลือกจุด y ต่ำสุด (= กล่องสูงสุดในภาพ) เป็น apex
    -> กล่องที่ซ้อนสูงผิดปกติ (เช่น สีแดงชั้น 3 ใน AE02-01/02) ถูกเลือกเป็น apex แทน
    -> eff_b1 = min(b1, apex_x) ทำให้ stack ทั้งหมดที่อยู่ทางขวาของกล่องนั้น
       ถูกตัด xs_top=[] -> height_px=None ทั้งหมด -> carry-forward ให้ค่าเท่ากัน
       -> STEP_DOWN_RISK ตรวจไม่พบเลย

    FIX: ใช้ slope-change detection แทน argmin()
    apex จริงของตู้ isometric = จุดที่ slope ของ cargo_top_y เปลี่ยนจาก
    "ลาดลงทางขวา (negative)" เป็น "ลาดขึ้นทางขวา (positive)" ในช่วงยาวพอ (V-shape จริง)
    กล่องสูงผิดปกติสร้าง "dip" สั้นๆ เท่านั้น ไม่ใช่ V-shape ยาว -> ตรวจแยกได้
    ถ้าไม่พบ V-shape -> คืน None (ไม่ตัด data = ปลอดภัยกว่าการตัดผิดพลาด)

    regression-verified: ไฟล์ที่ cargo มีลักษณะ slope คงที่ (ไม่มี V-shape ชัดเจน)
    จะได้ apex=None ไม่ตัด data -> ไม่กระทบผลลัพธ์เดิม
    """
    span = end_x - start_x
    if span <= 0:
        return None
    search_start = start_x + int(span * search_margin_ratio)
    xs = np.arange(search_start, min(end_x + 1, len(cargo_top_y)))
    if len(xs) == 0:
        return None
    vals = cargo_top_y[xs]
    valid_mask = vals >= 0
    if np.sum(valid_mask) < 20:
        return None

    xs_v = xs[valid_mask]
    ys_v = vals[valid_mask].astype(float)

    # smooth ก่อน detect slope-change (ลด noise จากขอบกล่องและ label text)
    half = smooth_window // 2
    smoothed = np.empty(len(ys_v))
    for i in range(len(ys_v)):
        lo, hi = max(0, i - half), min(len(ys_v), i + half + 1)
        smoothed[i] = float(np.median(ys_v[lo:hi]))

    n = len(smoothed)
    if n < 20:
        return None

    # หา V-shape: ต้องมี left slope negative + right slope positive ด้วย window ใหญ่พอ
    # (กล่องสูงผิดปกติสร้าง dip สั้น ~window_size เท่านั้น ไม่ใช่ V ยาวเต็ม half span)
    best_score = -1.0
    best_idx = None
    min_window = max(n // 8, 5)   # ต้องมี slope ยาวพอ (>= 1/8 ของ span) ทั้งสองข้าง

    for mid in range(min_window, n - min_window):
        left_win = min(mid, n // 4)
        right_win = min(n - mid - 1, n // 4)
        if left_win < min_window or right_win < min_window:
            continue
        left_slope = (smoothed[mid] - smoothed[mid - left_win]) / max(left_win, 1)
        right_slope = (smoothed[mid + right_win] - smoothed[mid]) / max(right_win, 1)
        if left_slope < -slope_thresh and right_slope > slope_thresh:
            score = (-left_slope) + right_slope
            if score > best_score:
                best_score = score
                best_idx = mid

    if best_idx is None:
        return None  # ไม่พบ V-shape จริง -> ไม่ตัด data (ปลอดภัยกว่า)
    return int(xs_v[best_idx])


def compute_stack_heights_px(seams, start_x, end_x, cargo_top_y, margin=6, local_floor_y=None):
    """คำนวณความสูง (px) ต่อ 1 ตั้ง โดย fit เส้นตรงทนทาน (robust local line) ให้กับ
    cargo_top_y ภายในแต่ละตั้งเอง (แก้บั๊กความชันธรรมชาติจากมุมมอง isometric) แล้วประเมิน
    ความสูงที่ตำแหน่งกึ่งกลางตั้ง เทียบกับ local floor (แก้บั๊กพื้นตู้รูปตัว V)

    v25.2 FIX: ตัดข้อมูลที่อยู่ "หลังจุดยอด isometric" (apex) ออกจากการคำนวณ - สำหรับตั้งที่
    อยู่หลัง apex ทั้งตั้ง (วัดเองไม่ได้เลย) จะคืนค่า height_px=None ก่อน ให้ cross-view
    reconciliation เติมค่าจากอีกมุมมองก่อน แล้วค่อย carry-forward เป็นทางเลือกสุดท้าย"""
    boundaries = [start_x] + sorted(seams) + [end_x]
    results = []

    def _floor_at(x):
        if local_floor_y is not None and 0 <= x < len(local_floor_y) and local_floor_y[x] >= 0:
            return local_floor_y[x]
        return None

    apex_x = detect_isometric_apex(cargo_top_y, local_floor_y, start_x, end_x)

    for i in range(len(boundaries) - 1):
        b0 = boundaries[i] + margin
        b1 = boundaries[i + 1] - margin
        eff_b1 = b1
        # v25.72 FIX (สำคัญ - พบจริงจาก AB03-04 หลัง v25.71 เพิ่ม blanket apex_fallback guard):
        # เดิม eff_b1 = min(b1, apex_x) แบบไม่มีเงื่อนไข - ถ้า apex_x <= b0 (คอลัมน์นี้ทั้งคอลัมน์
        # อยู่ "หลัง apex" ทั้งหมด ไม่มีส่วนใดก่อน apex เลย) จะได้ eff_b1 <= b0 -> ช่วง
        # range(b0, eff_b1) ว่างเปล่าเสมอ -> ทุกครั้งต้องเข้า apex_cut_fallback branch (ใช้ [b0,b1]
        # เต็มช่วง) แต่ผลลัพธ์ตัวเลขที่ได้เหมือนกับการ "ไม่มี apex logic เลย" (apex_x=None) ทุก
        # ประการ (n_samples = b1-b0 พอดี ไม่ใช่ค่าคงที่ผิดปกติแบบ ED84/ED85 ที่ n=67 ซ้ำกันข้าม
        # ไฟล์) - แต่กลับถูกติดป้าย "apex_fallback" อย่างผิดพลาด ทำให้ v25.71 blanket-guard (ที่ออกแบบ
        # มาสำหรับกรณี apex อยู่ "กลางคอลัมน์" ตัดข้อมูลจนเหลือน้อยผิดปกติ) ไปกรอง exclude กรณีนี้ด้วย
        # ทั้งที่เป็นการวัดที่เชื่อถือได้เต็มรูปแบบ (ยืนยันจาก AB03-04: idx2 (กล่องน้ำเงิน ASI1A-AJ
        # ชั้นเดียว, x=1110-1240) มี apex_x=1000 ซึ่งอยู่ก่อนคอลัมน์นี้ทั้งหมด (apex_x <= b0=1116)
        # -> n_samples=118 = ความกว้างคอลัมน์เป๊ะ ไม่ใช่ค่าคงที่แปลกๆ - ถูกกรองออกผิดพลาด ทำให้พลาด
        # STEP_DOWN_RISK จริงระหว่าง idx1 (เขียว/ฟ้า สูง) กับ idx2 (น้ำเงิน เตี้ย) ไป
        # FIX: cut ด้วย apex เฉพาะเมื่อ apex_x ตกอยู่ "ภายใน" ช่วงคอลัมน์นี้จริง (b0 < apex_x < b1)
        # เท่านั้น - ถ้า apex_x <= b0 (ทั้งคอลัมน์อยู่หลัง apex) หรือ apex_x >= b1 (ทั้งคอลัมน์อยู่
        # ก่อน apex, ไม่ต้องตัดอยู่แล้วเดิมก็ไม่เปลี่ยน) ให้ใช้ [b0,b1] เต็มช่วงตั้งแต่รอบแรกเลย
        # (ไม่ต้องผ่าน apex_cut_fallback branch อีกต่อไป) -> height_source ได้ "direct" ถูกต้องตาม
        # ความเป็นจริงของข้อมูล ไม่กระทบตัวเลขความสูงที่คำนวณได้เลย (ค่าเหมือนเดิมทุกประการ เปลี่ยน
        # แค่ label ความน่าเชื่อถือ) - ไม่กระทบกรณี apex อยู่กลางคอลัมน์จริง (b0<apex_x<b1) ที่ยังคง
        # ตัดข้อมูลแล้วอาจ fallback เป็น apex_fallback เหมือนเดิมทุกประการ (เช่น ED84/ED85 ที่ยืนยัน
        # แล้วว่าเป็น geometric artifact จริง - n_samples คงที่ผิดธรรมชาติข้ามไฟล์)
        apex_mid_cut = apex_x is not None and b0 < apex_x < b1
        if apex_mid_cut:
            eff_b1 = apex_x

        xs_top, ys_top = [], []
        for x in range(max(0, b0), max(0, eff_b1)):
            if x < len(cargo_top_y) and cargo_top_y[x] >= 0:
                xs_top.append(x)
                ys_top.append(cargo_top_y[x])

        # v25.21 FIX: ถ้า apex-cut ทำให้ xs_top=[] (eff_b1 <= b0 เพราะ apex_x น้อยกว่า b0)
        # -> fallback ใช้ cargo_top_y ทั้ง stack โดยไม่ตัด apex (ยอมรับ noise จาก isometric
        # slope แต่ดีกว่า height=None ที่ทำให้ carry-forward ให้ค่าเท่ากันหมด -> ไม่พบ STEP_DOWN)
        # ตัวอย่างที่ fix: AE02-01 BACK กล่องแดงชั้น 3 อยู่ฝั่งซ้าย -> apex_x เล็ก -> stack
        # ทุกตัวทางขวา xs_top=[] -> height=None -> carry-forward -> ไม่พบ STEP_DOWN
        apex_cut_fallback = False
        if len(xs_top) < 3 and b1 > b0:
            # ใช้ช่วงเต็ม [b0..b1] ไม่ตัด apex (fallback)
            xs_top, ys_top = [], []
            for x in range(max(0, b0), max(0, b1)):
                if x < len(cargo_top_y) and cargo_top_y[x] >= 0:
                    xs_top.append(x)
                    ys_top.append(cargo_top_y[x])
            apex_cut_fallback = True

        top_fit = _robust_local_line_fit(xs_top, ys_top) if xs_top else None

        height_px = None
        n_samples = 0
        height_source = "direct"
        if top_fit is not None and len(xs_top) >= 3:
            eff_mid = (max(0, b0) + (b1 if apex_cut_fallback else eff_b1)) / 2.0
            top_at_mid = top_fit["a"] * eff_mid + top_fit["b"]
            floor_at_mid = _floor_at(int(eff_mid))
            if floor_at_mid is not None:
                height_px = floor_at_mid - top_at_mid
                n_samples = len(top_fit["xs"])
                if apex_cut_fallback:
                    height_source = "apex_fallback"
                elif apex_mid_cut:
                    # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด
                    # ยังมีกรอบแดง คือกรอบซ้ายสุด", 31-Aug-2026): เดิม (v25.72) เมื่อ apex ตัด
                    # ข้อมูลกลางคอลัมน์จริง (apex_mid_cut=True, b0<apex_x<b1) แต่ยังเหลือจุด>=3
                    # จุด จะไม่เข้า apex_cut_fallback branch เลย (apex_cut_fallback=False) ทำให้
                    # ถูกติดป้าย "direct" เหมือนคอลัมน์ปกติทุกประการ โดยไม่คำนึงว่า eff_mid ที่ใช้
                    # ประเมินความสูง (คำนวณจาก [b0, eff_b1=apex_x] ที่ถูกตัดแล้ว) อาจอยู่ใกล้ apex
                    # (จุดสูงสุดของเส้นโค้ง isometric) มากผิดปกติ แทนที่จะอยู่ที่ "จุดกึ่งกลางจริง"
                    # ของคอลัมน์ (ซึ่งควรใช้ [b0,b1] เต็มช่วงเดิม ก่อนตัด apex) - ยืนยันด้วยข้อมูล
                    # จริง AB03-04 FRONT idx1 (x=955-1110, กล่องฟ้า TEP1A-AJ ติดกับกล่องน้ำเงิน):
                    # apex_x=1000 ตัดข้อมูลเหลือ n_samples=39 จาก 143px ที่มีอยู่ (coverage=27.3%)
                    # eff_mid ที่ใช้จริง=980 (ใกล้ apex=1000 มาก) แทนที่จะเป็นจุดกึ่งกลางจริงของ
                    # คอลัมน์ (~1032) ทำให้วัดความสูงได้ 284.5px (ใกล้ยอด/จุดสูงสุดของเส้นโค้ง) สูง
                    # กว่าเพื่อนบ้าน idx0 (x=805-955, กล่องฟ้าเดียวกัน SKU เดียวกัน, eff_mid=880
                    # อยู่กลางคอลัมน์ตัวเองจริง n_samples=138/150=92% coverage) ที่วัดได้ 243.3px
                    # ถึง 14.5% - ทำให้ detect_tail_stepdown flag ผิดพลาดว่ากล่องฟ้าเดียวกันสูงต่ำ
                    # ต่างกัน ทั้งที่ floor_jump ระหว่างทั้งคู่วัดได้แค่ 4.8px (แทบไม่มี - ยืนยันว่า
                    # เป็นพื้นเดียวกันจริง ไม่ใช่คนละแถว/คนละระดับ) และทั้งคู่เป็น SKU เดียวกันเป๊ะ
                    # (TEP1A-AJ ยืนยันจากภาพ + ข้อความบนกล่องซ้ำกัน)
                    # ROOT CAUSE ที่แท้จริง: eff_mid คำนวณจาก eff_b1 (ช่วงที่ถูกตัด apex แล้ว) ทำให้
                    # จุดประเมินความสูงเลื่อนไปใกล้ apex (จุดสูงสุดของเส้นโค้ง isometric ที่เกิดจาก
                    # มุมกล้อง ไม่ใช่ความสูงกล่องจริง) แทนที่จะเป็นจุดกึ่งกลางจริงของคอลัมน์ - ยิ่ง
                    # apex ตัดข้อมูลออกมาก (coverage ต่ำ) ยิ่งเลื่อนจุดประเมินเข้าใกล้ apex มาก
                    # ทำให้ค่าที่วัดได้เอนเอียงสูงขึ้นเป็นระบบ (ไม่ใช่แค่ noise สุ่ม)
                    # FIX: คำนวณ "coverage fraction" (n_samples เทียบกับความกว้างเต็มของคอลัมน์
                    # ก่อนตัด apex, b1-b0) - ถ้าต่ำกว่าเกณฑ์ (_APEX_CUT_MIN_COVERAGE_FRACTION=35%,
                    # แนวคิดเดียวกับ Plateau Span Coverage Guard เดิมของระบบ คือ "ต้องมีข้อมูล
                    # ครอบคลุมเพียงพอจึงจะเชื่อว่าเป็นตัวแทนที่แท้จริงของคอลัมน์") ให้ติดป้าย
                    # "apex_partial_cut" (ระดับความน่าเชื่อถือเดียวกับ apex_fallback) แทน "direct"
                    # - ไม่กระทบตัวเลขความสูงที่คำนวณได้เลย (ค่าเหมือนเดิมทุกประการ เปลี่ยนแค่
                    # label) - ไม่กระทบกรณี apex ตัดข้อมูลแล้วยังเหลือ coverage สูง (>=35%) ซึ่งยัง
                    # คงเชื่อถือได้ตามปกติ (ยังคง "direct" เหมือนเดิม)
                    full_width = max(1, b1 - b0)
                    coverage_frac = n_samples / full_width
                    if coverage_frac < _APEX_CUT_MIN_COVERAGE_FRACTION:
                        height_source = "apex_partial_cut"

        if height_px is None:
            height_source = "unreliable_post_apex"

        results.append({
            "stack_idx": i,
            "x_range": (boundaries[i], boundaries[i + 1]),
            "n_samples": n_samples,
            "height_px": height_px,
            "height_source": height_source,
            "apex_x": apex_x,
        })
    return results


_HIDDEN_BEHIND_UP_MAX_BOTTOM_JUMP_PX = 40  # v25.89 NEW: ดู docstring เต็มที่จุดใช้งานจริงด้านล่าง
# (ทิศทาง 'up') สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01) - ตั้งค่าให้สูงกว่า noise ปกติของขอบกล่อง
# (มักไม่กี่ px) มากพอ แต่ต่ำกว่าความจริงของกรณี ghost-artifact ที่พบ (197px) มาก
# v25.89 FIX (สำคัญ - พบ regression จริงจาก EC05-01 ระหว่าง regression-test เต็มรูปแบบ
# 2-Sep-2026): เดิมเช็คแค่ cargo_bottom_y jump อย่างเดียว (ไม่เช็คสี) - พบว่า EC05-01 FRONT
# idx=4 (genuine hidden_behind จริง ยืนยันด้วยภาพ: กล่องม่วง/ชมพูแถวหน้า TTTCA ถูกกล่องเขียว
# STT1A แถวหลังที่สูงกว่าบัง) ก็มี cargo_bottom_y กระโดดใหญ่เช่นกัน (461->116 = 345px) เพราะ
# "หลังคา" ที่โผล่พ้นมาโดยธรรมชาติจะเห็นแค่ส่วนบนเท่านั้น (ส่วนล่างถูกกล่องแถวหน้าบังไว้เสมอ -
# เป็นลักษณะทางกายภาพปกติของ genuine hidden_behind ไม่ใช่แค่สัญญาณของ ghost artifact) ทำให้
# guard เดิม suppress ผิดพลาด (regression)
# ROOT CAUSE ที่แยกแยะ 2 กรณีนี้ได้จริง (ยืนยันด้วยข้อมูลสี pixel จริงทั้ง 2 ไฟล์): EB73-01
# (ghost จริง) มีสีเดียวกันเป๊ะทั้ง 2 ฝั่งของ jump (0,0,255 น้ำเงินล้วนทั้งคู่ - เพราะไฟล์นี้มี
# SKU เดียว สีเดียวทั้งไฟล์ และ Phase 1B นับได้แค่ 2 คอลัมน์ทั้งวิว ไม่มี "แถวหลัง" อยู่จริงเลย)
# ในขณะที่ EC05-01 (genuine ทั้ง idx=0 และ idx=4) มีสีต่างกันชัดเจนทั้ง 2 กรณี (ส้ม->เขียวมะกอก,
# ม่วง/ชมพู->เขียว - เป็นกล่องคนละใบ/คนละ SKU ที่ซ่อนอยู่แถวหลังจริง)
# FIX: เปลี่ยนเงื่อนไข suppress จาก "cargo_bottom_y jump อย่างเดียว" เป็น "cargo_bottom_y jump
# ใหญ่ AND สีเดียวกันทั้ง 2 ฝั่ง" (ต้องผ่านทั้ง 2 เงื่อนไขจึง suppress) - เพิ่มพารามิเตอร์
# region/cargo_mask เพื่อ sample สีจริงที่ตำแหน่ง top ของแต่ละฝั่ง เปรียบเทียบด้วย
# normalized-hue distance (เทคนิคเดียวกับที่ใช้ใน _recheck_stack_height_via_color/
# _merge_shade_duplicate_clusters ที่ผ่านการยืนยันมาแล้วทั่วระบบ) - ถ้าระยะห่างสีต่ำกว่า
# threshold (สีเดียวกัน/ใกล้เคียงกันมาก) และ cargo_bottom_y jump ใหญ่ ให้ถือว่าเป็น ghost
# artifact - ถ้าสีต่างกันชัดเจน (เกิน threshold) ให้เชื่อว่าเป็น genuine hidden_behind เสมอ
# (ไม่ suppress) ไม่ว่า cargo_bottom_y jump จะใหญ่แค่ไหนก็ตาม
_HIDDEN_BEHIND_SAME_COLOR_MAX_DIST = 35  # ระยะห่าง normalized-hue สูงสุดที่ยังถือว่า "สีเดียวกัน"
# (ยืนยันจาก EB73: (0,0,255) vs (24,24,254) normalize แล้วใกล้เคียงกันมาก distance<10 | EC05:
# ส้ม vs เขียวมะกอก, ม่วง vs เขียว distance>150 ทั้งคู่ - ตั้ง threshold ต่ำไว้ก่อนเพื่อความปลอดภัย
# ให้ margin สูงพอจะไม่ suppress กรณีที่สีต่างกันจริงโดยไม่ตั้งใจ)
def _sample_color_near(region, cargo_mask, x_center, half_width=4):
    """เก็บสี median ของ pixel ที่ 'ขอบบนสุดของ cargo_mask' ในช่วง x_center±half_width -
    ใช้เปรียบเทียบว่า 2 ฝั่งของ hidden_behind split เป็นสีเดียวกันหรือไม่ (ดู docstring เต็ม
    ด้านบน) คืนค่า None ถ้า sample ไม่ได้ (fail-safe)"""
    if region is None or cargo_mask is None:
        return None
    h, w = cargo_mask.shape[:2]
    colors = []
    for x in range(max(0, x_center - half_width), min(w, x_center + half_width + 1)):
        ys = np.nonzero(cargo_mask[:, x])[0]
        if len(ys) == 0:
            continue
        y0 = int(ys.min())
        if 0 <= y0 < h:
            colors.append(region[y0, x].astype(np.float64))
    if not colors:
        return None
    return np.median(np.array(colors), axis=0)
def _hidden_behind_sides_same_color(region, cargo_mask, left_x, right_x):
    """True ถ้าสีที่ขอบซ้าย (left_x) และขอบขวา (right_x) ของ split เป็นสีเดียวกัน/ใกล้เคียงกัน
    มาก (ใช้ normalized-hue distance เดียวกับที่ใช้ทั่วระบบ) - คืน False ถ้าตรวจสอบไม่ได้หรือ
    สีต่างกันชัดเจน (fail-safe: ถ้าไม่แน่ใจ ให้ถือว่า "ต่างสี" = ไม่ suppress = ปลอดภัยกว่า)"""
    c_left = _sample_color_near(region, cargo_mask, left_x)
    c_right = _sample_color_near(region, cargo_mask, right_x)
    if c_left is None or c_right is None:
        return False
    n_left = _stack_color_normalize(c_left)
    n_right = _stack_color_normalize(c_right)
    if n_left is None or n_right is None:
        return False
    dist = float(np.sqrt(np.sum((n_left - n_right) ** 2)))
    return dist <= _HIDDEN_BEHIND_SAME_COLOR_MAX_DIST
def _detect_hidden_behind_split(cargo_top_y, local_floor_y, x0, x1,
                                 margin=STEP_DOWN_HIDDEN_BEHIND_MARGIN,
                                 min_seg=STEP_DOWN_HIDDEN_BEHIND_MIN_SEG,
                                 jump_thresh_px=STEP_DOWN_HIDDEN_BEHIND_MIN_JUMP_PX,
                                 win=STEP_DOWN_HIDDEN_BEHIND_WIN,
                                 max_side_std=STEP_DOWN_HIDDEN_BEHIND_MAX_SIDE_STD,
                                 cargo_bottom_y=None, region=None, cargo_mask=None):
    """v25.23 NEW: หาจุด 'seam ที่ซ่อนอยู่กลางคอลัมน์' ซึ่งเกิดจากกล่องแถวหลัง (ข้ามความกว้าง
    ตู้) สูงกว่ากล่องแถวหน้าที่บังอยู่ - สัญญาณคือ top-face bleed-through (หลังคากล่องหลัง
    โผล่พ้นกล่องหน้า) ทำให้ cargo_top_y กระโดดขึ้นกะทันหันกลางคอลัมน์ (คนละสาเหตุกับ seam
    ระหว่างคอลัมน์ปกติที่ Phase 1B ตรวจจับจากรอยต่อสี front-face)

    วิธีตรวจ: หาตำแหน่ง k ที่ median(height ก่อน k) กับ median(height หลัง k) ต่างกันอย่างน้อย
    jump_thresh_px พิกเซล โดยทั้ง 2 ฝั่ง (หน้าต่างกว้าง win พิกเซล) ต้องนิ่งมาก (std <=
    max_side_std) เพื่อแยกแยะจาก noise ของตัวอักษร SKU หรือความชันธรรมชาติของมุมมอง
    isometric (ซึ่งมักมี std สูงกว่านี้มากเพราะเป็นการไล่ระดับต่อเนื่อง ไม่ใช่การกระโดดคมชัด)
    ใช้ median-filter (size=5) ก่อนเพื่อกันจุด outlier เดี่ยวๆจากรู/ขอบตัวอักษรบนกล่อง

    v25.70 NEW (สำคัญ - พบจริงจาก EE03-01 ที่ผู้ใช้ระบุ "silhouette_notch/step_down จับไม่เจอ
    อะไรเลย", 30-Aug-2026): เดิมฟังก์ชันนี้ตรวจจับเฉพาะทิศทาง "สูงขึ้นกะทันหัน" (jump บวก - กล่อง
    ซ่อนหลังสูงกว่าฝั่งหน้า) เท่านั้น - พบว่าไฟล์ EE03-01 มีรูปแบบตรงข้าม: ภายในคอลัมน์ P1B
    เดียวกัน (เกิดจาก reconcile ระหว่าง FRONT/BACK ที่ใช้ "ชุดสีซ้ำกัน" เป็นเกณฑ์ตัดสินใจ ไม่
    สามารถแยกแยะ 2 fragment คนละตำแหน่งจริงที่บังเอิญมีสีผสมเหมือนกันได้ - ทำให้กล่อง 2 ใบคนละ
    ความสูงถูกรวมอยู่ในคอลัมน์เดียวกัน) พบจุดกระโดด "ลดลงกะทันหัน" ที่ x=1146 (จาก 282px เหลือ
    222px, drop_ratio=21.1%, left_std=0.82/right_std=1.40 - นิ่งมากทั้ง 2 ฝั่ง ผ่านเกณฑ์เดียวกับ
    ที่ใช้ยืนยัน AE02-01 มาก่อน) ทำให้ STEP_DOWN pairwise/cross_view ตรวจไม่พบ (เพราะข้อมูลถูก
    รวมเป็นคอลัมน์เดียวไปแล้วตั้งแต่ขั้น Phase 1B ก่อนกลไกเหล่านั้นจะมีโอกาสเห็นข้อมูลที่ถูกต้อง)
    และ silhouette_notch ก็ตรวจไม่พบเช่นกัน (เพราะ sample สีตรงจุดกระโดดแล้วพบว่าเป็นสีกล่องจริง
    ไม่ใช่พื้นหลัง/สีโครงสร้างตู้ - ถูกต้องแล้วที่ไม่ flag เพราะนี่ไม่ใช่ "พื้นที่ว่าง")

    FIX: ตรวจจับทั้ง 2 ทิศทาง (jump บวก="สูงขึ้น" เดิม, jump ลบ="ลดลง" ใหม่) ด้วย guard ชุด
    เดียวกันทุกประการ (ไม่ผ่อนปรน threshold ใดๆ) - เลือกทิศทางแรกที่พบตามลำดับการสแกน (เหมือน
    เดิม ไม่เปลี่ยนพฤติกรรมสำหรับไฟล์ที่มีแค่ทิศทางเดียว) คืนค่าเพิ่ม key "direction" ('up'/
    'down') ให้ผู้เรียกใช้ (detect_step_down_hidden_behind) ตัดสินใจว่าจะ mark ฝั่งไหนของ split
    (ทิศทาง 'up': ฝั่งขวา/หลัง split สูงกว่า -> mark ฝั่งขวา (เดิม) | ทิศทาง 'down': ฝั่งซ้าย/
    ก่อน split สูงกว่า -> mark ฝั่งซ้ายแทน - ทั้ง 2 กรณี mark "ฝั่งที่สูงกว่า" เสมอ ตรงกับหลักการ
    เดียวกับ STEP_DOWN_RISK ทุก subtype อื่นที่ mark กองสูงกว่าเป็นแหล่งเสี่ยงล้มทับ)

    คืนค่า dict(split_x, front_height, hidden_height, jump_px, direction) ถ้าพบ หรือ None ถ้า
    ไม่พบรูปแบบที่น่าเชื่อถือทั้ง 2 ทิศทาง"""
    xs, vals, floor_vals, bottom_vals = [], [], [], []
    for x in range(x0 + margin, x1 - margin):
        if x < 0 or x >= len(cargo_top_y):
            continue
        t = cargo_top_y[x]
        f = local_floor_y[x] if x < len(local_floor_y) else -1
        if t >= 0 and f >= 0:
            xs.append(x)
            vals.append(f - t)
            floor_vals.append(f)  # v25.70 NEW: เก็บค่า floor ดิบแยกไว้ต่างหาก (ดูเหตุผลด้านล่าง)
            # v25.89 NEW: เก็บ cargo_bottom_y ดิบ (ขอบล่างจริงของ mask กล่อง ก่อนคำนวณ floor) ไว้
            # ด้วย - ใช้ตรวจสอบความต่อเนื่องของ mask ในทิศทาง 'up' (ดู docstring ด้านล่าง)
            if cargo_bottom_y is not None and x < len(cargo_bottom_y):
                bottom_vals.append(float(cargo_bottom_y[x]) if cargo_bottom_y[x] >= 0 else np.nan)
            else:
                bottom_vals.append(np.nan)
    n = len(vals)
    if n < min_seg * 2:
        return None
    vals = np.array(vals, dtype=float)
    floor_vals = np.array(floor_vals, dtype=float)
    bottom_vals = np.array(bottom_vals, dtype=float)
    smoothed = ndimage.median_filter(vals, size=5, mode="nearest")
    for k in range(win, n - win + 1):
        left_win = smoothed[max(0, k - win):k]
        right_win = smoothed[k:k + win]
        if len(left_win) < 3 or len(right_win) < 3:
            continue
        left_std = float(np.std(left_win))
        right_std = float(np.std(right_win))
        left_med = float(np.median(left_win))
        right_med = float(np.median(right_win))
        jump = right_med - left_med
        if abs(jump) < jump_thresh_px or left_std > max_side_std or right_std > max_side_std:
            continue
        if jump >= jump_thresh_px:
            # v25.89 NEW (สำคัญ - พบจริงจาก EB73-01 ที่ผู้ใช้แนบ 2-Sep-2026, ผู้ใช้ยืนยันว่า
            # ไฟล์นี้ปลอดภัย แต่ v25.88 flag hidden_behind BACK idx0 ผิดพลาด): ยืนยันด้วยข้อมูล
            # จริงระดับ pixel - cargo_bottom_y (ขอบล่างจริงของ mask กล่อง ก่อนคำนวณ floor) กระโดด
            # จาก 387px ไป 584px (197px) ภายในแค่ 1 pixel (x=755->756) ณ ตำแหน่งเดียวกับที่พบ
            # "jump" ของ height (floor-top) - พิสูจน์ว่า cargo_mask ตรงนี้เป็น "เศษสีปลอม/artifact"
            # (ghost sliver) ที่ไม่ต่อเนื่องกับ mask หลัก (2 ก้อนแยกกันจริง ไม่ใช่วัตถุเดียวที่มี
            # หลังคากล่องซ่อนโผล่พ้น) เพราะกรณี "หลังคากล่องซ่อนโผล่พ้นจริง" (genuine top-face
            # bleed-through) ควรมี cargo_bottom_y ต่อเนื่องคงที่ (พื้น/ขอบล่างกล่องแถวหน้าเดิม
            # ไม่เปลี่ยน มีแค่ยอดที่โผล่สูงขึ้น) ไม่ใช่กระโดดพร้อมกันทั้งขอบบนและขอบล่างแบบนี้
            # FIX: ตรวจสอบความต่อเนื่องของ cargo_bottom_y (mask ดิบ) ที่จุด split เดียวกัน - ถ้า
            # cargo_bottom_y เองก็กระโดดเกิน _HIDDEN_BEHIND_UP_MAX_BOTTOM_JUMP_PX ด้วย (บ่งชี้ mask
            # ไม่ต่อเนื่อง/เป็นคนละก้อน) ให้ไม่เชื่อว่าเป็น genuine hidden-behind - ปลอดภัยเพราะเกณฑ์
            # นี้ตั้งสูง (40px) กว่า noise ปกติของขอบกล่องมาก แต่ยังต่ำกว่าค่าที่พบจริงของ artifact
            # (197px) มาก - ถ้าไม่มีข้อมูล cargo_bottom_y (None) จะข้ามการตรวจสอบนี้ไป (fail-safe)
            bottom_jump_ok = True
            if not np.all(np.isnan(bottom_vals)):
                bl = bottom_vals[max(0, k - win):k]
                br = bottom_vals[k:k + win]
                bl = bl[~np.isnan(bl)]
                br = br[~np.isnan(br)]
                if len(bl) >= 3 and len(br) >= 3:
                    bottom_jump = abs(float(np.median(br)) - float(np.median(bl)))
                    if bottom_jump > _HIDDEN_BEHIND_UP_MAX_BOTTOM_JUMP_PX:
                        bottom_jump_ok = False
            # v25.89 FIX (สำคัญ - พบ regression จริงจาก EC05-01): ไม่ suppress ทันทีแค่เพราะ
            # cargo_bottom_y jump ใหญ่ (เพราะ genuine hidden_behind ก็มี jump แบบนี้ได้ตามธรรมชาติ
            # - ดู docstring เต็มด้านบน) ต้องตรวจสอบเพิ่มว่าสีทั้ง 2 ฝั่งเดียวกันหรือไม่ด้วย - ถ้า
            # bottom_jump ใหญ่ "และ" สีทั้ง 2 ฝั่งเป็นสีเดียวกัน (บ่งชี้ ghost/fragment ของวัตถุ
            # เดียวกัน ไม่ใช่กล่องคนละใบ) จึงจะ suppress
            if not bottom_jump_ok:
                same_color = _hidden_behind_sides_same_color(
                    region, cargo_mask, xs[k] - win // 2, xs[k] + win // 2)
                if same_color:
                    continue
            # ทิศทางเดิม (v25.23): ฝั่งขวา/หลัง split สูงกว่า (กล่องซ่อนหลังโผล่พ้น)
            return {
                "split_x": xs[k], "front_height": left_med, "hidden_height": right_med,
                "jump_px": jump, "left_std": left_std, "right_std": right_std,
                "direction": "up",
            }
        else:
            # v25.70 NEW: ทิศทางใหม่ - ฝั่งซ้าย/ก่อน split สูงกว่า (2 fragment คนละตำแหน่งจริง
            # ที่ถูกรวมเป็นคอลัมน์เดียวจาก Phase 1B/reconcile - ดู docstring เต็มด้านบน)
            #
            # v25.70 FIX (Critical - พบ regression จริงจาก RD01-01 ระหว่าง self-regression-test
            # วันเดียวกัน, ผู้ใช้ยืนยันว่าไฟล์นี้ปลอดภัย 100%): ทิศทาง "down" เสี่ยงจับ noise จาก
            # ความชัน isometric ธรรมชาติได้ง่ายกว่าทิศทาง "up" มาก เพราะไม่มีรูปแบบทางกายภาพที่
            # เฉพาะเจาะจง (ทิศทาง up ต้องมีกล่องซ่อนหลังสูงกว่าจริง ซึ่งหายากและมี signature ชัดเจน
            # ส่วนทิศทาง down อาจเกิดจากแค่ noise ของการ fit เส้นใกล้ apex/ขอบภาพก็ได้) ยืนยันจาก
            # RD01-01 (false positive): jump=20.5px (เกินเกณฑ์ขั้นต่ำ 20px แค่นิดเดียว) left_std=
            # 4.84 (สูงกว่าปกติมาก) -> signal/noise ratio = 20.5/4.84 = 4.2 เทียบกับ EE03-01
            # (true positive จริง): jump=59.5px, std สูงสุด=1.40 -> ratio = 42.5 (ต่างกันถึง 10
            # เท่า) - เพิ่มเกณฑ์ signal/noise ratio ขั้นต่ำ (เฉพาะทิศทาง down เท่านั้น ไม่กระทบ
            # ทิศทาง up เดิมที่ผ่าน regression มาแล้วหลายไฟล์) เพื่อกรอง noise แบบนี้ออก
            noise = max(left_std, right_std, 0.01)  # กัน division by zero
            signal_to_noise = abs(jump) / noise
            if signal_to_noise < _HIDDEN_BEHIND_DOWN_MIN_SNR:
                continue
            # v25.70 FIX #2 (Critical - พบ regression จริงจาก ED86-03 หลังแก้ SNR guard แล้ว):
            # เดิมคำนวณ "jump" จาก height (floor-top) เพียงอย่างเดียว - พบว่าไฟล์ ED86-03 มี
            # local_floor_y (เส้นพื้น) กระโดดปลอมที่ตำแหน่ง P1B column boundary พอดี (493->467,
            # 26px) ในขณะที่ cargo_top_y (เส้นยอดกล่อง) ราบเรียบต่อเนื่องสนิท (117->116, แทบไม่
            # เปลี่ยน) - ทำให้ "height jump" ที่คำนวณได้เป็นผลจาก floor artifact ไม่ใช่กล่องเตี้ยกว่า
            # จริง (ยืนยันแล้วด้วยภาพว่า STT1A/INERA สูงเท่ากันจริง ต่างแค่ 2.9%) ต่างจาก EE03-01
            # (true positive) ที่ floor แทบไม่เปลี่ยน (393->392, 1px) แต่ top กระโดดจริง (112->169,
            # 57px) - เพิ่มการตรวจสอบว่า floor ต้องนิ่งด้วย (ไม่ใช่แค่ height/std) ก่อนเชื่อว่าเป็น
            # step-down จริง (เฉพาะทิศทาง down เท่านั้น เหตุผลเดียวกับ SNR guard ด้านบน)
            left_floor = floor_vals[max(0, k - win):k]
            right_floor = floor_vals[k:k + win]
            if len(left_floor) >= 3 and len(right_floor) >= 3:
                floor_jump = abs(float(np.median(right_floor)) - float(np.median(left_floor)))
                if floor_jump > _HIDDEN_BEHIND_DOWN_MAX_FLOOR_JUMP_PX:
                    continue
            return {
                "split_x": xs[k], "front_height": right_med, "hidden_height": left_med,
                "jump_px": abs(jump), "left_std": left_std, "right_std": right_std,
                "direction": "down",
            }
    return None


def detect_hidden_behind_columns(view_result):
    """v25.23 NEW: สแกนทุกคอลัมน์ (ตั้ง) ของ view นี้หาจุด 'hidden_behind split' - คืนค่า
    dict {stack_idx: {split_x, front_height, hidden_height, jump_px}} เฉพาะคอลัมน์ที่พบ
    รูปแบบที่ผ่านเกณฑ์ทางสถิติเท่านั้น (ดู _detect_hidden_behind_split)"""
    cargo_top_y = view_result["cargo_top_y"]
    local_floor_y = view_result["local_floor_y"]
    cargo_bottom_y = view_result.get("cargo_bottom_y")  # v25.89 NEW: ดู docstring ที่
    # _detect_hidden_behind_split (ทิศทาง 'up') สำหรับหลักฐาน+เหตุผล
    region = view_result.get("region")  # v25.89 NEW: สำหรับ same-color check
    cargo_mask = view_result.get("cargo_mask")  # v25.89 NEW: สำหรับ same-color check
    seams = view_result["seams"]
    start_x, end_x = view_result["start_x"], view_result["end_x"]
    boundaries = [start_x] + sorted(seams) + [end_x]
    found = {}
    for i in range(len(boundaries) - 1):
        x0, x1 = boundaries[i], boundaries[i + 1]
        r = _detect_hidden_behind_split(cargo_top_y, local_floor_y, x0, x1,
                                         cargo_bottom_y=cargo_bottom_y,
                                         region=region, cargo_mask=cargo_mask)
        if r is not None:
            r["x0"] = x0  # v25.70 NEW: เก็บ x0 ไว้ด้วย (จำเป็นสำหรับ direction='down' ที่ต้อง
            r["x1"] = x1  # mark ฝั่งซ้าย/ก่อน split แทนฝั่งขวา/หลัง split แบบเดิม)
            found[i] = r
    return found


def fill_missing_heights(records):
    """เติมค่า height_px=None ที่เหลือ (หลัง cross-view reconciliation พยายามเติมให้แล้ว
    แต่ไม่มี match ที่ใช้ได้) ด้วยการ carry-forward จากตั้งก่อนหน้าในมุมมองเดียวกัน -
    เป็นทางเลือกสุดท้ายเท่านั้น ข้าม is_corner_duplicate เสมอ (ทั้งเป้าหมายและแหล่งอ้างอิง)"""
    last_valid = None
    for r in records:
        if r.get("is_corner_duplicate"):
            continue
        if r["height_px"] is not None:
            last_valid = r["height_px"]
        elif last_valid is not None:
            r["height_px"] = last_valid
            r["height_source"] = "carried_forward_same_view"
    return records


def process_view_with_height_on_image(full_img, doc, view_name, page_idx=1, margin=6,
                                       override_cols=None, precrop=None):
    r = process_view_with_length_on_image(full_img, doc, view_name, page_idx=page_idx,
                                           override_cols=override_cols, precrop=precrop)
    cargo_top_y = compute_cargo_top_profile(r["cargo_mask"])
    local_floor_y = compute_local_floor_y(r["floor_y"], r["grounded"])
    stack_heights = compute_stack_heights_px(
        r["seams"], r["start_x"], r["end_x"], cargo_top_y, margin=margin, local_floor_y=local_floor_y)
    view_result = {**r, "cargo_top_y": cargo_top_y, "local_floor_y": local_floor_y,
                   "stack_heights": stack_heights}
    # v25.23 NEW: สแกนหา 'hidden_behind' หลังมี cargo_top_y/local_floor_y ครบแล้ว
    view_result["hidden_behind"] = detect_hidden_behind_columns(view_result)
    return view_result


# ============================================================================
# RULE ENGINE: 3 risk types (STEP_DOWN pairwise, STEP_DOWN cross_view, REAR_EMPTY)
# ============================================================================

def stack_positions_normalized(view_result):
    start_x, end_x = view_result["start_x"], view_result["end_x"]
    span = max(1, end_x - start_x)
    seams = sorted(view_result["seams"])
    boundaries = [start_x] + seams + [end_x]
    positions = []
    for i in range(len(boundaries) - 1):
        p0 = (boundaries[i] - start_x) / span
        p1 = (boundaries[i + 1] - start_x) / span
        positions.append((p0, p1))
    return positions


def build_stack_records(view_result, view_label, flip_position=None):
    """สร้าง records แต่ละตั้ง: {idx, x_range, pos_range (0=หัวตู้,1=ประตูท้ายตู้), height_px}

    ทิศทาง flip อ้างอิงจาก HARDCODED_REAR_SIDE เดิมของ v24.36 (FRONT: ซ้าย=ประตูท้าย,
    ขวา=หัวตู้ | BACK: ซ้าย=หัวตู้, ขวา=ประตูท้าย) ยืนยันด้วยลำดับสี SKU จริงข้าม 2 view
    -> FRONT ต้อง flip (True), BACK ไม่ต้อง flip (False)"""
    if flip_position is None:
        flip_position = (view_label == "FRONT")
    positions = stack_positions_normalized(view_result)
    heights = view_result["stack_heights"]
    is_corner_dup = view_result.get("idx0_is_corner_duplicate", False)
    records = []
    for i, ((p0, p1), h) in enumerate(zip(positions, heights)):
        if flip_position:
            real_p0, real_p1 = 1.0 - p1, 1.0 - p0
        else:
            real_p0, real_p1 = p0, p1
        records.append({
            "idx": i, "view": view_label,
            "x_range": h["x_range"], "pos_range": (real_p0, real_p1),
            "height_px": h["height_px"],
            "height_source": h.get("height_source", "direct"),
            # v25.48 NEW: จำนวนจุดข้อมูลจริงที่ใช้ fit เส้นความสูง (n_samples) - เก็บไว้ใช้เป็น
            # สัญญาณความน่าเชื่อถือของค่า height_px นี้ (ดู STEP_DOWN_MIN_RELIABLE_SAMPLES)
            "n_samples": h.get("n_samples", 0),
            # True เฉพาะ idx==0 ที่ตรวจพบว่าเป็น corner artifact จริง (ตรวจจากเส้น rail
            # ทางเรขาคณิต ไม่ใช่ hardcode ชื่อ view - ดู process_view_on_image)
            "is_corner_duplicate": (i == 0 and is_corner_dup),
        })
    return records


STEP_DOWN_FLOOR_JUMP_MIN_PX = 15


def _p1b_compute_floor_jump(local_floor_y, x0a, x1a, x1b, exclude=8):
    seam = x1a
    left_xs = [x for x in range(max(0, x0a), seam - exclude)
               if 0 <= x < len(local_floor_y) and local_floor_y[x] >= 0]
    right_xs = [x for x in range(seam + exclude, x1b)
                if 0 <= x < len(local_floor_y) and local_floor_y[x] >= 0]
    if len(left_xs) < 5 or len(right_xs) < 5:
        return None
    lx = np.array(left_xs, dtype=float)
    ly = np.array([local_floor_y[x] for x in left_xs], dtype=float)
    rx = np.array(right_xs, dtype=float)
    ry = np.array([local_floor_y[x] for x in right_xs], dtype=float)
    coef_l = np.polyfit(lx, ly, 1)
    coef_r = np.polyfit(rx, ry, 1)
    floor_l_at_seam = np.polyval(coef_l, seam)
    floor_r_at_seam = np.polyval(coef_r, seam)
    return float(floor_r_at_seam - floor_l_at_seam)


# v25.59/61 NEW (สำคัญ - พบจริงจาก RD01-01, 29-Aug-2026): เดิม reconcile_heights_cross_view
# ตัดสินใจเชื่อค่าความสูงฝั่งไหนโดยดูแค่ reliability hierarchy + "ค่าสูงกว่าชนะ" เมื่อทั้งคู่
# reliable เท่ากัน - ไม่ตรวจสอบว่า local_floor_y ที่ตำแหน่งนั้น "สมเหตุสมผลทางเรขาคณิต" หรือไม่
# ยืนยันจาก RD01-01: BACK floor_y=550/477/405 (ลดหลั่นสม่ำเสมอ) แต่ FRONT floor_y=552/543/431
# (กระโดดผิดปกติ) reconcile เดิมเลือกเชื่อ FRONT (สูงกว่า) เขียนทับ BACK ที่ถูกต้อง
# FIX: เปรียบเทียบ floor_y ของคอลัมน์เป้าหมายกับค่าคาดหวังจาก interpolation ของเพื่อนบ้าน 2 ข้าง
# ในวิวเดียวกัน (เฉพาะ interpolation เท่านั้น - ทดลอง extrapolation หลายแบบแล้วพบว่าทำให้เกิด
# false-positive ใหม่กับ EB66-01 idx0 เสมอ เพราะความบิดเบือนที่ริมสุดจริงไม่เป็นเส้นตรง)
_FLOOR_LINEARITY_ANOMALY_MIN_PX = 20
# v25.81 NEW: ดู docstring เต็มที่จุดใช้งานจริงใน reconcile_heights_cross_view (BACK-View
# Priority Consensus Guard) สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA02-02/ED86-03 - ตามคำแนะนำผู้ใช้
# "ให้วิเคราะห์ BACK view ก่อนเสมอ")
_BACK_PRIORITY_MAX_INTERNAL_SPREAD = 0.08  # BACK ต้องนิ่งมาก (spread<=8%) จึงเชื่อเป็นหลัก - สูง
# กว่า EA02-02(0.24%)/ED86-03(2.8%) มากพอจะครอบคลุม noise ปกติ แต่ต่ำกว่าเกณฑ์ conflict_ratio
# เริ่มต้น (10%) พอสมควรเพื่อไม่ trigger กับกรณีทั่วไปที่ BACK มีความต่างกันบ้างตามธรรมชาติ
_BACK_PRIORITY_MIN_FRONT_DEVIATION = 0.15  # FRONT (ผู้แพ้ที่ควรจะเป็น) ต้องเบี่ยงเบนจาก BACK
# consensus อย่างน้อยเท่านี้ จึงจะ trigger การพลิกกลับ (เท่ากับเกณฑ์เดียวกับ Global-Consensus เดิม)


def _floor_linearity_anomaly(records_same_view, target_idx, local_floor_y):
    """คำนวณความเบี่ยงเบนจากเส้นตรงของ local_floor_y ที่ตำแหน่ง target_idx เทียบกับค่าคาดหวัง
    จาก interpolation ของเพื่อนบ้าน 2 ข้าง (ต้องมีครบทั้ง 2 ฝั่งเท่านั้น) คืนค่า deviation_px
    หรือ None ถ้าตรวจสอบไม่ได้ (คอลัมน์ริมสุด - ปลอดภัยกว่าไม่ตรวจสอบเลย)"""
    by_idx = {r["idx"]: r for r in records_same_view}
    target = by_idx.get(target_idx)
    if target is None:
        return None

    def _floor_at_mid(rec):
        x0, x1 = rec["x_range"]
        xm = (x0 + x1) // 2
        if 0 <= xm < len(local_floor_y) and local_floor_y[xm] >= 0:
            return float(xm), float(local_floor_y[xm])
        return None

    tgt_point = _floor_at_mid(target)
    if tgt_point is None:
        return None
    tx, tfloor = tgt_point

    left = by_idx.get(target_idx - 1)
    right = by_idx.get(target_idx + 1)
    left_point = _floor_at_mid(left) if left is not None else None
    right_point = _floor_at_mid(right) if right is not None else None

    if left_point is not None and right_point is not None:
        lx, lf = left_point
        rx, rf = right_point
        if rx == lx:
            return None
        expected = lf + (tx - lx) / (rx - lx) * (rf - lf)
        return abs(tfloor - expected)
    return None


