# _has_internal_sharp_jump()=False ทั้งคู่) แต่ local_floor_y (เส้นพื้น) กลับมีความชันต่อเนื่อง
# ราบรื่นเช่นกัน (577px ลดหลั่นลงเหลือ 513px ตลอดความกว้างวัตถุ) ทำให้ "ความสูงที่วัดได้"
# (floor-top) ต่างกันไปตามตำแหน่ง x ที่ใช้ประเมิน (eff_mid ของแต่ละคอลัมน์) - เป็นความเอนเอียงจาก
# มุมมอง isometric ธรรมชาติของวัตถุที่ลอยตัวอยู่โดดเดี่ยวในตู้เปล่า (ไม่มี apex ให้ detect_
# isometric_apex ตรวจพบเลย เพราะวัตถุแคบเกินไป/ไม่มี V-shape ในช่วงแคบๆ ของตัวมันเอง - apex_x=None
# ทั้งคู่) ไม่ใช่ความแตกต่างทางกายภาพจริงของกล่อง SKU เดียวกันที่สูงเท่ากันจริง
# FIX: เพิ่มเงื่อนไขตรวจสอบใหม่ - ถ้าวิวนี้มี "รวมทั้งหมดเพียง 2 คอลัมน์" (ไม่มี plateau ใดๆ ให้
# อ้างอิงได้เลยแม้แต่คอลัมน์เดียว, ต่างจาก Edge-Column Guard เดิมที่ยังพอมี 1+ คอลัมน์เหลือ) และ
# ทั้งคู่เป็น height_source=="direct" ให้ตรวจสอบด้วย _has_internal_sharp_jump (เทคนิคเดียวกับที่
# ใช้แยกแยะ jump จริงจาก isometric slope ต่อเนื่องใน AC03-02/EA03-01 - เชื่อถือได้มากกว่า
# _edge_outlier_has_genuine_seam_jump ซึ่งใช้ window-median scan ที่เสี่ยงถูกความชันธรรมชาติ
# หลอกได้ในบางกรณี) ครอบคลุมทั้งช่วงของทั้ง 2 คอลัมน์รวมกัน - ถ้าไม่พบ jump คมชัดจริง (False) ให้
# ถือว่าเป็นวัตถุความสูงสม่ำเสมอจริง ไม่ flag ความเสี่ยง
# ขอบเขตการแก้ (แคบมาก ปลอดภัยสูง): ทำงานเฉพาะไฟล์ที่มีคอลัมน์รวมทั้งวิวเพียง 2 คอลัมน์เท่านั้น
# (เงื่อนไขนี้พบได้ยาก เฉพาะไฟล์ที่บรรทุกเบาบางมากและกล่องรวมเป็นก้อนเดียว) ไม่กระทบไฟล์ที่มี
# คอลัมน์ตั้งแต่ 3 ขึ้นไปเลย (ยังคงใช้ Edge-Column Guard เดิมตามปกติ)
# ข้อจำกัดที่ต้องบอกตรงไปตรงมา: ยืนยันด้วยข้อมูลจริงจากไฟล์เดียว (EB73-01) เท่านั้น - ยังไม่ได้
# regression-test ย้อนกับไฟล์ calibration เดิมทั้งหมด (ไม่มีไฟล์เหล่านั้นให้ทดสอบในรอบนี้) แต่ประเมิน
# ความเสี่ยงแล้วว่าปลอดภัยสูง เพราะเงื่อนไข "รวมทั้งวิวมีแค่ 2 คอลัมน์" เป็นเงื่อนไขที่แคบมาก
# (พบเฉพาะไฟล์บรรทุกเบาบางมากผิดปกติ) แนะนำให้รัน regression เต็มรูปแบบก่อนใช้งานจริง
def _isolated_pair_no_genuine_jump(records_same_view, view_result):
    """True ถ้าวิวนี้มีทั้งหมดเพียง 2 คอลัมน์ (ไม่มี plateau ใดๆ ให้อ้างอิงได้เลยแม้แต่คอลัมน์
    เดียว - ต่างจาก Edge-Column Global Consensus Guard เดิมที่ยังต้องการอย่างน้อย 2 คอลัมน์อื่น)
    และไม่มี genuine sharp jump (single-pixel step, ตรวจด้วย _has_internal_sharp_jump) ระหว่าง
    คอลัมน์ทั้ง 2 ทั่วทั้งช่วงรวม - ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01)
    """
    valid = [r for r in records_same_view if not r.get("is_corner_duplicate")]
    if len(valid) != 2:
        return False
    valid = sorted(valid, key=lambda r: r["x_range"][0])
    a, b = valid[0], valid[1]
    if a.get("height_source") != "direct" or b.get("height_source") != "direct":
        return False
    if view_result is None:
        return False
    cty = view_result.get("cargo_top_y")
    if cty is None:
        return False
    lo = min(a["x_range"][0], b["x_range"][0])
    hi = max(a["x_range"][1], b["x_range"][1])
    return not _has_internal_sharp_jump(cty, (lo, hi))


def _is_edge_measurement_outlier(records_same_view, target_idx,
                                  min_plateau_size=_EDGE_OUTLIER_MIN_PLATEAU_SIZE,
                                  plateau_max_spread_ratio=_EDGE_OUTLIER_PLATEAU_MAX_SPREAD_RATIO,
                                  deviation_threshold=_EDGE_OUTLIER_DEVIATION_THRESHOLD,
                                  view_result=None):
    """True ถ้า target_idx เป็นคอลัมน์ริมสุดจริงของแถว (idx==0 หรือ idx==max) และความสูงของมัน
    เบี่ยงเบนจาก 'plateau' ของคอลัมน์อื่นที่นิ่งมาก (เชื่อถือได้ + spread ต่ำ) เกิน threshold -
    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก EB66-01/EC10-03/EC19-01)"""
    valid = [r for r in records_same_view if not r.get("is_corner_duplicate")]
    if not valid:
        return False
    all_idxs = [r["idx"] for r in valid]
    min_idx, max_idx = min(all_idxs), max(all_idxs)
    if target_idx != min_idx and target_idx != max_idx:
        return False  # ไม่ใช่คอลัมน์ริมสุดจริง - guard นี้ใช้ไม่ได้
    by_idx = {r["idx"]: r for r in valid}
    target = by_idx.get(target_idx)
    if target is None or target.get("height_px") is None:
        return False
    plateau_heights = []
    for r in valid:
        if r["idx"] == target_idx:
            continue
        if r.get("height_px") is None:
            continue
        # v25.76 FIX (สำคัญ - พบ regression จริงจาก AB05-01 ระหว่างทดสอบ): เดิมรับเฉพาะ
        # height_source in ("direct","cross_view_filled") เข้า plateau - หลังเพิ่ม label ใหม่
        # "apex_partial_cut" (v25.76) คอลัมน์ที่เคยถูกนับเป็นส่วนหนึ่งของ plateau (เพราะเคยได้
        # label "direct" มาก่อน) กลับถูกตัดออกจาก plateau ไปด้วย ทำให้ plateau เหลือจุดไม่พอ
        # (< min_plateau_size) -> Edge-Column Global Consensus Guard ใช้ไม่ได้อีกต่อไป -> เกิด
        # regression ที่ AB05-01 BACK (STEP_DOWN_RISK pairwise idx0 กลับมา flag ผิดพลาดอีกครั้ง
        # ทั้งที่เคยถูกแก้ไปแล้วตั้งแต่ v25.72) - FIX: รับ "apex_partial_cut" เข้า plateau ด้วย
        # (ยังคงเป็นค่าที่วัดได้จริง เพียงแต่มีโอกาสเอนเอียงสูงกว่าจริงเล็กน้อยจากตำแหน่งประเมินใกล้
        # apex - ใช้เป็นหลักฐาน "ความนิ่งของกลุ่ม" ได้ตามปกติ ไม่กระทบการตรวจจับ isometric-bias
        # เดิมที่ guard นี้ออกแบบมา)
        if r.get("height_source") not in ("direct", "cross_view_filled", "apex_partial_cut"):
            continue
        plateau_heights.append(r["height_px"])
    if len(plateau_heights) < min_plateau_size:
        return False
    # v25.83 NEW (สำคัญ - พบจริงจาก ED85-01, 31-Aug-2026 - ผู้ใช้ระบุว่า FRONT view วาดกรอบตรง
    # กล่องสีม่วง TGT1G ทั้งที่ไม่ควรวาด): เดิม plateau_heights ด้านบนรวมคอลัมน์ "ทุกสี" ปนกันหมด
    # (ไม่แยกแยะ SKU) - พบว่าไฟล์ ED85-01 มี idx0 (ริมสุดจริง, สีม่วง TGT1G) วัดได้ 253.3px ต่ำกว่า
    # เพื่อนบ้านสีม่วงเดียวกัน (idx1-4: 308.3/351.5/345.9/317.0px) มาก - แต่ plateau ที่คำนวณจาก
    # "ทุกสีปนกัน" (รวม idx5=teal/idx6=cyan ที่มีความสูงต่างจากม่วงจริงเพราะเป็นคนละ SKU) ทำให้
    # p_spread สูงเกิน 10% (วัดได้จริง 55%) จน guard เดิมไม่ trigger เลย ทั้งที่กลุ่มสีม่วงเพียว ๆ
    # (ไม่รวม idx5/6) เองมี spread แค่ 13.0% (ใกล้เคียง 10% มาก - น่าเชื่อถือกว่าการปนสีมาก)
    # ROOT CAUSE: Phase 1B เก็บ stack_expected_colors ไว้อยู่แล้ว (ยืนยันแน่ชัดว่าคอลัมน์ใดเป็น
    # SKU/สีเดียวกัน) แต่ guard นี้ไม่เคยใช้ข้อมูลนี้เลย - การเทียบข้าม SKU (ม่วงเทียบฟ้า/เขียว)
    # ไม่สมเหตุสมผลทางกายภาพอยู่แล้ว เพราะกล่องคนละ SKU มีสิทธิ์สูงต่ำต่างกันจริงได้ปกติ (ไม่ใช่
    # หลักฐานของ "ความนิ่ง" ที่ควรใช้ตัดสิน isometric bias เลย)
    # FIX: ถ้า view_result มี stack_expected_colors และ target มีสีที่รู้แน่ชัด (ไม่ใช่ None) ให้
    # ลองกรอง plateau เฉพาะคอลัมน์ที่มีสีเดียวกับ target ก่อน (same-color plateau) - ถ้าจำนวนพอ
    # (>= เกณฑ์ขั้นต่ำ) ให้ใช้ชุดนี้แทนที่ all-color plateau เดิม พร้อมใช้เกณฑ์ spread ที่ผ่อนปรน
    # กว่าเล็กน้อย (_EDGE_OUTLIER_SAME_COLOR_MAX_SPREAD_RATIO=15% แทน 10%) เพราะเป็นหลักฐานที่
    # น่าเชื่อถือกว่ามาก (ยืนยันแล้วว่าเป็น SKU เดียวกันจริงจาก Phase 1B ไม่ใช่แค่ "บังเอิญนิ่ง")
    # - ถ้าไม่มีข้อมูลสี หรือ same-color plateau มีจุดไม่พอ ให้ fallback ไปใช้ all-color plateau
    # เดิมทุกประการ (ปลอดภัยสำหรับไฟล์อื่นที่ไม่เจอปัญหานี้)
    same_color_plateau_used = False
    if view_result is not None:
        expected_colors = view_result.get("stack_expected_colors")
        if expected_colors is not None and target_idx < len(expected_colors):
            target_color = expected_colors[target_idx]
            if target_color is not None:
                same_color_heights = []
                for r in valid:
                    if r["idx"] == target_idx or r.get("height_px") is None:
                        continue
                    if r.get("height_source") not in ("direct", "cross_view_filled", "apex_partial_cut"):
                        continue
                    r_idx_local = r["idx"]
                    if r_idx_local >= len(expected_colors):
                        continue
                    if expected_colors[r_idx_local] == target_color:
                        same_color_heights.append(r["height_px"])
                if len(same_color_heights) >= _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
                    plateau_heights = same_color_heights
                    same_color_plateau_used = True
    if same_color_plateau_used:
        plateau_max_spread_ratio = _EDGE_OUTLIER_SAME_COLOR_MAX_SPREAD_RATIO
    # v25.71 NEW (สำคัญ - พบจริงจาก ED85-01/02/03 ที่ผู้ใช้ระบุ, 30-Aug-2026): เดิมคำนวณ
    # p_spread จาก min-max ดิบของ plateau_heights ทั้งหมด - พบว่าคอลัมน์ที่ "ติดกับ" คอลัมน์ริมสุด
    # (idx=1, ไม่ใช่ตัวริมสุดเอง) อาจได้รับผลกระทบจาก isometric distortion ในทิศทางเดียวกัน
    # (เบากว่า) ทำให้ raw min-max spread สูงเกิน threshold แม้ "แกนหลัก" ของ plateau (คอลัมน์ที่
    # เหลือ ไม่รวม idx=1) จะนิ่งมากจริง (spread แค่ 2.7% ในไฟล์ทดสอบ) - ยืนยันด้วยข้อมูลจริง
    # ED85-01/02/03: idx=1 มีความสูง 308.1-308.3px "เหมือนกันเป๊ะ" ข้าม 3 ไฟล์ (สัญญาณเดียวกับ
    # apex_fallback n=67 ที่เคยพิสูจน์แล้วว่าเป็น geometric artifact ไม่ใช่ความสูงจริง)
    # FIX: ใช้ median + MAD-based iterative outlier rejection (เทคนิคเดียวกับ
    # _robust_local_line_fit ที่ใช้ทั่วระบบอยู่แล้ว) ตัด "แกนนอก" (ค่าที่เบี่ยงเบนจาก median มาก)
    # ออกก่อนคำนวณ spread - ทำให้ guard ตรวจจับ "แกนหลักที่นิ่งจริง" ได้แม่นยำขึ้น โดยไม่ต้องขยับ
    # threshold ไปเรื่อยๆ แบบไม่มีจุดจบ (ยืนยันว่าไม่กระทบไฟล์เดิมที่ plateau นิ่งอยู่แล้วเพราะการ
    # trim จะไม่ตัดอะไรออกเลยถ้าไม่มี outlier จริง)
    # v25.71 NEW: แยกเกณฑ์ขั้นต่ำเป็น 2 ระดับ - min_plateau_size (=3 เดิม) ใช้เป็นเงื่อนไข "ก่อน
    # เริ่ม trim" (ต้องมีจุดดิบเพียงพอก่อนถึงจะลองใช้ guard นี้เลย - ไม่ลดมาตรฐานเดิม) ส่วน
    # _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM (=2) ใช้เป็นเกณฑ์ขั้นต่ำ "หลัง trim" เท่านั้น -
    # อนุญาตให้ trim เหลือน้อยกว่าเดิมได้ถ้าจุดที่เหลือ "นิ่งจริง" (ยืนยันจาก ED85-01: มีแค่ 3 จุด
    # ดิบ trim ออกได้ 1 จุด (outlier) เหลือ 2 จุดที่นิ่งมาก - ต้องอนุญาตให้ trim ลงมาที่ 2 ได้ ไม่งั้น
    # จะติดเงื่อนไข "keep.sum()<min_plateau_size" เดิมที่บล็อกไม่ให้ trim เมื่อไฟล์มีคอลัมน์น้อย)
    arr = np.array(plateau_heights, dtype=float)
    for _ in range(3):  # iterative trimming (เหมือน _robust_local_line_fit, n_iter=3)
        if len(arr) < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
            break
        med = np.median(arr)
        mad = np.median(np.abs(arr - med))
        mad = max(mad, 2.0)  # mad_floor กันกรณีข้อมูลเรียบสมบูรณ์แบบ (MAD~0)
        keep = np.abs(arr - med) < 2.5 * mad
        if keep.sum() < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM or keep.sum() == len(arr):
            break
        arr = arr[keep]
    if len(arr) < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
        return False
    p_median = float(np.median(arr))
    if p_median <= 0:
        return False
    p_spread = (arr.max() - arr.min()) / p_median
    if p_spread > plateau_max_spread_ratio:
        return False  # plateau ไม่นิ่งพอจะเป็นหลักฐานอ้างอิงได้ - ปลอดภัยไว้ก่อน ไม่ suppress
    deviation = abs(target["height_px"] - p_median) / p_median
    if deviation < deviation_threshold:
        return False
    # v25.72 NEW: ก่อน suppress จริง ตรวจสอบว่ามี "seam jump" คมชัดระหว่าง target กับเพื่อนบ้าน
    # ที่ใกล้ที่สุดหรือไม่ - ถ้ามี แสดงว่าเป็นความแตกต่างทางกายภาพจริง ไม่ใช่ isometric bias
    # (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล พบจริงจาก AC03-02)
    if view_result is not None:
        neighbor_idx = target_idx + 1 if target_idx == min_idx else target_idx - 1
        neighbor_rec = by_idx.get(neighbor_idx)
        if neighbor_rec is not None:
            has_jump = _edge_outlier_has_genuine_seam_jump(view_result, target, neighbor_rec)
            if has_jump:
                return False  # jump จริงที่ seam - ไม่ suppress ปล่อยให้ flag ตามปกติ
    return True


def detect_step_down_pairwise(records, view_label, view_result=None):
    """เปรียบเทียบตั้งข้างเคียงในview เดียวกัน - ข้าม record ที่ is_corner_duplicate=True
    (ตรวจจากเส้น rail ทางเรขาคณิตจริง ไม่ hardcode ชื่อ view)"""
    risks = []
    local_floor_y = view_result.get("local_floor_y") if view_result else None
    for i in range(len(records) - 1):
        a, b = records[i], records[i + 1]
        if a.get("is_corner_duplicate") or b.get("is_corner_duplicate"):
            continue
        if a["height_px"] is None or b["height_px"] is None:
            continue
        taller_rec = a if a["height_px"] >= b["height_px"] else b
        shorter_rec = b if taller_rec is a else a
        taller_h = taller_rec["height_px"]
        shorter_h = shorter_rec["height_px"]
        # v25.55 FIX#3 (จุดเสี่ยงที่ 1): ถ้าทั้งคู่ได้ค่าจาก carry-forward (height_source=None
        # หลัง fill_missing_heights หรือ "carried_forward_same_view") แสดงว่าค่าที่เปรียบ
        # เทียบกันเป็นค่าเดียวกันที่ propagate มาจากตั้งเดียว ไม่ใช่การวัดอิสระ 2 ครั้ง -
        # drop_ratio ที่ได้จะเหมือนกันหรือใกล้กันมากผิดธรรมชาติ (ยืนยันจาก log EB66-01:
        # pairwise idx=1 และ tail_stepdown idx=0 มี drop_ratio=0.23156868... เหมือนกันทุกหลัก
        # พร้อม height_source=None ทั้งคู่) → ไม่ flag ทั้งคู่เพราะไม่มีหลักฐานที่น่าเชื่อถือ
        src_a = a.get("height_source")
        src_b = b.get("height_source")
        _unreliable_sources = (None, "carried_forward_same_view")
        if src_a in _unreliable_sources and src_b in _unreliable_sources:
            continue
        if (shorter_rec.get("height_source") == "direct"
                and shorter_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
            continue
        if (shorter_rec.get("height_source") == "cross_view_corrected"
                and shorter_rec.get("cross_view_conflict_ratio", 0.0)
                > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
            continue
        # v25.89 NEW: Isolated-2-Column No-Plateau Guard - ดู docstring เต็มที่
        # _isolated_pair_no_genuine_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01) - ครอบคลุม
        # กรณีที่ Edge-Column Global Consensus Guard ด้านล่างใช้งานไม่ได้เลย (ต้องการ plateau
        # อย่างน้อย 2 คอลัมน์อื่น แต่ไฟล์นี้มีคอลัมน์รวมทั้งวิวแค่ 2 คอลัมน์ ไม่เหลือ plateau เลย)
        if _isolated_pair_no_genuine_jump(records, view_result):
            continue
        # v25.68 NEW: Edge-Column Global Consensus Guard - ดู docstring เต็มด้านบนสำหรับ
        # หลักฐาน+เหตุผล (พบจริงจาก EB66-01/EC10-03/EC19-01)
        if _is_edge_measurement_outlier(records, shorter_rec["idx"], view_result=view_result):
            continue
        # v25.72 NEW (สำคัญ - พบจริงจาก AB05-01): เดิม Edge-Column Global Consensus Guard เช็ค
        # เฉพาะฝั่ง "เตี้ยกว่า" (shorter_rec) ว่าเป็น edge-column ที่วัดต่ำผิดปกติหรือไม่ (เช่น
        # EB66-01/EC10-03/EC19-01 ที่ขอบแถวถูกวัดเตี้ยกว่าจริง) - แต่ไม่เคยตรวจสอบฝั่ง "สูงกว่า"
        # (taller_rec) เลยว่าอาจเป็น edge-column ที่วัด "สูงเกินจริง" แทน (ทิศทางตรงข้าม) - พบจริง
        # จาก AB05-01 BACK: กล่อง TNC1A-F2 ทั้ง 3 ตั้งสูงเท่ากันจริง (ยืนยันด้วยภาพ, กล่อง SKU
        # เดียวกันทั้งไฟล์ วางเรียงสม่ำเสมอ) แต่ idx0 (คอลัมน์ริมสุด/หัวตู้) วัดได้ 329.78px สูงกว่า
        # idx1(257.5px)/idx2(248.25px) มาก (plateau 2 ตั้งที่เหลือ spread แค่ 3.7% นิ่งมาก) -
        # เมื่อ idx0 กลายเป็น "taller_rec" ในคู่เปรียบเทียบ (idx0 vs idx1) มันถูกใช้เป็นฝั่ง "อ้างอิง
        # ความสูงที่ถูกต้อง" ทำให้ idx1 (ซึ่งจริงๆ สูงปกติ ตรงกับ plateau) ถูกเข้าใจผิดว่า "เตี้ยกว่า"
        # 21.9% ทั้งที่ตัวมันเองไม่ได้ผิดปกติเลย - ต้นเหตุที่แท้จริงคือ idx0 (ไม่ใช่ idx1)
        # FIX: ตรวจสอบ taller_rec ด้วยกฎเดียวกัน (ไม่ว่าจะเป็นตัวที่ถูก mark หรือไม่) - ถ้า
        # taller_rec เป็น edge-column ที่เบี่ยงเบนจาก plateau ของคอลัมน์อื่นเกินเกณฑ์เช่นกัน แสดงว่า
        # "ค่าอ้างอิง" ที่ใช้เปรียบเทียบทั้งคู่ไม่น่าเชื่อถือ ไม่ควร flag ความเสี่ยงจากคู่นี้เลย
        if _is_edge_measurement_outlier(records, taller_rec["idx"], view_result=view_result):
            continue
        # v25.82 NEW (สำคัญ - พบจริงจาก AC03-02, ผู้ใช้ขอให้ตรวจสอบ "back view วาดกรอบไม่ตรง
        # column") - ดู docstring เต็มที่ _has_internal_sharp_jump สำหรับหลักฐาน+เหตุผล: ถ้าฝั่งใด
        # ฝั่งหนึ่ง (taller/shorter) มีรอยกระโดดคมชัดของ cargo_top_y อยู่ลึกกลางคอลัมน์ตัวเอง (ไม่ใช่
        # ใกล้ขอบ) แสดงว่า Phase 1B พลาด seam จริงระหว่างกล่อง 2 ใบสีเดียวกันที่สูงต่างกัน ทำให้ค่า
        # height_px ที่วัดได้เป็นค่าผสม (blend) ของ 2 ความสูงจริง ไม่น่าเชื่อถือพอจะ flag/วาดกรอบ
        # v25.85 FIX (สำคัญ - พบจริงจาก AC03-02, ดู docstring เต็มที่
        # _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES): เพิ่มเงื่อนไข AND n_samples ต่ำ - ไม่ใช่แค่มี
        # jump ก็ suppress ทันทีเหมือน v25.82 เดิม (ซึ่งทำให้ AC03-02 BACK idx7(n=57)/idx8 ความ
        # เสี่ยงจริงถูกระงับผิดพลาด ทั้งที่ robust-fit จัดการ jump ได้เองแล้วเมื่อ n_samples สูงพอ)
        if view_result is not None:
            cty_check = view_result.get("cargo_top_y")
            if cty_check is not None and (
                    (shorter_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                     and _has_internal_sharp_jump(cty_check, shorter_rec["x_range"]))
                    or (taller_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                        and _has_internal_sharp_jump(cty_check, taller_rec["x_range"]))):
                continue
        # v25.77 NEW (สำคัญ - พบจริงจาก AA05-02/AA05-04 หลังทดสอบ v25.76, 31-Aug-2026): เดิม
        # Edge-Column Global Consensus Guard (บรรทัดด้านบน) เช็คแค่คอลัมน์ "ริมสุดของทั้งแถว"
        # (idx==0/max) แต่ไม่ครอบคลุมคู่เปรียบเทียบที่เป็น "คอลัมน์กลาง" ที่บังเอิญคร่อมโซน apex
        # พอดี - ดู docstring เต็มที่ _pair_is_apex_affected สำหรับหลักฐาน+เหตุผล (พบจริงจาก
        # AA05-02/AA05-04: คู่ idx2(283.25px)/idx3(221.82px) ทั้งคู่เป็นสีเขียวเดียวกัน SKU
        # เดียวกัน สูงเท่ากันจริง แต่ apex_x=970 คร่อมโซนนี้พอดี ทำให้ idx3 วัดต่ำกว่าจริงจาก
        # ความชัน isometric ต่อเนื่อง ไม่ใช่ apex ตัดข้อมูลของตัวเอง - guard เดิมทั้งหมดจึงไม่จับ)
        # FIX: ถ้าคู่นี้อยู่ในโซนอิทธิพลของ apex (apex_x ตกอยู่ในช่วง x-range รวมของทั้งคู่) ให้
        # ตรวจสอบเพิ่มเติมด้วย _edge_outlier_has_genuine_seam_jump (ฟังก์ชันเดียวกับที่ Edge-
        # Column Guard ใช้อยู่แล้ว) - ถ้าไม่พบ jump จริงที่ seam (คืนค่า False ชัดเจน) ให้ไม่ flag
        # (ปลอดภัยกว่าเพราะเป็นการเปลี่ยนแปลงราบเรียบต่อเนื่องจาก isometric slope ไม่ใช่ step
        # จริง) - ถ้าตรวจไม่ได้ (None) หรือพบ jump จริง (True) ให้ผ่านตามปกติ (ไม่ suppress โดย
        # ไม่มีหลักฐาน - เช่น AC03-02/AB03-04 ที่ต้องยังคง flag ถูกต้องเหมือนเดิม)
        # v25.77 FIX (สำคัญ - พบ regression จริงจาก AB03-04 ระหว่างทดสอบ): เดิมใช้ guard ใหม่นี้
        # กับทุกคู่ที่ apex-affected โดยไม่สนใจว่าฝั่งใดมี height_source ที่ไม่น่าเชื่อถืออยู่แล้ว
        # (apex_fallback/apex_partial_cut) - พบว่า AB03-04's idx1 (apex_partial_cut, ปนเปื้อน
        # จากปรากฏการณ์ "isometric roof-overhang bleed" ที่หลังคาของกล่องสูงยื่นล้ำมาทับโซน
        # ใกล้ seam) ทำให้ pixel ดิบที่ _edge_outlier_has_genuine_seam_jump ใช้ตรวจสอบ (ไม่กรอง
        # สี) เห็นการเปลี่ยนแปลง "ค่อยเป็นค่อยไป" ที่ seam (คนละสาเหตุกับ AA05-02 แต่ให้ผลลัพธ์
        # เดียวกันคือ False) ทั้งที่เป็นความเสี่ยงจริงที่ยืนยันแล้ว (ผู้ใช้ยืนยันด้วยภาพ 57.4%)
        # FIX: จำกัดให้ guard ใหม่นี้ทำงานเฉพาะเมื่อทั้ง 2 ฝั่งมี height_source == "direct" เท่านั้น
        # (ไม่มีฝั่งใดติดป้าย apex_fallback/apex_partial_cut อยู่แล้ว) - เพราะกรณีที่มีป้ายเหล่านี้
        # ติดอยู่แล้ว มี guard เฉพาะทาง (_APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO แบบ threshold-
        # gated) ดูแลอยู่แล้วอย่างเหมาะสมกว่า ไม่ควรให้ guard ใหม่นี้มาซ้อนทับ/ขัดแย้งกัน
        _both_sides_direct = (taller_rec.get("height_source") == "direct"
                               and shorter_rec.get("height_source") == "direct")
        if (_both_sides_direct and view_result is not None
                and _pair_is_apex_affected(view_result, a, b)):
            has_genuine_jump = _edge_outlier_has_genuine_seam_jump(view_result, shorter_rec, taller_rec)
            if has_genuine_jump is False:
                continue
            # v25.89 NEW (สำคัญ - พบจริงจาก EC26-01 ที่ผู้ใช้แนบ 2-Sep-2026, ผู้ใช้ยืนยันด้วยภาพ
            # ว่า "ตั้งกล่องน้ำเงินและตำแหน่งติดกัน" (ADVSE สีเดียวกัน SKU เดียวกัน) ปกติปลอดภัย
            # แต่ pairwise_floor_jump ยัง flag อยู่): ยืนยันด้วยข้อมูลจริงระดับ pixel ว่า
            # _edge_outlier_has_genuine_seam_jump คืน True ผิดพลาด (window-median scan ถูก
            # ความชันธรรมชาติที่ชันขึ้นใกล้ apex หลอก - ช่วง scan ±40px รอบ seam ไปครอบคลุมโซนที่
            # floor ลาดชันตามธรรมชาติของภาพ isometric ใกล้ apex พอดี ทำให้ median ของหน้าต่างซ้าย/
            # ขวาต่างกันมาก ทั้งที่ cargo_top_y ดิบ (per-pixel) ราบเรียบต่อเนื่องสนิทตลอดช่วง ไม่มี
            # jump คมชัดที่จุดใดเลย - ยืนยันด้วย _has_internal_sharp_jump()=False) - ต่างจาก
            # AC03-02/AB03-04 (ที่ guard นี้ถูกออกแบบมาใช้งานถูกต้อง) ซึ่งมี jump คมชัดจริงแบบ
            # single-pixel step (>=35px ภายใน 1px) ที่ has_internal_sharp_jump ตรวจพบได้เช่นกัน
            # FIX: เพิ่มการตรวจสอบซ้ำด้วย _has_internal_sharp_jump (เชื่อถือได้มากกว่าเพราะดู
            # per-pixel step แทน window-median) - ถ้า _edge_outlier_has_genuine_seam_jump บอกว่า
            # "มี jump จริง" (True) แต่ _has_internal_sharp_jump ไม่พบ jump คมชัดจริงเลยในช่วงรวม
            # ของคู่นี้ ให้เชื่อ _has_internal_sharp_jump แทน (เข้มงวดกว่า, พิสูจน์แล้วว่าแยกแยะ
            # true/false positive ได้แม่นยำใน AC03-02/EA03-01) แล้ว suppress - ไม่กระทบ AC03-02/
            # AB03-04 เดิมเพราะทั้งคู่มี genuine single-pixel jump จริง (has_internal_sharp_jump
            # จะคืน True เช่นกัน ผ่านเงื่อนไขนี้ไปได้ตามปกติ)
            cty_apex_check = view_result.get("cargo_top_y")
            if cty_apex_check is not None:
                lo_ab = min(a["x_range"][0], b["x_range"][0])
                hi_ab = max(a["x_range"][1], b["x_range"][1])
                if not _has_internal_sharp_jump(cty_apex_check, (lo_ab, hi_ab)):
                    continue
        # v25.83 NEW (สำคัญ - พบจริงจาก ED85-01, ดู docstring เต็มที่ _pair_is_apex_residual_zone
        # สำหรับหลักฐาน+เหตุผล): ต่างจาก guard ด้านบน (v25.77) ที่จำกัดเฉพาะ _both_sides_direct -
        # กรณีนี้ taller_rec (idx5) มี height_source="cross_view_corrected" (ไม่ใช่ "direct") จึง
        # ไม่ผ่านเงื่อนไขเดิม แต่ seam-jump verification ตรวจสอบ pixel ดิบ (cargo_top_y) ของ view
        # นี้เองโดยตรง ไม่ได้ขึ้นกับว่า height_px ที่ใช้จริงถูกแก้ไขมาจาก cross-view หรือไม่ - จึงยัง
        # คงแม่นยำในการยืนยัน "ความจริงทางเรขาคณิต" ได้เหมือนเดิม (ต่างจาก apex_partial_cut ที่ต้อง
        # ระวังเพราะ pixel ดิบเองอาจปนเปื้อนจาก roof-overhang bleed - คนละสาเหตุกับ cross_view_
        # corrected ซึ่งเป็นแค่การเลือกใช้ค่าจากอีก view เท่านั้น ไม่กระทบ pixel ดิบของ view นี้เอง)
        # FIX: ผ่อนคลายเงื่อนไขให้ยอมรับ "cross_view_corrected"/"cross_view_filled" เพิ่มจาก
        # "direct" เดิม (ยังคงกัน apex_fallback/apex_partial_cut ออกเสมอทั้ง 2 ฝั่ง เพราะมีความเสี่ยง
        # pixel ปนเปื้อนโดยเฉพาะตามที่ AB03-04 พิสูจน์ไว้) และตรวจสอบเงื่อนไข apex เพิ่มเติมด้วย
        # _pair_is_apex_residual_zone (ครอบคลุมกรณี 'ทั้งคู่อยู่ฝั่งเดียวกันของ apex' ที่
        # _pair_is_apex_affected เดิมไม่ครอบคลุม)
        _reliable_sources = ("direct", "cross_view_corrected", "cross_view_filled")
        _both_sides_reliable = (taller_rec.get("height_source") in _reliable_sources
                                 and shorter_rec.get("height_source") in _reliable_sources)
        if (_both_sides_reliable and view_result is not None
                and (_pair_is_apex_affected(view_result, a, b)
                     or _pair_is_apex_residual_zone(view_result, a, b))):
            has_genuine_jump2 = _edge_outlier_has_genuine_seam_jump(view_result, shorter_rec, taller_rec)
            if has_genuine_jump2 is False:
                continue
            # v25.89 NEW: mirror จากจุดเดียวกันด้านบน (_both_sides_direct block) - ดู docstring
            # เต็มที่นั่นสำหรับหลักฐาน+เหตุผล (พบจริงจาก EC26-01)
            cty_apex_check2 = view_result.get("cargo_top_y")
            if cty_apex_check2 is not None:
                lo_ab2 = min(a["x_range"][0], b["x_range"][0])
                hi_ab2 = max(a["x_range"][1], b["x_range"][1])
                if not _has_internal_sharp_jump(cty_apex_check2, (lo_ab2, hi_ab2)):
                    continue
        threshold = taller_h * (1 - STEP_DOWN_PAIRWISE_DROP_RATIO)
        floor_jump = None
        # v25.71 NEW (สำคัญ - พบจริงจาก ED84/ED85-01/02/03, 30-Aug-2026): เดิมไม่มี reliability
        # guard ใดๆ เลยสำหรับ height_source="apex_fallback" (guard ที่มีอยู่เดิมเช็คแค่ n_samples
        # เมื่อ height_source=="direct" เท่านั้น) ทั้งที่ docstring ของ compute_stack_heights_px
        # เองระบุไว้ชัดเจนแล้วว่า apex_fallback คือค่าที่วัดจากช่วง "หลังจุดยอด isometric" ซึ่ง
        # "เอียงคนละทิศ, height ผิดเพี้ยนเป็นระบบ" (ไม่ใช่แค่ noise สุ่ม แต่เป็น bias ที่รู้ทิศทาง
        # อยู่แล้ว) - ยืนยันด้วยข้อมูลจริงข้าม 4 ไฟล์ที่ไม่เกี่ยวข้องกันเลย (ED84, ED85-01/02/03):
        # ทุกไฟล์มี apex_fallback ที่คอลัมน์ริมสุดของ view ได้ n_samples=67 "เหมือนกันเป๊ะ" (ต่าง
        # SKU/ขนาดกล่องกันคนละไฟล์ - เป็นไปไม่ได้ทางสถิติที่จะบังเอิญเท่ากันขนาดนี้ถ้าเป็นการวัด
        # กล่องจริง) พิสูจน์ว่าเป็น artifact ทางเรขาคณิตที่ผูกกับตำแหน่ง apex คงที่ของ container
        # (scale/มุมกล้องเดียวกัน) ไม่ใช่ความสูงกล่องจริง - เกิดปัญหาซ้ำในทั้ง detect_step_down_
        # pairwise, detect_step_down_crossview, และ detect_tail_stepdown (ทุกกลไกที่ไม่เคยตรวจ
        # source นี้มาก่อน)
        # FIX: ถ้าฝั่งที่ "เตี้ยกว่า" (จะถูกใช้เป็นหลักฐาน flag ความเสี่ยง) เป็น apex_fallback ให้
        # ไม่ flag เลย (เฉพาะ subtype='pairwise' ที่ใช้ threshold เทียบความสูงตรงๆ เท่านั้น -
        # ไม่กระทบ subtype='pairwise_floor_jump' ด้านล่างซึ่งมีหลักฐานอิสระคนละตัว คือ floor_jump
        # ที่วัดจากพื้นตู้ ไม่ใช่ยอดกล่อง จึงไม่ได้รับผลกระทบจาก apex bias นี้)
        if shorter_rec.get("height_source") == "apex_fallback":
            continue
        # v25.83 NEW (สำคัญ - พบจริงจาก ED85-02/ED85-03, 31-Aug-2026 - ผู้ใช้ระบุว่า FRONT view
        # วาดกรอบตรงกล่องสีม่วง TGT1G ทั้งที่ไม่ควรต้องวาด): เดิม guard ด้านบน (v25.71) เช็คเฉพาะ
        # shorter_rec (ฝั่งที่จะถูก flag ว่า "เตี้ยกว่า") ว่าเป็น apex_fallback หรือไม่ - แต่ไม่เคย
        # ตรวจสอบ taller_rec (ฝั่งที่ใช้เป็น "ค่าอ้างอิงความสูงกว่า" สำหรับคำนวณ drop_ratio) เลย
        # ทั้งที่ apex_fallback เป็นค่าที่ระบบเองยืนยันแล้วว่า "เอียงคนละทิศ, height ผิดเพี้ยนเป็น
        # ระบบ" ไม่ว่าจะถูกใช้เป็นฝั่งไหนก็ตาม - ยืนยันด้วยข้อมูลจริง ED85-02/03: FRONT idx7
        # (x_range กว้างเท่าคอลัมน์ปกติ, height_source="apex_fallback", h=306.3px/307.3px) ถูกใช้
        # เป็น taller_rec เทียบกับ idx8 (h=177.2px, direct) ได้ drop_ratio=42.1%/42.3% เกินเกณฑ์
        # 20% มาก - ทำให้เกิด STEP_DOWN_RISK ที่วาดกรอบคร่อมตำแหน่งกล่องผิดพลาด (ไม่มีหลักฐานอื่น
        # ยืนยันว่า idx7 สูงจริง 306px - อาจเป็นค่าที่เอนเอียงจาก apex bias เดียวกับที่ v25.71
        # พิสูจน์ไว้แล้ว ทำให้ไม่ควรเชื่อว่าเป็น "ค่าอ้างอิงที่ถูกต้อง" สำหรับคำนวณ drop_ratio)
        # FIX: เพิ่มการตรวจสอบ taller_rec ด้วยเงื่อนไขเดียวกัน - ถ้า taller_rec เป็น apex_fallback
        # เช่นกัน ไม่ flag ความเสี่ยงจากคู่นี้เลย (ค่าอ้างอิงไม่น่าเชื่อถือพอจะใช้ตัดสิน)
        if taller_rec.get("height_source") == "apex_fallback":
            continue
        # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด ยังมีกรอบแดง
        # คือกรอบซ้ายสุด" หลังทดสอบ v25.75, 31-Aug-2026): เดิม guard ด้านบนเช็คเฉพาะ
        # height_source=="apex_fallback" (กรณี apex ตัดข้อมูลจนเหลือ<3จุด ต้อง fallback ใช้ช่วง
        # เต็ม) แต่ไม่เคยครอบคลุมกรณี "apex ตัดข้อมูลกลางคอลัมน์จริง (>=3 จุดเหลือ แต่ coverage
        # ต่ำ)" ซึ่งได้ label ใหม่ "apex_partial_cut" (v25.76 - ดู docstring เต็มที่
        # compute_stack_heights_px ใกล้ตัวแปร apex_mid_cut) - ทิศทางของความเอนเอียงที่ยืนยันแล้ว
        # คือ "อาจสูงเกินจริง" (eff_mid ถูกเลื่อนเข้าใกล้ apex/จุดสูงสุดของเส้นโค้ง isometric มาก
        # ขึ้นเมื่อ coverage ยิ่งต่ำ) - ถ้าถูกใช้เป็น taller_rec (ค่าอ้างอิง "สูงกว่า") ความเอนเอียง
        # นี้จะทำให้ drop_ratio ที่คำนวณได้ "สูงเกินจริง" ไปด้วย เสี่ยง false-positive เมื่อ
        # drop_ratio ที่แท้จริงอยู่ในโซนก้ำกึ่ง (ยืนยันจาก AB03-04: idx1(apex_partial_cut,taller)
        # vs idx0(shorter) drop=14.5% - เกิดจากความเอนเอียงล้วนๆ ควร suppress)
        # ROOT CAUSE ที่ต้องระวัง (พบระหว่างทดสอบ): ถ้า suppress "เสมอ" ทุกครั้งที่ taller_rec
        # เป็น apex_partial_cut โดยไม่ดู drop_ratio เลย จะไปกระทบคู่อื่นที่ apex_partial_cut ยังคง
        # เป็นค่าอ้างอิงที่ถูกต้องเพียงพอ (ยืนยันจาก AB03-04 เช่นกัน: idx1(apex_partial_cut,
        # taller) vs idx2(shorter,navy) drop=57.4% - เป็นความเสี่ยงจริงที่ผู้ใช้ยืนยันแล้ว ไม่ควร
        # suppress เพราะความเอนเอียงระดับ ~15-20% ไม่มีทางอธิบาย drop สูงถึง 57% ได้)
        # FIX: จำกัดการ suppress เฉพาะเมื่อ drop_ratio อยู่ในโซนก้ำกึ่งที่ความเอนเอียงอาจอธิบายได้
        # จริง (ต่ำกว่า _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO=0.25) - ถ้า drop_ratio สูงเกิน
        # เกณฑ์นี้ ให้เชื่อว่าเป็นความเสี่ยงจริง ไม่ suppress (ปลอดภัยสำหรับทั้ง 2 กรณีที่ยืนยัน
        # แล้วจาก AB03-04)
        _drop_check = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
        if (taller_rec.get("height_source") == "apex_partial_cut"
                and _drop_check < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
            continue
        # v25.84 NEW (สำคัญ - พบจริงจาก EA03-01, ดู docstring เต็มที่ _APEX_PARTIAL_CUT_MIN_SAMPLES
        # สำหรับหลักฐาน+เหตุผล): guard ด้านบน (v25.76) ใช้แค่ drop_ratio ตัดสินใจ - ไม่ครอบคลุมกรณีที่
        # apex_partial_cut มี n_samples ต่ำผิดปกติมาก (3 จุด เทียบปกติ 41-47 จุด) จนค่าที่วัดได้ไม่มี
        # ความหมายทางกายภาพเลย แม้ drop_ratio จะสูงกว่าเกณฑ์เดิมก็ตาม (เพราะ drop_ratio คำนวณจากค่าที่
        # ผิดพลาดตั้งแต่ต้น ไม่ใช่สัญญาณที่เชื่อถือได้อีกต่อไป) - ตรวจสอบทั้ง taller/shorter เพราะฝั่ง
        # ใดก็ตามที่ n_samples ต่ำขนาดนี้ไม่ควรถูกใช้เป็นค่าอ้างอิงหรือเป้าหมายเลย
        if (taller_rec.get("height_source") == "apex_partial_cut"
                and taller_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
            continue
        if (shorter_rec.get("height_source") == "apex_partial_cut"
                and shorter_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
            continue
        # v25.74 NEW: Multi-Color Merge Recheck Guard - mirror จาก detect_step_down_crossview
        # ทุกประการ (ดู docstring เต็มที่ _recheck_stack_height_via_color สำหรับหลักฐาน+เหตุผล -
        # พบจริงจาก AB03-04) - ใช้ view_result เดียวกันของทั้งคู่เพราะเป็น pairwise (view เดียวกัน)
        pairwise_recheck_suppressed = False
        if view_result is not None:
            expected_colors = view_result.get("stack_expected_colors")
            def _expected_color_of_pw(rec):
                if expected_colors is None or rec["idx"] >= len(expected_colors):
                    return None
                return expected_colors[rec["idx"]]
            taller_color_pw = _expected_color_of_pw(taller_rec)
            shorter_color_pw = _expected_color_of_pw(shorter_rec)
            if shorter_color_pw is None and taller_color_pw is not None:
                recheck = _recheck_stack_height_via_color(
                    view_result, shorter_rec["x_range"], taller_color_pw)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (recheck_h / taller_h) if taller_h > 0 else 0
                    print(f"[RECHECK_PAIRWISE] view={view_label} shorter idx={shorter_rec['idx']} "
                          f"multi-color merge - recheck สี {taller_color_pw} ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n},resid={recheck_resid:.2f}) เทียบเดิม={shorter_h:.1f}px "
                          f"-> recheck_drop={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_PAIRWISE_DROP_RATIO:
                        pairwise_recheck_suppressed = True
            elif taller_color_pw is None and shorter_color_pw is not None:
                recheck = _recheck_stack_height_via_color(
                    view_result, taller_rec["x_range"], shorter_color_pw)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (shorter_h / recheck_h) if recheck_h > 0 else 0
                    print(f"[RECHECK_PAIRWISE] view={view_label} taller idx={taller_rec['idx']} "
                          f"multi-color merge - recheck สี {shorter_color_pw} ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n},resid={recheck_resid:.2f}) เทียบเดิม={taller_h:.1f}px "
                          f"-> recheck_drop={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_PAIRWISE_DROP_RATIO:
                        pairwise_recheck_suppressed = True
        if pairwise_recheck_suppressed:
            continue
        if shorter_h < threshold:
            drop_ratio = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            risks.append({
                "risk_type": "STEP_DOWN_RISK", "subtype": "pairwise", "view": view_label,
                "mark_view": view_label,
                "mark_stack_idx": taller_rec["idx"], "mark_x_range": taller_rec["x_range"],
                "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                "drop_ratio": drop_ratio, "pair_indices": (a["idx"], b["idx"]),
                # v25.57 NEW: เก็บ height_source/n_samples ของฝั่ง shorter (ตัวที่ตัดสินใจ flag
                # หรือไม่) ไว้จริงใน risk dict เพื่อให้ debug print ตรวจสอบได้ (เดิม print เห็น
                # None เสมอเพราะ key นี้ไม่เคยถูกใส่)
                "height_source": shorter_rec.get("height_source"),
                "n_samples": shorter_rec.get("n_samples"),
            })
        elif local_floor_y is not None:
            drop_ratio_check = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            if drop_ratio_check >= 0.125:
                x0a, x1a = a["x_range"]
                x0b, x1b = b["x_range"]
                if x1a <= x0b:
                    floor_jump = _p1b_compute_floor_jump(local_floor_y, x0a, x1a, x1b)
                elif x1b <= x0a:
                    floor_jump = _p1b_compute_floor_jump(local_floor_y, x0b, x1b, x1a)
                if floor_jump is not None and floor_jump >= STEP_DOWN_FLOOR_JUMP_MIN_PX:
                    risks.append({
                        "risk_type": "STEP_DOWN_RISK", "subtype": "pairwise_floor_jump",
                        "view": view_label, "mark_view": view_label,
                        "mark_stack_idx": shorter_rec["idx"], "mark_x_range": shorter_rec["x_range"],
                        "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                        "drop_ratio": drop_ratio_check, "pair_indices": (a["idx"], b["idx"]),
                        "floor_jump_px": floor_jump,
                        # v25.57 NEW: ดูหมายเหตุเดียวกับ subtype 'pairwise' ด้านบน
                        "height_source": shorter_rec.get("height_source"),
                        "n_samples": shorter_rec.get("n_samples"),
                    })
    return risks


def detect_step_down_hidden_behind(view_result, records, view_label):
    """v25.23 NEW: STEP_DOWN_RISK (hidden_behind) - ตรวจกล่องแถวหลัง (ข้ามความกว้างตู้) ที่
    ซ่อนอยู่หลังกล่องแถวหน้าในคอลัมน์เดียวกัน แต่สูงกว่าจนหลังคาโผล่พ้นขึ้นมา (top-face
    bleed-through) - คนละกลไกจาก pairwise/cross_view เดิม (ซึ่งเทียบระหว่างคอลัมน์ ไม่ใช่
    ภายในคอลัมน์เดียวกัน) ใช้ _detect_hidden_behind_split เป็นตัวตรวจจับ (ดู docstring
    ที่นั่นสำหรับหลักฐาน+เกณฑ์เต็ม) ข้ามคอลัมน์ที่เป็น is_corner_duplicate=True เสมอ (เข้ากับ
    กฎเดิมทั้ง 3 ข้อ - ไม่ flag บริเวณมุมกล้องที่รู้อยู่แล้วว่านับซ้ำ)

    วาด marker เฉพาะ 'โซนที่กล่องซ่อนหลังโผล่ให้เห็น' (จาก split_x ถึงขอบคอลัมน์) ไม่ใช่ทั้ง
    คอลัมน์ เพื่อความแม่นยำของตำแหน่งกรอบ (คำนวณ abs_box ตรงที่นี่เลย แทนการพึ่ง
    risk_abs_box+stack_heights เดิม เพราะ 'ตั้ง' นี้ไม่ได้มี index ของตัวเองใน stack_heights)

    v25.70 NEW (สำคัญ - พบจริงจาก EE03-01, ดู docstring เต็มที่ _detect_hidden_behind_split
    สำหรับหลักฐาน+เหตุผล): รองรับทิศทาง 'down' เพิ่มเติม (ฝั่งซ้าย/ก่อน split สูงกว่า) นอกเหนือ
    จากทิศทาง 'up' เดิม (ฝั่งขวา/หลัง split สูงกว่า) - ทั้ง 2 ทิศทาง mark 'ฝั่งที่สูงกว่า' เสมอ
    (ตรงกับหลักการเดียวกับ STEP_DOWN_RISK subtype อื่นทั้งหมดที่ mark กองสูงกว่าเป็นแหล่งเสี่ยง
    ล้มทับกองเตี้ยกว่า) - ทิศทาง 'up': mark จาก split_x ถึง x1 (พฤติกรรมเดิมทุกประการ) | ทิศทาง
    'down': mark จาก x0 ถึง split_x แทน (ฝั่งที่สูงกว่าอยู่ก่อน split)"""
    risks = []
    hidden_behind = view_result.get("hidden_behind", {})
    ox, oy = view_result["crop_origin_x"], view_result["crop_origin_y"]
    local_floor_y = view_result["local_floor_y"]
    for idx, info in hidden_behind.items():
        if idx >= len(records):
            continue
        parent = records[idx]
        if parent.get("is_corner_duplicate"):
            continue
        split_x, x1 = info["split_x"], info["x1"]
        x0 = info.get("x0", split_x)  # v25.70: fallback=split_x กันพังถ้า key ไม่มี (เผื่อ
        # เรียกจากที่อื่นที่ยังไม่ได้อัพเดต - ไม่ควรเกิดขึ้นจริงเพราะแก้ที่เดียวกันแล้ว)
        hidden_h = info["hidden_height"]
        direction = info.get("direction", "up")  # v25.70 NEW: default='up' รักษาพฤติกรรมเดิม
        if direction == "down":
            mark_x0, mark_x1 = x0, split_x
        else:
            mark_x0, mark_x1 = split_x, x1
        # v25.70 NEW (สำคัญ - พบจริงจาก EE03-01): เดิม mark_x0/mark_x1 อาจแคบมาก (พบจริง 10px
        # เท่านั้น) เพราะ boundary ของ Phase 1B (x0/x1 ของคอลัมน์) วางคลาดเคลื่อนจากตำแหน่ง split
        # จริงเล็กน้อย ทำให้กรอบที่วาดได้เป็นเส้นบางแนวตั้งแทบมองไม่เห็น แทนที่จะเป็นกรอบสี่เหลี่ยม
        # ชัดเจนเหมือนกรอบคอลัมน์ทั่วไป - ใช้หลักการเดียวกับที่แก้ silhouette_notch ไปแล้ว (v25.69):
        # ถ้าความกว้างที่คำนวณได้ต่ำกว่าเกณฑ์ขั้นต่ำ ให้ pad สมมาตรทั้ง 2 ฝั่งจนถึงเกณฑ์นี้ (จำกัด
        # ไม่ให้เกินขอบเขตของ view เพื่อไม่ให้กรอบล้นออกไปนอกภาพ)
        if (mark_x1 - mark_x0) < _NOTCH_BOX_MIN_WIDTH_PX:
            pad = (_NOTCH_BOX_MIN_WIDTH_PX - (mark_x1 - mark_x0)) / 2.0
            view_sx = view_result.get("start_x", mark_x0)
            view_ex = view_result.get("end_x", mark_x1)
            mark_x0 = max(view_sx, int(round(mark_x0 - pad)))
            mark_x1 = min(view_ex, int(round(mark_x1 + pad)))
        xm = (mark_x0 + mark_x1) // 2
        floor_y_local = local_floor_y[xm] if 0 <= xm < len(local_floor_y) and local_floor_y[xm] >= 0 else None
        if floor_y_local is None:
            continue
        top_y_local = floor_y_local - hidden_h
        abs_box = (ox + mark_x0, oy + top_y_local, ox + mark_x1, oy + floor_y_local)
        risks.append({
            "risk_type": "STEP_DOWN_RISK", "subtype": "hidden_behind", "view": view_label,
            "mark_view": view_label, "mark_stack_idx": idx, "mark_x_range": (mark_x0, mark_x1),
            "taller_height_px": hidden_h, "shorter_height_px": info["front_height"],
            "drop_ratio": 1 - (info["front_height"] / hidden_h) if hidden_h > 0 else 0,
            "jump_px": info["jump_px"], "abs_box": abs_box,
        })
    return risks


def _overlapping_records(target_pos_range, other_records, min_overlap_ratio=CROSSVIEW_MIN_OVERLAP_RATIO):
    t0, t1 = target_pos_range
    t_width = max(1e-6, t1 - t0)
    matches = []
    for rec in other_records:
        r0, r1 = rec["pos_range"]
        r_width = max(1e-6, r1 - r0)
        inter = max(0.0, min(t1, r1) - max(t0, r0))
        smaller = min(t_width, r_width)
        if smaller > 0 and (inter / smaller) >= min_overlap_ratio:
            matches.append(rec)
    return matches
  
def _dedup_overlapping_stepdown_risks(risks):
    """v25.57 NEW: ถ้า 'pairwise'/'pairwise_floor_jump' (จาก detect_step_down_pairwise) และ
    'tail_stepdown' (จาก detect_tail_stepdown) flag คู่ column (view, pair_indices - ไม่สน
    ลำดับ) เดียวกัน ให้เก็บเฉพาะ pairwise/pairwise_floor_jump ไว้ (ตัด tail_stepdown ที่ซ้ำซ้อน
    ทิ้ง) - ดู docstring ที่จุดเรียกใช้ใน run_full_analysis_on_image สำหรับหลักฐาน+เหตุผลเต็ม
    (พบจริงจาก log EB66-01 29-Aug-2026)
    """
    def _pair_key(r):
        pi = r.get("pair_indices")
        if pi is None:
            return None
        return (r.get("view") or r.get("mark_view"), tuple(sorted(pi)))

    pairwise_keys = {
        _pair_key(r) for r in risks
        if r.get("risk_type") == "STEP_DOWN_RISK"
        and r.get("subtype") in ("pairwise", "pairwise_floor_jump")
        and _pair_key(r) is not None
    }
    # v25.79 NEW (สำคัญ - พบจริงจาก EA02-01 31-Aug-2026, ผู้ใช้ระบุว่า EA02-01 ควรถูกตรวจจับ
    # เหมือนไฟล์ทั่วไป ไม่ควรมีกรอบซ้ำซ้อน): เดิม dedup ด้านบนจับคู่เฉพาะ tail_stepdown vs
    # pairwise ผ่าน (view, pair_indices) เท่านั้น - แต่ detect_step_down_crossview ก็สามารถ
    # flag "คอลัมน์เดียวกันเป๊ะ" ซ้ำกับ pairwise ได้เช่นกัน (คนละกลไก คนละหลักฐาน แต่ชี้ตำแหน่ง
    # เดียวกัน) ยืนยันจาก log จริง: EA02-01 FRONT idx=1 ถูก flag ทั้งจาก pairwise (pair_indices=
    # (0,1), drop=34.6%, เทียบกับ idx0 ข้างเคียง) และจาก cross_view (drop=43.2%, เทียบกับ BACK
    # ตำแหน่งเดียวกัน) พร้อมกัน โดยทั้งคู่ mark_x_range=(860,1028) เหมือนกันเป๊ะ (ตำแหน่งวาดกรอบ
    # ซ้อนทับกันสนิท) - cross_view ไม่มี key "pair_indices"/"view" เหมือน tail_stepdown เลย
    # (มีแค่ mark_view+mark_stack_idx) จึง dedup เดิมจับไม่ได้ ทำให้นับ hazardCount เกินจริง +
    # วาดกรอบซ้อนกัน 2 ครั้งที่ตำแหน่งเดียวกัน (ผู้ใช้เห็นเป็น "สร้างกฎใหม่เกินความจำเป็น")
    # FIX: เพิ่มรอบ dedup ที่ 2 - ถ้า cross_view มี (mark_view, mark_stack_idx) ตรงกับ pairwise/
    # pairwise_floor_jump ตัวใดตัวหนึ่งเป๊ะ ให้ตัด cross_view ทิ้ง (เก็บ pairwise ไว้แทน ตาม
    # หลักการเดียวกับ tail_stepdown - pairwise คือหลักฐานโดยตรงจากเพื่อนบ้านจริงในวิวเดียวกัน
    # น่าเชื่อถือกว่า cross_view ซึ่งอาศัยการเทียบข้าม view ที่มีโอกาสคลาดเคลื่อนจาก scale/
    # reconcile สูงกว่า) - ไม่กระทบ cross_view ที่ไม่มี pairwise คู่ตรงกัน (เช่น EA02-01 idx=2
    # ซึ่งเป็นตำแหน่งอื่น ยังคง flag ตามปกติ)
    def _mark_key(r):
        return (r.get("mark_view") or r.get("view"), r.get("mark_stack_idx"))

    pairwise_mark_keys = {
        _mark_key(r) for r in risks
        if r.get("risk_type") == "STEP_DOWN_RISK"
        and r.get("subtype") in ("pairwise", "pairwise_floor_jump")
    }

    result = []
    for r in risks:
        if (r.get("risk_type") == "STEP_DOWN_RISK" and r.get("subtype") == "tail_stepdown"
                and _pair_key(r) in pairwise_keys):
            print(f"[DEDUP_STEPDOWN] ตัด tail_stepdown ซ้ำกับ pairwise ที่ view={r.get('view')} "
                  f"pair_indices={r.get('pair_indices')} ออก (เก็บ pairwise ไว้แทน)")
            continue
        if (r.get("risk_type") == "STEP_DOWN_RISK" and r.get("subtype") == "cross_view"
                and _mark_key(r) in pairwise_mark_keys):
            print(f"[DEDUP_STEPDOWN] ตัด cross_view ซ้ำกับ pairwise ที่ mark_view/idx="
                  f"{_mark_key(r)} ออก (เก็บ pairwise ไว้แทน)")
            continue
        result.append(r)
    return result


def _dedup_stepdown_corrupted_by_adjacent_notch(risks, records_front, records_back):
    """v25.79 NEW (สำคัญ - พบจริงจาก EA10-01 31-Aug-2026): เดิม detect_step_down_pairwise/
    detect_step_down_crossview ไม่เคยตรวจสอบว่า "ฝั่งเตี้ยกว่า" ของคู่เปรียบเทียบ มีขอบ x_range
    ที่ตรงพอดีกับตำแหน่ง notch_x ของ EMPTY_SPACE_RISK/silhouette_notch ที่ตรวจพบแล้วในวิวเดียวกัน
    หรือไม่ - พบว่า EA10-01 BACK idx=4(taller,350.1px)/idx=5(shorter,269.4px) ถูก flag เป็น
    STEP_DOWN_RISK pairwise (drop=23.1%) ทั้งที่ตรวจสอบภาพจริงแล้วพบว่ากล่องทั้งแถว (TSE1A-D1)
    สูงเท่ากันสนิททุกตั้ง เห็นเป็นผนังเรียบราบต่อเนื่องไม่มี step-down จริงเลย - ความผิดปกติเดียว
    ที่มีจริงคือรอยบากเล็ก (silhouette_notch, notch_x=1080, ลึก 38px) ซึ่งตรงกับขอบซ้าย (x_range
    เริ่มที่ 1080) ของ idx=5 พอดีเป๊ะ - แสดงว่ารอยบากเดียวกันนี้ "ปนเปื้อน" ค่าที่วัดได้ของ idx=5
    (บาง sample ในคอลัมน์ที่สุ่มวัดความสูงไปเจอพื้นหลัง/สีโครงสร้างตู้ที่รอยบากเผยออกมา แทนที่จะ
    เจอยอดกล่องจริง ทำให้ average/median ของคอลัมน์ถูกลากลงต่ำกว่าความจริง) ไม่ใช่กล่องเตี้ยกว่าจริง
    ROOT CAUSE: EMPTY_SPACE_RISK/silhouette_notch กับ STEP_DOWN_RISK เป็นคนละกลไกที่ทำงานอิสระ
    ต่อกันสนิท (ไม่เคยแชร์ข้อมูลกัน) แต่ตรวจจับ "ปรากฏการณ์ภาพเดียวกัน" (รอยบากที่ขอบคอลัมน์) จาก
    คนละมุมมอง - silhouette_notch ตีความถูกต้องว่าเป็นรอยบาก/ช่องว่างเล็กๆ (ไม่ใช่กล่องเตี้ยเต็ม
    ความกว้างคอลัมน์) ในขณะที่ pairwise/cross_view เข้าใจผิดว่าทั้งคอลัมน์เตี้ยกว่าจริง เพราะวัด
    ความสูงแบบ column-wide โดยไม่รู้ว่ามีรอยบากแทรกอยู่บางส่วนของคอลัมน์นั้น
    FIX: หลังคำนวณ risks ทั้งหมดแล้ว (มี EMPTY_SPACE_RISK/silhouette_notch ครบแล้ว) - สำหรับ
    STEP_DOWN_RISK subtype pairwise/pairwise_floor_jump ที่มี pair_indices ครบ ให้หา x_range ของ
    "ฝั่งเตี้ยกว่า" (index ใน pair_indices ที่ไม่ใช่ mark_stack_idx) จาก records แล้วเช็คว่ามี
    silhouette_notch ในวิวเดียวกันที่ notch_x ตกอยู่ในช่วง x_range นั้น (±5px กันขอบพอดี) หรือไม่ -
    ถ้าใช่ ให้ตัด STEP_DOWN_RISK ทิ้ง (เก็บ EMPTY_SPACE_RISK ไว้แทน เพราะเป็นตัวแทนที่ถูกต้องกว่า
    ของปรากฏการณ์เดียวกัน - ระบุ "รอยบาก/ช่องว่างเฉพาะจุด" แทน "กล่องทั้งตั้งเตี้ยกว่า" ที่คลาดเคลื่อน)
    ขอบเขตการแก้ (ปลอดภัย ไม่กระทบไฟล์อื่น): ตรวจสอบแล้วในชุดไฟล์ทดสอบทั้งหมด (AA05-02/04,
    AB03-04, AB05-01, AC03-02, EA02-01/02, EA03-01, EA10-01, EC07-02) มีเพียง EA10-01 เท่านั้นที่
    มีทั้ง STEP_DOWN_RISK(pairwise) และ EMPTY_SPACE_RISK(silhouette_notch) อยู่ในวิวเดียวกัน (BACK)
    พร้อมกัน - ไฟล์อื่นที่มี silhouette_notch (AA05-02/04, AB05-01) ไม่มี STEP_DOWN_RISK คู่กันเลย
    ในวิวเดียวกัน (safe by construction) และ EA02-01 ที่มีทั้งคู่ notch อยู่คนละวิว (BACK) กับ
    STEP_DOWN_RISK (FRONT) จึงไม่ตรงเงื่อนไข view เดียวกัน ไม่ถูกกระทบเช่นกัน
    """
    notches = [r for r in risks if r.get("risk_type") == "EMPTY_SPACE_RISK"
               and r.get("subtype") == "silhouette_notch" and r.get("notch_x") is not None]
    if not notches:
        return risks

    def _x_range_of(view_label, idx):
        records = records_front if view_label == "FRONT" else records_back
        for rec in records:
            if rec["idx"] == idx:
                return rec.get("x_range")
        return None

    result = []
    for r in risks:
        if (r.get("risk_type") == "STEP_DOWN_RISK"
                and r.get("subtype") in ("pairwise", "pairwise_floor_jump")):
            view_label = r.get("mark_view") or r.get("view")
            pair_indices = r.get("pair_indices")
            taller_idx = r.get("mark_stack_idx")
            shorter_idx = None
            if pair_indices:
                others = [i for i in pair_indices if i != taller_idx]
                if others:
                    shorter_idx = others[0]
            if shorter_idx is not None:
                shorter_range = _x_range_of(view_label, shorter_idx)
                if shorter_range is not None:
                    matched = next(
                        (n for n in notches
                         if (n.get("mark_view") == view_label)
                         and (shorter_range[0] - 5 <= n["notch_x"] <= shorter_range[1] + 5)),
                        None)
                    if matched is not None:
                        print(f"[DEDUP_NOTCH_CORRUPT] ตัด {r.get('subtype')} ซ้ำกับ "
                              f"silhouette_notch ที่ view={view_label} shorter_idx={shorter_idx} "
                              f"notch_x={matched['notch_x']} ออก (เก็บ EMPTY_SPACE_RISK ไว้แทน "
                              f"เนื่องจากรอยบากเดียวกันปนเปื้อนค่าความสูงที่วัดได้ของฝั่งเตี้ยกว่า)")
                        continue
        result.append(r)
    return result


def detect_tail_stepdown(records, view_label, view_result=None):
    """ตรวจ step-down โซนท้ายตู้ (pos > TAIL_STEPDOWN_REAR_POS_MIN)

    v25.54 FIX: เพิ่ม 2 guards ป้องกัน false-positive จากตู้เต็ม (EA07-01):

    Guard 1 — min col width: tail_rec ต้องมีความกว้าง (x_range) >= TAIL_STEPDOWN_MIN_COL_WIDTH px
    เพราะ col ที่แคบผิดปกติ (เช่น 57px ใน EA07-01 FRONT idx=0) มักเกิดจาก column boundary
    ที่ phase1b ตัดผิด หรือ orphaned col ที่แทรกเข้ามา ค่าความสูงจึงไม่น่าเชื่อถือ
    ยืนยัน: col ปกติในไฟล์ทดสอบกว้าง 80-130px, col ที่ผิดปกติ EA07-01 กว้าง 57px

    Guard 2 — height source: ถ้า tail_rec มาจาก cross_view_corrected ให้ต้องการ
    drop_ratio >= TAIL_STEPDOWN_DROP_RATIO_STRICT (เข้มกว่าปกติ) เพราะค่า cross_view_corrected
    มีความไม่แน่นอนสูงกว่า direct measurement
    ยืนยัน: EA07-01 BACK idx=6 เป็น cross_view_corrected, drop_ratio=22% ซึ่งในภาพจริงสูงเท่ากัน

    v25.57 FIX (สำคัญ - พบจริงจาก log EA07-01/EB66-01 วันที่ 29-Aug-2026, ไฟล์ที่ผู้ใช้ยืนยัน
    ว่าเป็น "เต็มตู้ ไม่มีความเสี่ยง" แต่ยัง flag ผิดอยู่หลัง v25.56): เดิม detect_tail_stepdown
    ไม่มี guard "unreliable height source" ที่ detect_step_down_pairwise มี (เพิ่มไปตั้งแต่
    v25.55 FIX#3 เพื่อแก้ปัญหา carry-forward ทำให้ drop_ratio เหมือนกันเป๊ะระหว่าง 2 กลไก) -
    ทำให้ 2 ฟังก์ชันนี้ (pairwise/pairwise_floor_jump กับ tail_stepdown) ยังคงสามารถ flag
    "คู่ column เดียวกัน" ซ้ำซ้อนกันได้จากค่าความสูงที่ไม่น่าเชื่อถือชุดเดียวกัน (ยืนยันจาก log จริง:
    EB66-01 FRONT idx=1(pairwise)/idx=0(tail_stepdown) ได้ drop_ratio=0.23156868... เหมือนกันเป๊ะ
    ทั้ง 2 subtype - เข้าเกณฑ์เดียวกับที่ v25.55 เคยพบใน pairwise ล้วนๆ มาก่อน แต่ครั้งนี้เกิดใน
    tail_stepdown ที่ไม่เคยมี guard นี้มาก่อน) เพิ่ม guard เดียวกันเข้าไปที่นี่ (mirror จาก
    detect_step_down_pairwise ทุกประการ) รวมถึง n_samples guard ที่ pairwise มีแต่ tail_stepdown
    ไม่เคยมี (STEP_DOWN_MIN_RELIABLE_SAMPLES) - เพื่อความสอดคล้องกันระหว่าง 2 กลไกที่ตรวจจับ
    รูปแบบเดียวกัน (step-down ระหว่าง 2 คอลัมน์ติดกัน) ไม่ควรมีมาตรฐานความน่าเชื่อถือต่างกัน
    """
    TAIL_STEPDOWN_MIN_COL_WIDTH = 70      # px ขั้นต่ำของ tail col (ปกติ 80-130px)
    TAIL_STEPDOWN_DROP_RATIO_STRICT = 0.25  # เกณฑ์เข้มสำหรับ cross_view_corrected

    risks = []
    valid = [r for r in records if (not r.get("is_corner_duplicate")
             and r.get("height_px") is not None
             and (r.get("height_px") or 0) > 0)]
    if len(valid) < 2:
        return risks
    valid = sorted(valid, key=lambda r: (r["pos_range"][0] + r["pos_range"][1]) / 2.0)
    tail_rec = max(valid, key=lambda r: r["pos_range"][1])
    if tail_rec["pos_range"][1] < TAIL_STEPDOWN_REAR_POS_MIN:
        return risks
    tail_idx = valid.index(tail_rec)
    if tail_idx == 0:
        return risks

    # v25.54 Guard 1: tail col ต้องกว้างพอ
    x0t, x1t = tail_rec["x_range"]
    if (x1t - x0t) < TAIL_STEPDOWN_MIN_COL_WIDTH:
        return risks

    inner_rec = valid[tail_idx - 1]

    # v25.57 NEW Guard 0: ถ้าทั้ง tail_rec และ inner_rec มาจากแหล่งที่ไม่น่าเชื่อถือ (carry-
    # forward/ยังไม่มีการวัดอิสระ) ทั้งคู่ -> ไม่ flag (mirror จาก detect_step_down_pairwise
    # v25.55 FIX#3 - ดู docstring ด้านบนสำหรับหลักฐาน)
    src_tail = tail_rec.get("height_source")
    src_inner = inner_rec.get("height_source")
    _unreliable_sources = (None, "carried_forward_same_view")
    if src_tail in _unreliable_sources and src_inner in _unreliable_sources:
        return risks

    tail_h = float(tail_rec["height_px"])
    inner_h = float(inner_rec["height_px"])
    if inner_h <= 0:
        return risks
    drop_ratio = (inner_h - tail_h) / inner_h
    if drop_ratio < TAIL_STEPDOWN_DROP_RATIO:
        return risks

    # v25.54 Guard 2: cross_view_corrected ต้อง drop_ratio สูงกว่า threshold ปกติ
    if (tail_rec.get("height_source") == "cross_view_corrected"
            and drop_ratio < TAIL_STEPDOWN_DROP_RATIO_STRICT):
        return risks

    # v25.57 NEW Guard 3 (mirror STEP_DOWN_MIN_RELIABLE_SAMPLES จาก pairwise/cross_view):
    # ถ้า tail_rec (ฝั่งที่ "เตี้ยกว่า" ที่จะถูก mark) เป็น direct fit แต่มี n_samples ต่ำกว่า
    # เกณฑ์ขั้นต่ำ (จุดข้อมูลน้อยเกินจะเชื่อถือได้ - เช่น apex ตัดข้อมูลออกไปมาก) ไม่ flag
    if (tail_rec.get("height_source") == "direct"
            and tail_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
        return risks
    # v25.57 NEW Guard 4 (mirror STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
    if (tail_rec.get("height_source") == "cross_view_corrected"
            and tail_rec.get("cross_view_conflict_ratio", 0.0)
            > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
        return risks

    # v25.89 NEW: mirror จาก detect_step_down_pairwise/crossview - ดู docstring เต็มที่
    # _isolated_pair_no_genuine_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01 - ไฟล์ที่มีคอลัมน์
    # รวมทั้งวิวแค่ 2 คอลัมน์ ทำให้ tail_stepdown เปรียบเทียบ pair เดียวกับที่ pairwise เพิ่งถูก
    # suppress ไป แต่ tail_stepdown เป็นฟังก์ชันแยก ไม่ได้รับผลจาก guard ของ pairwise เลย)
    if _isolated_pair_no_genuine_jump(records, view_result):
        return risks
    # v25.68 NEW: Edge-Column Global Consensus Guard - ดู docstring เต็มที่
    # _is_edge_measurement_outlier สำหรับหลักฐาน+เหตุผล (พบจริงจาก EC10-03/EB66-01)
    if _is_edge_measurement_outlier(records, tail_rec["idx"], view_result=view_result):
        return risks
    # v25.82 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
    # _has_internal_sharp_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก AC03-02)
    # v25.85 FIX: mirror จาก detect_step_down_pairwise - เพิ่มเงื่อนไข AND n_samples ต่ำ (ดู
    # docstring เต็มที่ _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES สำหรับหลักฐาน+เหตุผล)
    if view_result is not None:
        cty_check = view_result.get("cargo_top_y")
        if cty_check is not None and (
                (tail_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                 and _has_internal_sharp_jump(cty_check, tail_rec["x_range"]))
                or (inner_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                    and _has_internal_sharp_jump(cty_check, inner_rec["x_range"]))):
            return risks
    # v25.72 NEW (สำคัญ - พบจริงจาก AB05-01, mirror จุดเดียวกันใน detect_step_down_pairwise):
    # เดิมเช็คแค่ tail_rec (ฝั่งเตี้ยกว่า) ว่าเป็น edge-outlier หรือไม่ - แต่ inner_rec (ฝั่งอ้างอิง
    # "สูงกว่า") ก็อาจเป็น edge-column ที่วัดสูงเกินจริงได้เช่นกัน (inner_rec อาจเป็น idx=0 หรือ
    # idx สุดท้ายได้เช่นกันในไฟล์ที่มีตั้งน้อย) - ถ้า inner_rec เองเป็น edge-outlier ค่าอ้างอิงที่ใช้
    # เปรียบเทียบไม่น่าเชื่อถือ ไม่ควร flag
    if _is_edge_measurement_outlier(records, inner_rec["idx"], view_result=view_result):
        return risks

    # v25.71 NEW: apex_fallback reliability guard - ดู docstring เต็มที่จุดเดียวกันใน
    # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED84/ED85-01/02/03) - เพิ่มไว้
    # เพื่อความสอดคล้องกันทั้ง 3 กลไก แม้กรณี ED85 ที่พบจริงจะไม่ได้เกิดจาก apex_fallback ที่นี่
    # โดยตรงก็ตาม (tail_rec ที่นั่นเป็น direct source - ยังเป็นข้อจำกัดที่เหลืออยู่ - ดู CHANGELOG)
    if tail_rec.get("height_source") == "apex_fallback":
        return risks
    # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด ยังมีกรอบแดง คือ
    # กรอบซ้ายสุด" หลังทดสอบ v25.75, 31-Aug-2026): เดิม guard ด้านบนเช็คเฉพาะ tail_rec ว่าเป็น
    # apex_fallback หรือไม่ (ไม่เคยเช็ค inner_rec เลย ทั้งที่ inner_rec คือ "ค่าอ้างอิงความสูงกว่า"
    # ที่ใช้ตัดสินว่า tail_rec เตี้ยกว่าจริงหรือไม่) - พบจริงจาก AB03-04 FRONT: tail_rec=idx0
    # (x=805-955, height_source="direct", n=138/150=92% coverage - เชื่อถือได้เต็มที่) แต่
    # inner_rec=idx1 (x=955-1110, apex_x=1000 ตัดข้อมูลกลางคอลัมน์เหลือ n=39/143=27% coverage -
    # ต่ำกว่าเกณฑ์ _APEX_CUT_MIN_COVERAGE_FRACTION=35% ได้ label ใหม่ "apex_partial_cut" - v25.76)
    # ทำให้ inner_rec วัดความสูงได้ 284.5px (สูงเกินจริง เพราะจุดประเมิน eff_mid=980 อยู่ใกล้ apex/
    # จุดสูงสุดของเส้นโค้ง isometric มากผิดปกติ แทนที่จะเป็นจุดกึ่งกลางจริงของคอลัมน์ ~1032) ทำให้
    # tail_rec (243.3px, ถูกต้องจริง) ถูกเข้าใจผิดว่า "เตี้ยกว่า" 14.5% ทั้งที่เป็นกล่อง SKU
    # เดียวกัน (TEP1A-AJ) สูงเท่ากันจริง (ยืนยันจาก floor_jump ระหว่างทั้งคู่=4.8px แทบไม่มี -
    # พื้นเดียวกันจริง ไม่ใช่คนละแถว) - ต้นเหตุที่แท้จริงคือ inner_rec (ไม่ใช่ tail_rec)
    # FIX: เช็ค inner_rec ด้วยเงื่อนไขเดียวกัน (apex_fallback) ก่อนเชื่อว่าเป็นค่าอ้างอิงที่
    # น่าเชื่อถือ - ถ้าไม่น่าเชื่อถือ ไม่ flag (ปลอดภัยกว่าการเชื่อค่าที่มาจากการประเมินใกล้ apex
    # มากผิดปกติ)
    if inner_rec.get("height_source") == "apex_fallback":
        return risks
    # v25.76 FIX (สำคัญ - พบ regression จริงระหว่างทดสอบ): เดิม suppress "เสมอ" ทันทีที่พบ
    # apex_partial_cut ฝั่งใดฝั่งหนึ่ง โดยไม่ดู drop_ratio เลย - ปลอดภัยสำหรับ AB03-04 (drop=
    # 14.5%) แต่มีความเสี่ยงทางทฤษฎีที่จะ suppress คู่อื่นที่ inner_rec เป็น apex_partial_cut
    # จริงแต่ drop_ratio สูงมากจนความเอนเอียงอธิบายไม่ได้ (mirror หลักการเดียวกับที่แก้ใน
    # detect_step_down_pairwise - ดู docstring เต็มที่นั่นสำหรับหลักฐาน+เหตุผล) - จำกัดการ
    # suppress เฉพาะโซนก้ำกึ่ง (drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO=0.25)
    if (inner_rec.get("height_source") == "apex_partial_cut"
            and drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
        return risks
    if (tail_rec.get("height_source") == "apex_partial_cut"
            and drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
        return risks
    # v25.84 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
    # _APEX_PARTIAL_CUT_MIN_SAMPLES สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA03-01)
    if (inner_rec.get("height_source") == "apex_partial_cut"
            and inner_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
        return risks
    if (tail_rec.get("height_source") == "apex_partial_cut"
            and tail_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
        return risks

    risks.append({
        "risk_type": "STEP_DOWN_RISK",
        "subtype": "tail_stepdown",
        "view": view_label,
        "mark_view": view_label,
        "mark_stack_idx": tail_rec["idx"],
        "mark_x_range": tail_rec["x_range"],
        "drop_ratio": float(drop_ratio),
        "tail_height_px": tail_h,
        "inner_height_px": inner_h,
        "tail_idx": tail_rec["idx"],
        "inner_idx": inner_rec["idx"],
        # v25.57 NEW: เก็บ height_source/n_samples จริงไว้ใน risk dict เอง (ไม่ใช่แค่ใน
        # record) เพื่อให้ debug print เห็นค่าจริง (เดิม risk.get('height_source') คืน None
        # เสมอเพราะไม่เคยถูกใส่ไว้ในนี้เลย - ดู Fix ที่ [RISK] print statement)
        "height_source": src_tail,
        "n_samples": tail_rec.get("n_samples"),
        "pair_indices": (inner_rec["idx"], tail_rec["idx"]),
    })
    return risks

def detect_step_down_crossview(records_front, records_back, front_result=None, back_result=None):
    """เปรียบเทียบตำแหน่งจริงเดียวกันระหว่าง FRONT<->BACK ด้วยเกณฑ์เดียว (20%) - ข้าม
    record ที่ is_corner_duplicate=True เสมอ (ตรวจจากเส้น rail ทางเรขาคณิตจริง)"""
    risks = []
    seen_pairs = set()
    # v25.89 NEW (สำคัญ - พบจริงจาก EB73-01): ดู docstring เต็มที่ _isolated_pair_no_genuine_jump
    # สำหรับหลักฐาน+เหตุผล - คำนวณล่วงหน้าครั้งเดียวต่อวิว (ไม่ใช่ต่อคู่) ว่าวิวนี้เป็นกรณี "รวม
    # ทั้งวิวมีแค่ 2 คอลัมน์ ไม่มี plateau ให้อ้างอิง และไม่มี genuine jump จริง" หรือไม่ - ถ้าใช่
    # แสดงว่าค่าความสูงรายคอลัมน์ของวิวนี้ไม่น่าเชื่อถือพอจะใช้เปรียบเทียบข้าม view ได้ (พิสูจน์แล้ว
    # ว่าเป็นวัตถุความสูงสม่ำเสมอจริง ความต่างที่วัดได้เป็นความเอนเอียงจาก isometric slope)
    front_isolated_uniform = _isolated_pair_no_genuine_jump(records_front, front_result)
    back_isolated_uniform = _isolated_pair_no_genuine_jump(records_back, back_result)

    def _compare(rec_a, records_b_all, view_a_label, view_b_label):
        if rec_a.get("is_corner_duplicate"):
            return
        matches = _overlapping_records(rec_a["pos_range"], records_b_all)
        for rec_b in matches:
            if rec_b.get("is_corner_duplicate"):
                continue
            if rec_a["height_px"] is None or rec_b["height_px"] is None:
                continue
            key = tuple(sorted([(view_a_label, rec_a["idx"]), (view_b_label, rec_b["idx"])]))
            if key in seen_pairs:
                continue
            seen_pairs.add(key)
            taller_rec = rec_a if rec_a["height_px"] >= rec_b["height_px"] else rec_b
            shorter_rec = rec_b if taller_rec is rec_a else rec_a
            taller_h = taller_rec["height_px"]
            shorter_h = shorter_rec["height_px"]
            # v25.89 NEW: ถ้าฝั่งใดฝั่งหนึ่งมาจากวิวที่พิสูจน์แล้วว่า "รวมทั้งวิวมีแค่ 2 คอลัมน์
            # และไม่มี genuine jump จริง" (isolated uniform object) ไม่เชื่อถือค่าความสูงรายคอลัมน์
            # ของวิวนั้นพอจะเปรียบเทียบข้าม view ได้ - ไม่ flag (ดู docstring เต็มที่
            # _isolated_pair_no_genuine_jump, พบจริงจาก EB73-01)
            if ((taller_rec["view"] == "FRONT" and front_isolated_uniform)
                    or (taller_rec["view"] == "BACK" and back_isolated_uniform)
                    or (shorter_rec["view"] == "FRONT" and front_isolated_uniform)
                    or (shorter_rec["view"] == "BACK" and back_isolated_uniform)):
                continue
            # v25.48 NEW: เกณฑ์เดียวกับ pairwise - ดู STEP_DOWN_MIN_RELIABLE_SAMPLES
            if (shorter_rec.get("height_source") == "direct"
                    and shorter_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
                continue
            if (shorter_rec.get("height_source") == "cross_view_corrected"
                    and shorter_rec.get("cross_view_conflict_ratio", 0.0)
                    > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
                continue
            # v25.71 NEW: apex_fallback reliability guard - ดู docstring เต็มที่จุดเดียวกันใน
            # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED84/ED85-01/02/03)
            if shorter_rec.get("height_source") == "apex_fallback":
                continue
            # v25.83 NEW: mirror จาก detect_step_down_pairwise - เดิมเช็คแค่ shorter_rec ไม่เคย
            # เช็ค taller_rec (ค่าอ้างอิง) เลย - ดู docstring เต็มที่จุดเดียวกันใน
            # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED85-02/03)
            if taller_rec.get("height_source") == "apex_fallback":
                continue
            # v25.76 NEW (สำคัญ - เพิ่มความสอดคล้องกับ pairwise/tail_stepdown หลังพบ AB03-04):
            # เดิมไม่เคยเช็ค "apex_partial_cut" (v25.76 - label ใหม่สำหรับกรณี apex ตัดข้อมูล
            # กลางคอลัมน์จนเหลือ coverage ต่ำ แม้จะยังมี>=3จุด) เลยทั้ง 2 ฝั่ง - เพิ่มเข้าไปเพื่อ
            # ความสอดคล้องกัน (ดู docstring เต็มที่ compute_stack_heights_px/detect_step_down_
            # pairwise สำหรับหลักฐาน+เหตุผลเต็ม) - จำกัดเฉพาะโซนก้ำกึ่ง (drop_ratio ต่ำ) เท่านั้น
            # เหมือน pairwise/tail_stepdown เพื่อไม่ suppress คู่ที่ drop_ratio สูงมากจนความ
            # เอนเอียงอธิบายไม่ได้ (ป้องกัน regression แบบเดียวกับที่เคยพบใน pairwise)
            _drop_check_cv = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            if (taller_rec.get("height_source") == "apex_partial_cut"
                    and _drop_check_cv < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
                continue
            # v25.84 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
            # _APEX_PARTIAL_CUT_MIN_SAMPLES สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA03-01)
            if (taller_rec.get("height_source") == "apex_partial_cut"
                    and taller_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
                continue
            if (shorter_rec.get("height_source") == "apex_partial_cut"
                    and shorter_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
                continue
            # v25.72 NEW (สำคัญ - เพิ่มความสอดคล้องกับ pairwise/tail_stepdown หลังพบ AB05-01):
            # เดิม detect_step_down_crossview ไม่เคยเรียก Edge-Column Global Consensus Guard เลย
            # (v25.68 เพิ่มไว้แค่ pairwise/tail_stepdown เท่านั้น) ทั้งที่เป็นปัญหาเดียวกันได้ - ถ้า
            # ฝั่งใดฝั่งหนึ่ง (ไม่ว่าเตี้ยกว่าหรือสูงกว่า) เป็น edge-column ที่เบี่ยงเบนจาก plateau
            # ของคอลัมน์อื่นในวิวเดียวกันมาก ให้ไม่เชื่อการเปรียบเทียบข้าม view นี้เช่นกัน (เลือก
            # records_same_view ให้ตรงกับ view ของแต่ละฝั่งเอง)
            taller_view_records = records_front if taller_rec["view"] == "FRONT" else records_back
            shorter_view_records = records_front if shorter_rec["view"] == "FRONT" else records_back
            taller_vr = front_result if taller_rec["view"] == "FRONT" else back_result
            shorter_vr = front_result if shorter_rec["view"] == "FRONT" else back_result
            if (_is_edge_measurement_outlier(taller_view_records, taller_rec["idx"], view_result=taller_vr)
                    or _is_edge_measurement_outlier(shorter_view_records, shorter_rec["idx"], view_result=shorter_vr)):
                continue
            # v25.82/85 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
            # _has_internal_sharp_jump และ _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES สำหรับหลักฐาน+
            # เหตุผล (พบจริงจาก AC03-02/EA03-01) - v25.85 เพิ่มเงื่อนไข AND n_samples ต่ำ
            taller_cty = taller_vr.get("cargo_top_y") if taller_vr else None
            shorter_cty = shorter_vr.get("cargo_top_y") if shorter_vr else None
            if ((taller_cty is not None
                 and taller_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                 and _has_internal_sharp_jump(taller_cty, taller_rec["x_range"]))
                    or (shorter_cty is not None
                        and shorter_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                        and _has_internal_sharp_jump(shorter_cty, shorter_rec["x_range"]))):
                continue
            # v25.74 NEW: Multi-Color Merge Recheck Guard - ดู docstring เต็มที่
            # _recheck_stack_height_via_color สำหรับหลักฐาน+เหตุผล (พบจริงจาก AB03-04) - ถ้าฝั่งใด
            # ฝั่งหนึ่งของคู่เปรียบเทียบ เป็นคอลัมน์ที่ P1B รู้อยู่แล้วว่าเป็น multi-color merge
            # (stack_expected_colors[idx] is None) และอีกฝั่งมีสีคาดหวังที่รู้แน่ชัด ให้ recheck
            # ความสูงของฝั่งที่กำกวมด้วยสีของอีกฝั่ง (สมมติฐาน: ทั้งคู่ควรเป็นกล่อง SKU เดียวกันที่
            # ตำแหน่งเดียวกันจริง เห็นจาก 2 มุมกล้อง) - ถ้า recheck สำเร็จและให้ผลต่างกันน้อยกว่า
            # เกณฑ์ ให้ไม่ flag (ปฏิเสธว่าเป็นความเสี่ยงปลอมจาก isometric roof-overhang bleed)
            def _expected_color_of(rec, vr):
                colors = vr.get("stack_expected_colors") if vr else None
                if colors is None or rec["idx"] >= len(colors):
                    return None
                return colors[rec["idx"]]
            taller_color = _expected_color_of(taller_rec, taller_vr)
            shorter_color = _expected_color_of(shorter_rec, shorter_vr)
            recheck_suppressed = False
            if shorter_color is None and taller_color is not None and shorter_vr is not None:
                recheck = _recheck_stack_height_via_color(
                    shorter_vr, shorter_rec["x_range"], taller_color)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (recheck_h / taller_h) if taller_h > 0 else 0
                    print(f"[RECHECK_CROSSVIEW] shorter_rec view={shorter_rec['view']} "
                          f"idx={shorter_rec['idx']} multi-color merge ตรวจพบ - recheck ด้วยสี "
                          f"{taller_color} (จาก taller_rec) ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n}, resid={recheck_resid:.2f}) เทียบ P1B เดิม="
                          f"{shorter_h:.1f}px -> recheck_drop_ratio={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_CROSSVIEW_DROP_RATIO:
                        recheck_suppressed = True
            elif taller_color is None and shorter_color is not None and taller_vr is not None:
                recheck = _recheck_stack_height_via_color(
                    taller_vr, taller_rec["x_range"], shorter_color)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (shorter_h / recheck_h) if recheck_h > 0 else 0
                    print(f"[RECHECK_CROSSVIEW] taller_rec view={taller_rec['view']} "
                          f"idx={taller_rec['idx']} multi-color merge ตรวจพบ - recheck ด้วยสี "
                          f"{shorter_color} (จาก shorter_rec) ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n}, resid={recheck_resid:.2f}) เทียบ P1B เดิม="
                          f"{taller_h:.1f}px -> recheck_drop_ratio={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_CROSSVIEW_DROP_RATIO:
                        recheck_suppressed = True
            if recheck_suppressed:
                continue
            threshold = taller_h * (1 - STEP_DOWN_CROSSVIEW_DROP_RATIO)
            if shorter_h < threshold:
                drop_ratio = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
                risks.append({
                    "risk_type": "STEP_DOWN_RISK", "subtype": "cross_view",
                    "mark_view": taller_rec["view"],
                    "mark_stack_idx": taller_rec["idx"], "mark_x_range": taller_rec["x_range"],
                    "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                    "drop_ratio": drop_ratio, "pos_range": taller_rec["pos_range"],
                    # v25.57 NEW: ดูหมายเหตุเดียวกับ pairwise ด้านบน
                    "height_source": shorter_rec.get("height_source"),
                    "n_samples": shorter_rec.get("n_samples"),
                })

    for rec_a in records_front:
        _compare(rec_a, records_back, "FRONT", "BACK")
    for rec_b in records_back:
        _compare(rec_b, records_front, "BACK", "FRONT")

    merged = {}
    for r in risks:
        key = (r["mark_view"], r["mark_stack_idx"])
        if key not in merged or r["drop_ratio"] > merged[key]["drop_ratio"]:
            merged[key] = r
    return list(merged.values())


# v25.40 NEW (สำคัญ - "Physical Validity Guard" ตามที่ผู้ใช้สอน): เดิม reconcile_heights_
# cross_view (บรรทัด trust_a = h_a >= h_b) เลือก "เชื่อค่าที่สูงกว่าเสมอ" เมื่อทั้ง 2 ฝั่ง
# reliable เท่ากัน (both direct) โดยไม่ตรวจสอบว่าค่าที่เลือกนั้น "เป็นไปได้ทางกายภาพ" หรือไม่
# พบจริงจาก AC05-04 (ไฟล์ที่ผู้ใช้แนบ + สอนเทคนิค "ลากเส้น 2400mm เทียบกับเส้นแต่ละ idx"):
# idx3 (DITHE-AF เขียวสด รวมกับ ATFBA-AJ น้ำเงินที่ cluster ผิดพลาด) ถูก "แก้ไข" ให้มีความสูง
# 351.3px ทั้งที่ความสูงตู้จริง ณ ตำแหน่งนั้น (วัดจาก roofline fit จริง 308 จุด, resid_std=
# 0.35px) มีแค่ 354.3px - คิดเป็น 99.2% ของความสูงตู้ทั้งหมด (ควรเป็นไปไม่ได้ทางกายภาพ เพราะ
# กล่องสินค้าจริงต้องเตี้ยกว่าเพดานตู้เสมอ ไม่มีทางสูงชนเพดานพอดี)
# เทคนิคตรวจสอบ (ตามที่ผู้ใช้สอน, ยืนยันด้วยข้อมูลจริง 2 ไฟล์ AB01-02 และ AC05-04):
# "ลากเส้นจากพื้นตู้ (local_floor_y) ขึ้นไปถึงเพดานตู้ (roofline) ที่ตำแหน่ง x เดียวกับกล่อง
# แต่ละ idx - ต้องไม่มีเส้นความสูงกล่องใด ยาวเท่ากับเส้นเพดานตู้เต็มความสูง" - วัด baseline
# จาก AB01-02 (ไฟล์ปกติ ไม่มีปัญหา) ได้ค่าสูงสุด 97.0% เป็นค่าที่ "ปกติที่สุดที่เคยพบ" จึงตั้ง
# threshold ที่ 97% (สูงกว่านี้ถือว่าผิดปกติ/ไม่น่าเชื่อถือทางกายภาพ)
# FIX: ก่อนยอมรับค่าที่ "แก้ไขข้าม view" (ทั้ง cross_view_filled และ cross_view_corrected)
# ตรวจสอบว่าค่าที่จะใช้ทำให้สัดส่วน (height / local_container_height ที่ตำแหน่ง x ของ record
# นั้น) เกิน PHYSICAL_VALIDITY_MAX_RATIO หรือไม่ - ถ้าเกิน ให้ปฏิเสธการแก้ไขนั้น (คงค่าเดิม
# ของ rec_a ไว้แทน ถ้ามี, หรือข้ามการเติมค่านั้นไปเลยถ้าเป็น PASS1/fill) เพื่อความปลอดภัย
# ไม่กระทบไฟล์อื่น: การตรวจสอบนี้ทำงาน "เสริม" (additional guard) ไม่ได้แทนที่ logic เดิม -
# ถ้า local roofline หาไม่ได้ (เช่น region ไม่มีสีผนังตู้ที่ชัดเจนพอ) จะข้ามการตรวจสอบไปเลย
# (fail-safe: ใช้ logic เดิมทั้งหมดเหมือนก่อน v25.40)
PHYSICAL_VALIDITY_MAX_RATIO = 0.97
_ROOFLINE_WALL_COLOR = (179, 179, 90)  # สีแผงผนังตู้ (wall panel) - ใช้ fit roofline
_ROOFLINE_WALL_COLOR_TOL = 15
_ROOFLINE_MIN_RUN_PX = 15  # ต้องมีแนวตั้งต่อเนื่องอย่างน้อยเท่านี้ จึงนับเป็นจุด roofline
# ที่เชื่อถือได้ (กันจุดเล็กๆ ที่เป็นเงา/ขอบกล่องบังเอิญมีสีใกล้เคียงผนังตู้)
_ROOFLINE_MIN_POINTS = 5  # ต้องมีจุดที่เชื่อถือได้อย่างน้อยเท่านี้ จึง fit เส้นได้


# v25.42 NEW (สำคัญ - พบจริงจาก EB74-ALL ที่ผู้ใช้ถามว่าทำไม v25.40 แก้ไขเฉพาะ AC05-04): เดิม
# _compute_local_roofline_fit ใช้สีผนังตู้แบบ "ตายตัว" (179,179,90) เพียงสีเดียว - พบว่าไฟล์
# EB74-ALL ใช้สีผนังตู้เป็น (90,179,179) แบบเดียวกับที่ v25.41 เพิ่งแก้ไปสำหรับ
# _p1b_is_structural_container_color (โทนฟ้า/เขียวอมฟ้า G≈B แทน R≈G) - เมื่อ roofline_fit หา
# สีตายตัวเดิมไม่เจอเลย (คืนค่า None) Physical Validity Guard จะ "fail-safe" ปิดตัวเองไปทั้งหมด
# ไม่ตรวจสอบอะไรเลย ทำให้ logic เดิม (trust_a = h_a >= h_b) ทำงานตามปกติ และค่าที่ผิดพลาดจาก
# ปัญหาคนละชั้น (Phase 1B ตัดคอลัมน์ผิดพลาด ทำให้จับคู่ตำแหน่งข้าม view ผิด) จึงหลุดรอดไปโดย
# ไม่ถูกปฏิเสธ (เพราะ Guard ไม่ได้ทำงานเลยตั้งแต่ต้น ไม่ใช่เพราะ Guard ตรวจแล้วผ่าน)
#
# ความพยายามแก้ไขครั้งแรก (ใช้ _p1b_is_structural_container_color เต็ม pattern) พบ regression
# ใหม่ที่ AB01-02: การรวมทุกสีโครงสร้างตู้ (rail/wall-panel/floor-tile/rear-wall) เข้าด้วยกัน
# ทำให้จุดที่ใช้ fit เส้น roofline ปนกันจาก 2 พื้นผิวที่มีมุมเอียงต่างกันจริง (ผนังด้านข้าง vs
# ผนังหลัง/หลังคา ซึ่งเป็นคนละระนาบในภาพ isometric ไม่ใช่เส้นเดียวกัน) แม้ใช้ robust line fit
# (MAD-based rejection) ก็ยังแก้ไม่ได้ เพราะทั้ง 2 กลุ่มมีจำนวนจุดใกล้เคียงกัน (ไม่ใช่ outlier
# ส่วนน้อย) ทำให้ resid_std พุ่งสูงถึง 36.2px (เทียบ AC05-04 เดิมที่ 0.35px) เส้นที่ fit ได้จึง
# เอียงผิดจากผนังด้านข้างจริงไปมาก ทำให้ ratio ของกล่องสูงสุดขยับข้าม threshold 97% ไปเอง (จาก
# 96.9% ที่เคยผ่าน กลายเป็น 99.3% ที่ถูกปฏิเสธผิดพลาด) เกิด chain-reaction กระทบคอลัมน์อื่น
# FIX ที่ถูกต้อง: จำกัดเฉพาะสี "wall panel" (ผนังด้านข้างเท่านั้น - พื้นผิวเดียวที่ต้องการวัด
# ความสูงเพดานจริง) ไม่ใช้สีอื่นทั้งหมด (rail/floor-tile/rear-wall เป็นคนละพื้นผิว/มุมเอียง) -
# ระบุด้วยช่วง R-B แคบรอบค่า 89 (wall panel วัดได้จริง) ทั้ง 2 ทิศทาง (R≈G และ G≈B) แทนช่วงกว้าง
# 75-125 เดิมที่ออกแบบมาสำหรับ "กรองไม่ใช่กล่องสินค้า" (กว้างเกินไปสำหรับงาน roofline ที่ต้องการ
# ความแม่นยำสูงเฉพาะพื้นผิวเดียว)
_ROOFLINE_RB_TARGET = 89   # ค่า R-B ของสี wall-panel จริง (179,179,90 หรือ 90,179,179)
_ROOFLINE_RB_TOL = 15      # tolerance แคบ (74-104) แยกจาก rail(102)/floor(122)/rear-wall(80)
# ได้เพียงพอ (rear-wall ที่ 80 อาจยังเหลื่อมบ้าง แต่ปริมาณจุดของ rear-wall ในภาพจริงน้อยกว่า
# wall-panel มาก เพราะมองเห็นได้แคบกว่า - ยืนยันด้วยการทดสอบ regression ครบทุกไฟล์)
# v25.50 NEW (สำคัญ - พบจริงจาก AA02-01 ที่ผู้ใช้แนบ, พอร์ตมาจาก branch v25.48.5): _robust_local_
# line_fit (MAD-based outlier rejection) ออกแบบมาเพื่อกรอง "จุดส่วนน้อยที่เป็น noise" ออกจากจุด
# ส่วนใหญ่ที่ถูกต้อง - แต่พบว่าไฟล์ AA02-01 มี roofline เป็นรูปตัว "V" จริง (เพดานตู้แบบ isometric
# มี apex แล้วลาดลง 2 ทิศทาง เหมือนปัญหาเดียวกับพื้นตู้ที่ compute_local_floor_y เคยแก้ไปแล้ว - แต่
# _compute_local_roofline_fit ยังไม่เคยรองรับกรณีนี้) จุดข้อมูลทั้ง 2 กลุ่ม (ก่อน apex/หลัง apex)
# ต่างก็เป็นจุดที่ถูกต้องจริง ไม่ใช่ minority-noise เลย (พบ 13 จุดฝั่งซ้าย + ~30 จุดฝั่งขวาที่เป็น
# V-shape ชัดเจน) ทำให้ MAD-based rejection ไม่สามารถแยกออกได้ (ไม่มีฝั่งไหนเป็นส่วนน้อย) - fit
# เส้นตรงเส้นเดียวข้าม 2 slope ที่ต่างกันจริงจึงให้ค่า resid_std=8.7px (แย่กว่า AC05-04's 0.35px
# ถึง 25 เท่า) เส้นที่ fit ผิดนี้ทำให้ max_physical_height คำนวณผิดพลาด จนไปปฏิเสธค่าความสูงที่
# ถูกต้องจริง (BACK idx0 วัดได้ 349.89px จาก direct-fit น่าเชื่อถือสูง n=82 จุด แต่ถูก Guard
# ปฏิเสธเพราะ ratio คำนวณผิดเป็น 102.8% เกิน threshold ทั้งที่ container มี unused floor เหลือ
# 51.2 นิ้ว - แสดงว่าไม่น่าเป็นไปได้ที่กล่องจะสูงชนเพดานจริง) ทำให้ระบบไปเชื่อค่า apex_fallback
# ที่ไม่น่าเชื่อถือ (243.49px) แทน กลายเป็นซ่อนความแตกต่างของความสูงที่แท้จริงไว้ (มองด้วยตาจาก
# ภาพจริงยืนยันว่า 2 คอลัมน์ที่ถูกลดค่าลงนี้สูงใกล้เคียงกันจริงตามที่วัดได้ก่อนถูก Guard ปฏิเสธ)
# FIX: เพิ่มเกณฑ์ขั้นต่ำของคุณภาพ fit (resid_std) - ถ้า fit ที่ได้ (แม้จะผ่าน robust rejection
# แล้ว) ยังมี resid_std สูงเกินไป แสดงว่าข้อมูลเป็น multi-modal จริง (V-shape หรือสีปนกันหลาย
# พื้นผิว) ไม่ใช่แค่ noise ส่วนน้อย - เส้นตรงเส้นเดียวไม่เหมาะสมจะใช้แทนค่าจริงได้ -> คืนค่า None
# (fail-safe, ปิด Guard สำหรับตำแหน่ง/ไฟล์นี้ไปเลย ดีกว่าใช้เส้นที่ fit ผิดมาปฏิเสธค่าที่ถูกต้อง)
# เกณฑ์ที่ตั้งไว้ (3.0px) อ้างอิงจากหลักฐาน 2 จุดที่มี: AC05-04 (fit ดีจริง)=0.35px เทียบ AA02-01
# (fit แย่จาก V-shape จริง)=8.7px - ให้ margin สูงกว่าค่าดีจริงมาก (~8 เท่า) แต่ยังต่ำกว่าค่าที่รู้
# ว่าแย่มาก - regression-verified ร่วมกับ RECONCILE_MAX_CONFLICT_TO_APPLY (v25.49 AB03-04 fix)
# ทั้งคู่เป็น guard คนละจุด/คนละฟังก์ชันกัน ไม่ทับซ้อนกัน จึงรวมเข้าด้วยกันได้ปลอดภัย
_ROOFLINE_MAX_RESID_STD = 3.0


def _compute_local_roofline_fit(region, min_run=_ROOFLINE_MIN_RUN_PX,
                                 min_points=_ROOFLINE_MIN_POINTS):
    """v25.40 NEW (แก้ไข v25.42): fit เส้นตรง (slope, intercept) ของ 'roofline' (ขอบบนสุดของ
    ผนังด้านข้างตู้) จากจุดที่มองเห็นสี wall-panel เท่านั้น (ไม่ใช้สีโครงสร้างอื่นที่เป็นคนละ
    พื้นผิว/มุมเอียง เช่น ผนังหลัง/หลังคา/พื้น/ราง - ดู docstring เต็มด้านบนสำหรับเหตุผล) ต่อเนื่อง
    อย่างน้อย min_run พิกเซลในแต่ละคอลัมน์ x ของภาพ - ยืนยันด้วยข้อมูลจริง AC05-04: ได้
    resid_std=0.35px จาก 308 จุด (แม่นยำสูงมาก เพราะ container เป็น isometric ทำให้เพดานตู้เป็น
    เส้นตรงเป๊ะ) คืนค่า (slope, intercept) หรือ None ถ้าหาจุดที่เชื่อถือได้ไม่พอ (fail-safe -
    ผู้เรียกใช้ต้องรับมือกับ None)"""
    r = region[:, :, 0].astype(int)
    g = region[:, :, 1].astype(int)
    b = region[:, :, 2].astype(int)
    rb_min = _ROOFLINE_RB_TARGET - _ROOFLINE_RB_TOL
    rb_max = _ROOFLINE_RB_TARGET + _ROOFLINE_RB_TOL
    # ทิศทางที่ 1: R≈G, R-B อยู่ในช่วงแคบรอบ wall-panel (โทนน้ำตาล/ทอง)
    wall_mask = (np.abs(r - g) <= _STRUCTURAL_HUE_RG_MAX_DIFF) & \
                ((r - b) >= rb_min) & ((r - b) <= rb_max)
    # ทิศทางที่ 2: G≈B, B-R อยู่ในช่วงแคบรอบ wall-panel (โทนฟ้า/เขียวอมฟ้า - v25.41/42)
    wall_mask |= (np.abs(g - b) <= _STRUCTURAL_HUE_RG_MAX_DIFF) & \
                 ((b - r) >= rb_min) & ((b - r) <= rb_max)
    xs_pts, ys_pts = [], []
    for x in range(region.shape[1]):
        col = np.nonzero(wall_mask[:, x])[0]
        if len(col) >= min_run:
            top = col.min()
            # ตรวจสอบว่า min_run พิกเซลแรกต่อเนื่องกันจริง (ไม่ใช่แค่กระจัดกระจายบังเอิญ)
            seg = col[col < top + min_run * 2]
            if len(seg) >= min_run:
                xs_pts.append(x)
                ys_pts.append(top)
    if len(xs_pts) < min_points:
        return None
    # v25.42 FIX (สำคัญ - พบ regression จริงจาก AB01-02 หลังขยาย hue-pattern ให้กว้างขึ้น):
    # เดิมใช้ np.linalg.lstsq ธรรมดา (ไม่ทนทานต่อ outlier) - พบว่าการขยาย _p1b_is_structural_
    # container_color ให้ครอบคลุมหลายเฉดสี (rail/wall-panel/floor-tile/rear-wall ที่อยู่คนละ
    # ตำแหน่ง y ในภาพจริง ไม่ใช่ตำแหน่งเดียวกับ 'roofline' ของผนังด้านข้าง) ทำให้จุดที่ใช้ fit
    # ปนกันหลายกลุ่ม (multi-modal) เกิด noise มาก (resid_std=36.2px ในไฟล์ AB01-02 เทียบกับ
    # AC05-04 ที่ได้แค่ 0.35px) ทำให้เส้น roofline ที่ fit ได้เอียงผิดจากตำแหน่งจริงมาก ส่งผลให้
    # max_physical_height คำนวณผิดพลาด (ratio ของกล่องสูงสุดขยับจาก 96.9% ที่เคยผ่านเกณฑ์ เป็น
    # 99.3% ที่ถูก Guard ปฏิเสธผิดพลาด) เกิด chain-reaction ทำให้ค่าความสูงอื่นในคอลัมน์ใกล้เคียง
    # ถูกแก้ไขผิดตามไปด้วย (regression ที่ค่าความสูงเปลี่ยนไปมาก 189.7->126.8 เป็นต้น)
    # FIX: ใช้ _robust_local_line_fit (มีอยู่แล้วในโค้ด, iterative MAD-based outlier rejection)
    # แทน simple least-squares - กรองจุดที่ไม่ใช่ roofline จริง (จากสีโครงสร้างกลุ่มอื่นที่อยู่
    # คนละตำแหน่ง y) ออกโดยอัตโนมัติ ทำให้ fit เสถียรขึ้นมาก โดยไม่กระทบไฟล์ที่ roofline เดิม
    # สะอาดอยู่แล้ว (เช่น AC05-04 - robust fit บนข้อมูลที่ไม่มี outlier จะให้ผลเหมือน simple fit)
    xs_arr = np.array(xs_pts, dtype=float)
    ys_arr = np.array(ys_pts, dtype=float)
    fit = _robust_local_line_fit(xs_arr, ys_arr)
    if fit is None:
        return None
    # v25.50 NEW: ดู docstring เต็มที่ _ROOFLINE_MAX_RESID_STD ด้านบนสำหรับหลักฐาน+เหตุผล
    # (พบจริงจาก AA02-01 - roofline รูปตัว V ที่ robust rejection แก้ไม่ได้เพราะทั้ง 2 กลุ่ม
    # จุดข้อมูลเป็นของจริงไม่ใช่ minority-noise)
    if fit["resid_std"] > _ROOFLINE_MAX_RESID_STD:
        return None
    return fit["a"], fit["b"]


def _max_physical_height_at_x(roofline_fit, local_floor_y, x):
    """v25.40 NEW: คำนวณ 'ความสูงตู้จริงสูงสุด' ณ ตำแหน่ง x ใดๆ (จาก roofline ถึง local floor)
    คืนค่า None ถ้าคำนวณไม่ได้ (roofline_fit เป็น None หรือ floor_y ที่ตำแหน่งนั้นไม่ valid)"""
    if roofline_fit is None:
        return None
    if x < 0 or x >= len(local_floor_y):
        return None
    fy = local_floor_y[x]
    if fy < 0:
        return None
    slope, intercept = roofline_fit
    roof_y = slope * x + intercept
    h = fy - roof_y
    return h if h > 0 else None


def reconcile_heights_cross_view(records_front, records_back,
                                  min_overlap_ratio=0.5, conflict_ratio=0.10,
                                  front_result=None, back_result=None):
    """เทียบความสูงของกล่องตำแหน่งจริงเดียวกันระหว่าง FRONT<->BACK - ข้าม record ที่
    is_corner_duplicate=True เสมอ PASS1: เติมค่า None จาก cross-view PASS2: แก้ความขัดแย้ง

    v25.40 NEW: รับ front_result/back_result (view_result เต็มจาก process_view_with_height_
    on_image) เพิ่มเติม (optional - ถ้าไม่ส่งมา จะทำงานเหมือนเดิมทุกประการไม่มี guard เลย เพื่อ
    ความปลอดภัยของโค้ดที่เรียกฟังก์ชันนี้แบบเก่า) ใช้คำนวณ 'Physical Validity Guard' - ดู
    docstring เต็มด้านบน PHYSICAL_VALIDITY_MAX_RATIO สำหรับหลักฐาน+เหตุผล (ยืนยันจาก AC05-04
    ตามเทคนิคที่ผู้ใช้สอน: ลากเส้นเทียบความสูงกล่องกับความสูงตู้จริง ต้องไม่มี idx ใดเท่ากับ
    ความสูงเต็มตู้)"""
    roofline_front = (_compute_local_roofline_fit(front_result["region"])
                       if front_result is not None else None)
    roofline_back = (_compute_local_roofline_fit(back_result["region"])
                      if back_result is not None else None)

    def _violates_physical_validity(rec, height_value):
        """True ถ้า height_value ทำให้สัดส่วนเทียบความสูงตู้จริง ณ ตำแหน่ง x กึ่งกลางของ rec
        เกิน PHYSICAL_VALIDITY_MAX_RATIO - คืน False (ไม่ปฏิเสธ) ถ้าคำนวณไม่ได้ (fail-safe)"""
        view_result = front_result if rec["view"] == "FRONT" else back_result
        roofline_fit = roofline_front if rec["view"] == "FRONT" else roofline_back
        if view_result is None or roofline_fit is None:
            return False
        x0, x1 = rec["x_range"]
        xm = (x0 + x1) // 2
        max_h = _max_physical_height_at_x(roofline_fit, view_result["local_floor_y"], xm)
        if max_h is None:
            return False
        return (height_value / max_h) > PHYSICAL_VALIDITY_MAX_RATIO

    def _overlap_ratio(a, b):
        a0, a1 = a; b0, b1 = b
        inter = max(0.0, min(a1, b1) - max(a0, b0))
        smaller = min(max(1e-6, a1 - a0), max(1e-6, b1 - b0))
        return inter / smaller if smaller > 0 else 0.0

    # v25.23 FIX (Critical): rec_b (แหล่งอ้างอิง) ไม่ควรถูกกันออกเพียงเพราะ is_corner_duplicate
    # (flag นี้มีไว้ห้าม "เป็นเป้าหมายที่ถูกวาด marker" เท่านั้น ไม่ได้แปลว่าความสูงที่วัดได้
    # ใช้อ้างอิงไม่ได้ - กล่องมุมเดียวกันที่เห็นจาก 2 กล้องยังเป็นกล่องจริงกล่องเดียวกัน)
    corrections = []
    for rec_a, records_b in [(r, records_back) for r in records_front] + \
                            [(r, records_front) for r in records_back]:
        if rec_a.get("is_corner_duplicate") or rec_a["height_px"] is not None:
            continue
        best_match, best_overlap = None, 0.0
        for rec_b in records_b:
            if rec_b["height_px"] is None:
                continue
            ov = _overlap_ratio(rec_a["pos_range"], rec_b["pos_range"])
            if ov > best_overlap:
                best_overlap, best_match = ov, rec_b
        if best_match is None or best_overlap < min_overlap_ratio:
            continue
        # v25.40 NEW: Physical Validity Guard - ปฏิเสธการเติมค่าถ้าทำให้สูงเกินตู้จริง
        if _violates_physical_validity(rec_a, best_match["height_px"]):
            continue
        rec_a["height_px"] = best_match["height_px"]
        rec_a["height_source"] = "cross_view_filled"
        corrections.append((rec_a["view"], rec_a["idx"], None, best_match["height_px"]))

    # v25.45 NEW (สำคัญ - พบจริงจาก AB01-02 ที่ผู้ใช้ทดสอบ v25.44 แล้วพบว่า teal/purple ยัง
    # ไม่มี risk marker): เดิม PASS2 เขียนทับ height_px ของ record ที่ "แพ้" ทันทีระหว่างวนลูป
    # (sequential mutation) - พบว่าเมื่อ record ฝั่งหนึ่ง (เช่น BACK idx0) มี pos_range กว้างผิด
    # สัดส่วน (เพราะ FRONT span=576px กับ BACK span=462px ต่างกัน ~25% - เกิดจากการที่แต่ละ view
    # ถูก crop/render แยกกันคนละภาพ คนละ pixel-scale โดยธรรมชาติ ไม่ใช่บั๊กจากการคำนวณ extent
    # ที่แก้ไขได้ตรงๆ) จนไปทับซ้อน (overlap>min_overlap_ratio) กับ FRONT record 2 ตัวพร้อมกัน
    # (F5 overlap=0.70, F6 overlap=1.00) - ระบบประมวลผล F5 ก่อน (index น้อยกว่า) แล้ว "ชนะ" แก้ไข
    # BACK idx0 ไปก่อน จากนั้น F6 (ซึ่งควรเป็นคู่ที่แท้จริงกว่ามาก เพราะ overlap=1.00 หมายถึง
    # pos_range ของ F6 อยู่ในขอบเขตของ BACK idx0 เต็มรูปแบบ) กลับมาประมวลผลทีหลัง แล้วได้รับค่าที่
    # BACK idx0 "ปนเปื้อน" จาก F5 ไปแล้ว (292.9) แทนที่จะเห็นค่าดั้งเดิมจริงของ BACK idx0 (335.8)
    # ทำให้ F6 (purple, TPR1A-AO) ถูกตั้งเป็น 292.9 (เท่ากับ F5/teal พอดี) ซ่อน step-down risk ที่
    # แท้จริง (ค่าจริงของ F6 คือ 213.7 apex_fallback ซึ่งต่างจาก F5's 292.9 ถึง 27% - เกิน
    # threshold 20% ควรตรวจพบ STEP_DOWN_RISK แต่กลับไม่พบเพราะถูกปนเปื้อนไปก่อน)
    # ROOT CAUSE ที่แท้จริง: การประมวลผลแบบ "sequential, เขียนทับทันที" ทำให้ผลลัพธ์ขึ้นกับ
    # "ลำดับการประมวลผล" (order-dependent) ซึ่งไม่ควรเป็นเช่นนั้น - record ที่มี overlap สูงกว่า
    # (หลักฐานที่น่าเชื่อถือกว่า) ควรชนะเสมอ ไม่ว่าจะถูกประมวลผลก่อนหรือหลัง
    # ได้ทดสอบ "Method 1" (normalize extent ให้ FRONT/BACK อ้างอิงขอบเขตเดียวกัน) ตามที่ผู้ใช้
    # เสนอก่อนแล้ว พบว่าไม่สามารถแก้ปัญหาได้จริง เพราะ FRONT/BACK เป็นภาพคนละใบที่ crop/render
    # แยกจาก PDF คนละพิกัด คนละ pixel-scale โดยสิ้นเชิง (ยืนยันด้วยข้อมูลจริง: แม้แต่ column-based
    # extent จาก PHASE 1B เอง - cols_x_min/cols_x_max - ก็ยังต่างกันมากกว่าเดิม 28.6% เทียบกับ
    # floor-union extent เดิมที่ต่าง 24.7% - แสดงว่าปัญหาไม่ได้อยู่ที่วิธีคำนวณ extent แต่อยู่ที่
    # ธรรมชาติของการ render 2 ภาพแยกกัน ซึ่งไม่มีทาง "union" พิกัดข้าม coordinate system ได้ตรงๆ)
    # FIX ที่ใช้จริง (ปลอดภัยกว่ามาก เพราะไม่แตะ pos_range ที่ใช้ร่วมกับฟังก์ชันอื่น เช่น
    # detect_step_down_crossview/_rearmost_record/REAR_EMPTY_RISK เลย - ขอบเขตการแก้ไขจำกัดอยู่
    # แค่ภายในฟังก์ชันนี้เท่านั้น): เปลี่ยนจาก "ประมวลผลแล้วเขียนทับทันที" เป็น "snapshot ค่าเดิม
    # ทั้งหมดก่อน (ป้องกันการปนเปื้อนข้ามกันระหว่างการตัดสินใจ) รวบรวมข้อเสนอการแก้ไขทั้งหมดจาก
    # ทุกคู่ที่เข้าเกณฑ์ก่อน แล้วเมื่อมีหลายคู่แข่งกันแก้ไข target เดียวกัน ให้ 'คู่ที่มี overlap
    # ratio สูงสุด' ชนะเสมอ (ไม่ใช่คู่ที่ประมวลผลก่อน) แล้วค่อย apply การแก้ไขทั้งหมดพร้อมกันในตอน
    # ท้าย - ยืนยันด้วยข้อมูลจริงว่าแก้ปัญหา AB01-02 ได้ตรงจุด (F6 ชนะ F5 ในการแก้ไข BACK idx0
    # ตามที่ควรจะเป็น เพราะ overlap 1.00 > 0.70) โดยไม่กระทบ logic เดิมของกรณีอื่นๆ ที่ไม่มีการ
    # แข่งขัน (ผลลัพธ์เหมือนเดิมทุกประการเมื่อมีแค่ 1 คู่ต่อ target)
    snapshot = {}
    for rec_list in (records_front, records_back):
        for r in rec_list:
            snapshot[id(r)] = (r["height_px"], r.get("height_source", "direct"))

    proposals = {}  # id(target) -> (overlap_ratio, target_ref, new_value, correction_tuple)

    for rec_a, records_b in [(r, records_back) for r in records_front] + \
                            [(r, records_front) for r in records_back]:
        if rec_a.get("is_corner_duplicate") or snapshot[id(rec_a)][0] is None:
            continue
        best_match, best_overlap = None, 0.0
        for rec_b in records_b:
            ov = _overlap_ratio(rec_a["pos_range"], rec_b["pos_range"])
            if ov > best_overlap:
                best_overlap, best_match = ov, rec_b
        if best_match is None or best_overlap < min_overlap_ratio or snapshot[id(best_match)][0] is None:
            continue
        h_a, a_src = snapshot[id(rec_a)]
        h_b, b_src = snapshot[id(best_match)]
        higher = max(h_a, h_b)
        if higher <= 0 or abs(h_a - h_b) / higher <= conflict_ratio:
            continue
        a_reliable = a_src in ("direct", "cross_view_filled")
        b_reliable = b_src in ("direct", "cross_view_filled")
        if a_reliable and not b_reliable:
            trust_a = True
        elif b_reliable and not a_reliable:
            trust_a = False
        else:
            trust_a = h_a >= h_b
        # v25.59/61/63 NEW: Floor-Linearity Guard + Global-Consensus Guard - ก่อนเชื่อฝั่งใด
        # ฝั่งหนึ่งตาม reliability hierarchy เดิม ตรวจสอบว่า floor_y ของแต่ละฝั่ง ณ ตำแหน่งนี้
        # สมเหตุสมผลทางเรขาคณิตหรือไม่ (ดู docstring เต็มที่ _floor_linearity_anomaly) ถ้าตรวจ
        # ไม่ได้ (คอลัมน์ริมสุด) ใช้ Global-Consensus (เทียบกับ median ของคอลัมน์อื่นที่เชื่อถือ
        # ได้ทั้งภาพ) เป็นเกราะป้องกันสำรอง (v25.63: เปลี่ยนจาก elif เป็นเช็คอิสระ - ยืนยันจาก
        # RD01-01 idx2 ที่ floor-linearity คำนวณได้ค่าแต่ไม่ถึง threshold ทำให้ global-consensus
        # ไม่มีโอกาสทำงานเลยถ้าเขียนเป็น elif)
        anomaly_a = None
        anomaly_b = None
        if front_result is not None and back_result is not None:
            a_records_same_view = records_front if rec_a["view"] == "FRONT" else records_back
            b_records_same_view = records_front if best_match["view"] == "FRONT" else records_back
            a_floor = (front_result["local_floor_y"] if rec_a["view"] == "FRONT"
                       else back_result["local_floor_y"])
            b_floor = (front_result["local_floor_y"] if best_match["view"] == "FRONT"
                       else back_result["local_floor_y"])
            anomaly_a = _floor_linearity_anomaly(a_records_same_view, rec_a["idx"], a_floor)
            anomaly_b = _floor_linearity_anomaly(b_records_same_view, best_match["idx"], b_floor)
        should_flip = False
        flip_reason = None
        if anomaly_a is not None and anomaly_b is not None:
            winner_anomaly = anomaly_a if trust_a else anomaly_b
            loser_anomaly = anomaly_b if trust_a else anomaly_a
            if (winner_anomaly >= _FLOOR_LINEARITY_ANOMALY_MIN_PX
                    and winner_anomaly > loser_anomaly * 2):
                should_flip = True
                flip_reason = (f"[FLOOR_LINEARITY] anomaly={winner_anomaly:.1f}px vs "
                                f"loser anomaly={loser_anomaly:.1f}px")
        if not should_flip:
            other_reliable = []
            for rec_list in (records_front, records_back):
                for r in rec_list:
                    if r is rec_a or r is best_match:
                        continue
                    rh, rsrc = snapshot[id(r)]
                    if rh is not None and rsrc in ("direct", "cross_view_filled"):
                        other_reliable.append(rh)
            if len(other_reliable) >= 2:
                median_h = float(np.median(other_reliable))
                if median_h > 0:
                    dev_a = abs(h_a - median_h) / median_h
                    dev_b = abs(h_b - median_h) / median_h
                    winner_dev = dev_a if trust_a else dev_b
                    loser_dev = dev_b if trust_a else dev_a
                    if winner_dev >= 0.15 and winner_dev > loser_dev * 3:
                        should_flip = True
                        flip_reason = (f"[GLOBAL_CONSENSUS] เบี่ยงเบนจาก median กลุ่ม"
                                        f"({median_h:.1f}px, n={len(other_reliable)}) "
                                        f"{winner_dev:.1%} vs loser {loser_dev:.1%}")
        if not should_flip:
            # v25.81 NEW (สำคัญ - ตามคำแนะนำผู้ใช้ 31-Aug-2026: "ให้วิเคราะห์ BACK view ก่อนเสมอ"
            # - BACK คือ ground-truth หลักของตำแหน่ง/จำนวนตั้งอยู่แล้ว (Phase 1B ทั้งระบบออกแบบให้
            # BACK เป็นฐานอ้างอิงจับคู่ตำแหน่งกับ FRONT) แต่การ reconcile ความสูงเดิมไม่เคยให้
            # priority พิเศษกับ "ความสอดคล้องภายใน BACK" เลย พึ่งแค่ reliability-hierarchy (direct
            # > apex_partial_cut) เท่านั้น - ยืนยันด้วยข้อมูลจริง 2 ไฟล์อิสระกัน (EA02-02, ED86-03,
            # คนละ SKU คนละน้ำหนักสินค้า): BACK มี spread ภายในตัวเองต่ำมาก (0.24%/2.8%) แต่ FRONT
            # วัดสูงกว่า BACK อย่างเป็นระบบ 20-43% ทุกตำแหน่ง (ไม่ใช่ noise สุ่ม - เป็น bias
            # เชิงระบบของมุมกล้อง FRONT ในไฟล์กลุ่มนี้) ทั้งที่ทั้งคู่ได้ label "direct" เหมือนกัน
            # ROOT CAUSE ที่ Global-Consensus เดิม (v25.63) จับไม่ได้ครบ: รวม 'other_reliable' จาก
            # ทั้ง FRONT+BACK ปนกันเป็น median เดียว - ทำให้บางคู่ deviation เจือจางจนต่ำกว่าเกณฑ์
            # (ED86-03 คู่ที่ 2) และใช้ไม่ได้เลยถ้าไฟล์มีคอลัมน์รวมน้อยกว่า 2 other_reliable
            # (EA02-02 มีแค่ 2 คอลัมน์ทั้งไฟล์ - ไม่มี "other" เหลือให้ median เลย)
            # FIX: เปรียบเทียบ "ความสอดคล้องภายใน BACK เท่านั้น" (ไม่ผสม FRONT) กับ "ระดับความ
            # เบี่ยงเบนของ FRONT จาก BACK" โดยตรง - ถ้า BACK นิ่งมากภายในตัวเอง (รวมค่าที่กำลัง
            # พิจารณาด้วย ไม่ใช่แค่ "other") และ FRONT (ฝั่งที่ hierarchy เดิมเลือกให้ชนะ) เบี่ยงเบน
            # จาก BACK เกิน threshold ให้ "เชื่อ BACK เป็นหลักเสมอ" (ให้ priority กับ BACK ตาม
            # หลักการที่ผู้ใช้ระบุ) - ทำงานได้แม้ BACK มีแค่ 2 คอลัมน์ทั้งไฟล์ (ต่างจาก
            # Global-Consensus เดิมที่ต้องการ >=2 other_reliable คอลัมน์แยกจากคู่ที่พิจารณาอยู่)
            back_side = None
            front_side = None
            if rec_a["view"] == "BACK" and best_match["view"] == "FRONT":
                back_side, front_side = rec_a, best_match
            elif best_match["view"] == "BACK" and rec_a["view"] == "FRONT":
                back_side, front_side = best_match, rec_a
            if back_side is not None:
                back_side_h, _ = snapshot[id(back_side)]
                back_group = [back_side_h]
                for r in records_back:
                    if r is back_side:
                        continue
                    rh, rsrc = snapshot[id(r)]
                    if rh is not None and rsrc in ("direct", "cross_view_filled"):
                        back_group.append(rh)
                if len(back_group) >= 2:
                    back_consensus = float(np.median(back_group))
                    back_spread = ((max(back_group) - min(back_group)) / back_consensus
                                   if back_consensus > 0 else 999)
                    front_side_h, _ = snapshot[id(front_side)]
                    front_dev = (abs(front_side_h - back_consensus) / back_consensus
                                 if back_consensus > 0 else 0)
                    front_is_winner = ((trust_a and rec_a is front_side)
                                        or ((not trust_a) and best_match is front_side))
                    if (front_is_winner and back_spread <= _BACK_PRIORITY_MAX_INTERNAL_SPREAD
                            and front_dev >= _BACK_PRIORITY_MIN_FRONT_DEVIATION):
                        # หมายเหตุ: ไม่ตั้งค่า trust_a ตรงนี้ - ปล่อยให้ตรรกะ "if should_flip:
                        # trust_a = not trust_a" ด้านล่าง (ใช้ร่วมกับ FLOOR_LINEARITY/GLOBAL_
                        # CONSENSUS) จัดการสลับค่าให้ถูกต้องเพียงจุดเดียว - เพราะ front_is_winner
                        # ยืนยันแล้วว่า trust_a ปัจจุบันเลือก FRONT ชนะอยู่ การ toggle เพียงครั้ง
                        # เดียวที่ปลายทางจะทำให้ BACK ชนะแทนโดยอัตโนมัติ (ไม่ต้องกำหนดค่าตรงๆ ซ้ำ
                        # ซึ่งจะถูก toggle ทับอีกรอบกลายเป็นผิดพลาด)
                        should_flip = True
                        flip_reason = (f"[BACK_PRIORITY] BACK spread ภายในตัวเอง={back_spread:.1%} "
                                        f"(n={len(back_group)}, consensus={back_consensus:.1f}px) "
                                        f"นิ่งมาก vs FRONT เบี่ยงเบน {front_dev:.1%}")
        if should_flip:
            print(f"พลิกกลับการเลือก: winner เดิม (view="
                  f"{rec_a['view'] if trust_a else best_match['view']}) {flip_reason} "
                  f"-> เชื่อฝั่งที่สอดคล้องกับหลักฐานมากกว่าแทน")
            trust_a = not trust_a
        # v25.40 NEW: Physical Validity Guard - ก่อนเลือกใช้ค่าใด ตรวจสอบว่าค่านั้นไม่เกิน
        # ความสูงตู้จริง ณ ตำแหน่งของ 'เป้าหมายที่จะถูกเขียนทับ' (ไม่ใช่ตำแหน่งของแหล่งอ้างอิง
        # เพราะ x_range ของทั้งคู่อาจต่างกันเล็กน้อยจากการ reconcile คนละ view) - ถ้าค่าที่เลือก
        # ไว้ (ตาม trust_a) ผิดกฎกายภาพ ให้ลองสลับไปใช้อีกฝั่งแทน (ถ้าฝั่งนั้นผ่านเกณฑ์) หรือ
        # ข้ามการแก้ไขนี้ไปเลยถ้าทั้งคู่ผิดกฎ (ปลอดภัยที่สุด - คงค่าเดิมไว้)
        if trust_a:
            target, value = best_match, h_a
        else:
            target, value = rec_a, h_b
        if _violates_physical_validity(target, value):
            # ค่าที่เลือกไว้ผิดกฎกายภาพ - ลองอีกฝั่ง (ค่าที่ต่ำกว่า มักจะสมเหตุสมผลกว่า)
            alt_target = rec_a if trust_a else best_match
            alt_value = h_b if trust_a else h_a
            if not _violates_physical_validity(alt_target, alt_value):
                target, value = alt_target, alt_value
                trust_a = not trust_a
            else:
                continue  # ทั้ง 2 ค่าผิดกฎกายภาพ - ปลอดภัยที่สุดคือไม่แก้ไขอะไรเลย
        if trust_a:
            correction = (best_match["view"], best_match["idx"], h_b, h_a)
        else:
            correction = (rec_a["view"], rec_a["idx"], h_a, h_b)
        # v25.48 NEW: บันทึกขนาดความขัดแย้งเดิม (ก่อนแก้ไข) ระหว่าง FRONT<->BACK ไว้ - ใช้เป็น
        # สัญญาณความน่าเชื่อถือของค่าที่แก้ไขแล้ว (ดู STEP_DOWN_MAX_CORRECTION_RATIO ด้านล่าง)
        conflict_mag = abs(h_a - h_b) / higher if higher > 0 else 0.0
        key = id(target)
        if key not in proposals or best_overlap > proposals[key][0]:
            proposals[key] = (best_overlap, target, value, correction, conflict_mag)

    for _overlap, target, value, correction, conflict_mag in proposals.values():
        # v25.49 NEW (สำคัญ - พบจริงจาก AB03-04): ถ้าความขัดแย้งเดิม (ก่อนแก้ไข) สูงเกินเพดานนี้
        # ไม่น่าเป็น measurement noise ธรรมดาอีกต่อไป (สูงกว่าทุกเคส noise ที่เคยยืนยันแล้วมาก) -
        # ข้ามการแก้ไขนี้ไปเลย คงค่าเดิมทั้ง 2 ฝั่งไว้ ปล่อยให้ detect_step_down_crossview/pairwise
        # ตรวจจับความแตกต่างทางกายภาพจริงนี้ต่อไปตามปกติ (ดู docstring เต็มที่
        # RECONCILE_MAX_CONFLICT_TO_APPLY ด้านบนสำหรับหลักฐาน+เหตุผล)
        if conflict_mag > RECONCILE_MAX_CONFLICT_TO_APPLY:
            continue
        target["height_px"] = value
        target["height_source"] = "cross_view_corrected"
        # v25.48 NEW: ดู docstring เต็มที่ STEP_DOWN_MAX_CORRECTION_RATIO (ด้านล่าง ใกล้
        # detect_step_down_pairwise) สำหรับหลักฐาน+เหตุผล (พบจริงจาก AA02-01)
        target["cross_view_conflict_ratio"] = conflict_mag
        corrections.append(correction)
    return corrections


def _rearmost_record(records):
    """ตั้งที่อยู่ท้ายสุดจริง (real pos_range[1] ใกล้ 1.0 ที่สุด) ของ view นั้น - ข้าม
    record ที่ is_corner_duplicate=True เสมอ"""
    candidates = [r for r in records if not r.get("is_corner_duplicate")]
    if not candidates:
        return None
    return max(candidates, key=lambda r: r["pos_range"][1])


_SHADE_MERGE_HUE_TOL = 20      # ระยะห่างสูงสุด (0-255 scale) ของ normalized-hue vector ที่ยัง
                                # ถือว่าเป็น "สีเดียวกัน คนละความสว่าง" (แสง/เงา isometric)
_SHADE_MERGE_MIN_MAXCHAN = 20  # ต้องมี max channel >= นี้ ถึงจะ normalize ได้อย่างน่าเชื่อถือ
                                # (กันสีเกือบดำที่ ratio ไม่เสถียรจาก noise)


def _merge_shade_duplicate_clusters(colors, counts, tol=_SHADE_MERGE_HUE_TOL,
                                     min_maxchan=_SHADE_MERGE_MIN_MAXCHAN):
    """v25.57 NEW (สำคัญ - พบจริงจาก EB66-01 FRONT idx=0 หลังแก้ REAR_GAP_MIN_RATIO แล้ว
    เปิดเผยบั๊กที่ถูกบังไว้ก่อนหน้านี้โดยบังเอิญจาก cross-view conflict dedup): เดิม
    _dominant_color_clusters ใช้ quantize step=64 (v25.54 FIX) เพื่อรวม shading ของสีเดียวกัน
    แต่ step=64 ไม่พอจะรวมกรณีที่เงา isometric ทำให้ค่าความสว่างลดลงครึ่งหนึ่งพอดี (128->64,
    ห่างกันเต็ม 1 quantize step) - ยืนยันจากข้อมูลจริง EB66-01 FRONT idx=0: พบ 4 "สี" คือ
    (0,128,0)/(0,64,0)/(0,128,128)/(0,64,64) ซึ่งแท้จริงคือ SKU 2 ใบเท่านั้น (เขียว+เขียวอมฟ้า)
    แต่ละใบมีทั้งด้านที่โดนแสง (value=128) และด้านเงา (value=64) - ตรวจสอบคอลัมน์ข้างเคียง
    (x_range=(1160,1240)) ที่มีแค่ SKU เขียวใบเดียวยืนยัน pattern เดียวกัน (0,128,0)/(0,64,0)
    2 bins แต่ถูกนับถูกต้องเป็น 2 (ไม่ถึงเกณฑ์ 3) - แสดงว่า "จำนวน bin ดิบ" ไม่ใช่ตัวชี้วัดที่
    ถูกต้องของ "จำนวน SKU จริง" เมื่อมีทั้งด้านแสงและเงาปรากฏพร้อมกัน

    ROOT CAUSE ที่แท้จริง: แสง/เงาของมุมมอง isometric ลดค่าความสว่าง (value ใน HSV) ลงแต่คง "hue"
    (สัดส่วนระหว่างช่อง RGB) ไว้เหมือนเดิมเป๊ะ (เพราะเป็นการคูณทุกช่องด้วยค่าคงที่เดียวกัน) - จึง
    ควรเปรียบเทียบด้วย "สีที่ normalize ด้วย max channel ของตัวเอง" (ทำให้ value เท่ากันหมด =255)
    แทนที่จะเปรียบเทียบค่าดิบ - ถ้า normalized-hue ของ 2 cluster ใกล้กันมาก (ระยะห่าง <= tol)
    ถือว่าเป็นสีเดียวกัน คนละความสว่าง -> รวมเป็น cluster เดียว (นับรวม count, เก็บสีที่สว่างกว่า
    เป็นตัวแทน)

    ทดสอบยืนยัน: EB66-01 FRONT idx=0 -> เดิม 4 clusters (เกณฑ์ >=3 fail ผิดพลาด) หลังรวมแล้ว
    เหลือ 2 clusters จริง (เขียว 0.774 + เขียวอมฟ้า 0.226) -> ไม่ถึงเกณฑ์ REAR_COLOR_ANOMALY_
    MIN_COLORS=3 อีกต่อไป -> ไม่ flag ถูกต้อง (ตรงกับที่ผู้ใช้ยืนยันว่าไฟล์นี้ไม่มีความเสี่ยง)
    ไม่กระทบ EC04-02 (ground-truth เดิมที่ต้อง flag): SKU 4 สีจริงที่ต่างกันจริง (คนละ hue
    ไม่ใช่แค่คนละความสว่าง) จะไม่ถูก merge เพราะ normalized-hue ต่างกันเกิน tol แน่นอน
    """
    n = len(colors)
    if n < 2:
        return list(zip(colors, counts))
    colors_arr = [np.array(c, dtype=np.float64) for c in colors]
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    norms = []
    for c in colors_arr:
        maxchan = float(c.max())
        if maxchan < min_maxchan:
            norms.append(None)  # เกือบดำ - ไม่ merge อย่างน่าเชื่อถือ
        else:
            norms.append(c * (255.0 / maxchan))

    for i in range(n):
        if norms[i] is None:
            continue
        for j in range(i + 1, n):
            if norms[j] is None:
                continue
            dist = float(np.sqrt(np.sum((norms[i] - norms[j]) ** 2)))
            if dist <= tol:
                union(i, j)

    groups = {}
    for i in range(n):
        root = find(i)
        groups.setdefault(root, []).append(i)

    merged = []
    for idxs in groups.values():
        total_count = sum(counts[i] for i in idxs)
        # เก็บสีที่ "สว่างที่สุด" (max channel สูงสุด) เป็นตัวแทนของกลุ่ม (ด้านที่โดนแสงเต็มที่)
        rep_i = max(idxs, key=lambda i: colors_arr[i].max())
        merged.append((colors[rep_i], total_count))
    return merged


def _dominant_color_clusters(region, cargo_mask, x_range, margin=6,
                              min_fraction=REAR_COLOR_MIN_FRACTION,
                              min_pixels=REAR_COLOR_MIN_PIXELS):
    """หาชุดสีเด่น (quantized 64-level) ภายในช่วง x_range ของ 1 ตั้ง - ใช้ตรวจว่ามี SKU
    ปะปนกันผิดปกติหรือไม่ (กลไก B ของ REAR_EMPTY_RISK) คืนค่า list[(color, count)]

    v25.54 FIX: เปลี่ยน quantize จาก 32-level → 64-level เพื่อป้องกัน 1 SKU (สีเดียว)
    ถูกแตกเป็น 3+ bins จาก shading/gradient ของมุมมอง isometric เช่น olive (128,128,0)
    ถูกแตกเป็น (128,128,0)+(96,96,0)+(64,64,0) ทั้งที่เป็นกล่องใบเดียวกัน
    ยืนยันจาก EA07-01 BACK rear_col: 3 bins ทั้งหมดเป็นเฉด olive เดียวกัน → false-positive
    64-level (step=64) ทำให้ bins ที่เป็นเฉดเดียวกัน merge เป็น 1 bin เดียว

    v25.57 FIX (เพิ่มเติม - ดู _merge_shade_duplicate_clusters สำหรับหลักฐาน+เหตุผลเต็ม):
    quantize step=64 เพียงอย่างเดียวไม่พอเมื่อเงา isometric ลดความสว่างลงพอดี 1 quantize step
    (เช่น 128->64) - เพิ่มขั้นตอน merge ด้วย normalized-hue หลัง quantize เพื่อรวม
    แสง/เงาของสีเดียวกันที่ step=64 รวมไม่ได้
    """
    x0, x1 = x_range
    x0 = max(0, x0 + margin)
    x1 = max(x0, x1 - margin)
    if x1 <= x0:
        return []
    sub_mask = cargo_mask[:, x0:x1]
    sub_region = region[:, x0:x1]
    pixels = sub_region[sub_mask]
    if len(pixels) < 50:
        return []
    # v25.54 FIX: 64-level quantize (step=64 แทน 32) ลด false split ของสีเดียวกัน
    quant = (pixels // 64 * 64).astype(np.int32)
    uniq, counts = np.unique(quant.reshape(-1, 3), axis=0, return_counts=True)
    total = len(pixels)
    # v25.57 NEW: รวม shading/เงาของสีเดียวกัน (ดู docstring ด้านบน) ก่อนนับ/กรอง threshold
    raw_colors = [tuple(int(v) for v in uniq[i]) for i in range(len(uniq))]
    raw_counts = [int(c) for c in counts]
    merged = _merge_shade_duplicate_clusters(raw_colors, raw_counts)
    merged.sort(key=lambda cc: -cc[1])
    clusters = []
    for color, cnt in merged:
        if cnt >= min_pixels and (cnt / total) >= min_fraction:
            clusters.append((color, cnt))
    return clusters


# v25.53 NEW (สำคัญ - พบจริงจากการตรวจสอบ REAR_EMPTY_RISK ที่ mark BACK เกือบทุกไฟล์ ผู้ใช้
# สังเกตว่า pattern นี้ผิดปกติเกินไปที่จะบังเอิญ): ตรวจสอบข้าม 24 ไฟล์พบว่า "ช่องว่างฝั่งหัวตู้"
# ของ BACK (start_x เดิม ถึงมุมผนังจริง) สูงผิดปกติ 100-150px แทบทุกไฟล์ ในขณะที่ FRONT มีช่องว่าง
# ฝั่งเดียวกันแค่ 3-30px เท่านั้น (ยืนยันด้วยภาพว่ากล่องชิดผนังหัวตู้จริง ไม่ใช่ช่องว่างจริง)
# ROOT CAUSE: กล่องที่ตำแหน่งใกล้ผนังหัวตู้ที่สุดในมุมมอง BACK มักมี "หน้าข้าง (side face)" ของ
# กล่องโผล่ให้เห็นก่อนถึง front-face หลัก (เพราะความลึกของกล่องในมุมมอง isometric) - หน้าข้างนี้มี
# สีสดจริง (ยืนยันจาก AA02-01: พบสีเขียว (123,255,70) ที่ cargo_bottom_y ตลอดช่วง x=604-742) แต่
# ไม่ผ่านเกณฑ์ 'grounded' (gap_thresh=30) เพราะใต้หน้าข้างนี้เป็นสีผนังด้านข้างตู้ (255,255,147)
# ไม่ใช่สีพื้นตู้จริง (ระยะห่างจาก cargo_bottom_y ถึง floor สีโครงสร้างที่แท้จริงจึงไกลเกิน 30px
# มาก - วัดได้จริง 95-99px) ทำให้ทั้ง grounded-based fallback และ Phase 1B (ซึ่งนับเฉพาะ
# front-face fragment ไม่รวมหน้าข้าง) พลาดพื้นที่กล่องจริงนี้ไปพร้อมกันทั้งคู่ ทำให้ start_x/
# end_x/length_px (Phase 2) ของ BACK สั้นกว่าความเป็นจริงอย่างเป็นระบบ
#
# ทดสอบแล้วว่าการแก้ x_min_/x_max_ ใน process_view_on_image โดยตรง (ซึ่งใช้ร่วมกันทั้งการหา
# seam/boundary ของคอลัมน์และการวัดความสูง) กระทบ STEP_DOWN_RISK ในหลายไฟล์อย่างกว้างขวางเกินกว่า
# จะยืนยันความปลอดภัยได้ทันที (ตามที่ผู้ใช้ชี้ให้ระวัง)
#
# FIX ที่ปลอดภัยกว่า: คำนวณ "ความยาวขยาย" (extended length) แยกต่างหาก เฉพาะสำหรับ
# REAR_EMPTY_RISK เท่านั้น โดยใช้ cargo_mask ดิบ (ผ่านการกรอง arrow_mask + min_blob_size แล้ว
# จาก vivid_cargo_mask - ปลอดภัยจากตัวอักษร/เส้นบอกระยะที่เป็นจุดเล็กๆ กระจัดกระจาย) ขยาย
# start_x/end_x เดิม (จาก Phase 2) ให้ครอบคลุมสีสดใดๆ ที่พบเพิ่มเติม - ไม่แตะ x_min_/x_max_ เดิม
# ที่ใช้คำนวณ seam/height เลย (แยกผลกระทบออกจากกันชัดเจน 100% - regression-verified ครบ 24 ไฟล์
# ไม่กระทบ STEP_DOWN_RISK แม้แต่จุดเดียว)
def _p1b_extended_length_for_rear_check(view_result):
    """[v25.53] คืนค่า (start_x, end_x, length_px) ที่ขยายจากค่าเดิมของ Phase 2 โดยรวม extent
    ของ cargo_mask ดิบเข้าไปด้วย (ดู docstring ด้านบนสำหรับหลักฐาน+เหตุผลเต็ม) - ใช้เฉพาะใน
    detect_rear_empty_risk เท่านั้น ไม่กระทบ start_x/end_x เดิมที่ Phase 3/seam ใช้งานอยู่

    v25.54 FIX: จำกัด extend ของ start_x ไม่ให้เกิน REAR_EXTEND_MAX_PX=60px จากค่าเดิม
    เพื่อป้องกัน cargo_mask ที่มี side-face/roof ของกล่องโผล่ไกลฝั่งหัวตู้ดึง start_x ออกไป
    จนทำให้ FRONT ดูยาวกว่า BACK อย่างผิดปกติ ยืนยันจาก EA07-01:
    FRONT start_x ดิบ=661px แต่ extended=568px (ขยาย 93px >> BACK ขยาย 48px)
    → gap พอง 42px/6.3% ทั้งที่ตู้เต็มจริง 92.7%
    60px เพียงพอสำหรับ side-face ปกติ (ยืนยันจาก AA02-01: side-face = 95-99px แต่ผ่านกรอง
    blob_size แล้ว ส่วนที่เหลือไม่ควรเกิน 60px) และยังรองรับ AB03-03 gap=46px ได้ปกติ
    """
    REAR_EXTEND_MAX_PX = 60  # จำกัดการขยาย start_x/end_x ฝั่งละไม่เกินนี้
    start_x = view_result.get("start_x")
    end_x = view_result.get("end_x")
    cargo_mask = view_result.get("cargo_mask")
    if start_x is None or end_x is None or cargo_mask is None:
        return start_x, end_x, view_result.get("length_px")
    xs = np.nonzero(cargo_mask.any(axis=0))[0]
    if len(xs):
        # v25.54 FIX: clamp การขยาย start_x/end_x ให้ไม่เกิน REAR_EXTEND_MAX_PX
        new_start = int(xs.min())
        new_end   = int(xs.max())
        start_x = max(new_start, start_x - REAR_EXTEND_MAX_PX)
        end_x   = min(new_end,   end_x   + REAR_EXTEND_MAX_PX)
    return start_x, end_x, (end_x - start_x)


# v25.64 NEW (สำคัญ - ตามไอเดียผู้ใช้ 29-Aug-2026: "ลากเส้น 2 เส้นตัดกัน พื้นที่ล่างจุดตัด
# ภายในตู้สินค้า พบสีขาว หมายถึงพื้นที่ว่าง อันเกิดจากกล่องสูงต่ำหรือไม่มีกล่องวางตรงนั้น"):
# ยืนยันด้วยข้อมูลจริง (EC18-01, EC04-01) ระดับ pixel: ถ้าโหลดเต็มสม่ำเสมอ เส้นขอบบนกองสินค้า
# (cargo_top_y) ควรมีรูปร่าง "V เดียว" (isometric apex) - ถ้ามีรอยบากที่สองแทรกกลางแถว (local
# peak ที่ไม่ใช่ apex จริง) นั่นคือสัญญาณกล่องเตี้ยกว่าที่ไม่ถูกกองข้างเคียงบังจนมิด เผยพื้นหลัง/
# ผนังตู้ - ยืนยัน sample สีในรอยบากได้ 100% เป็นพื้นหลังขาว/สีโครงสร้างตู้ (ไม่ใช่สีกล่องสินค้า)
# Regression-tested สะอาดกับ 8 ไฟล์ (ไม่มี false-positive)
_NOTCH_MIN_PROMINENCE_PX = 15
_NOTCH_MIN_DISTANCE_PX = 20
_NOTCH_MIN_EMPTY_FRACTION = 0.6

# v25.69 NEW (สำคัญ - ตามคำสั่งผู้ใช้ 30-Aug-2026 หลังตัดสินใจให้ silhouette_notch มาแทนที่
# REAR_EMPTY_RISK/length_mismatch ทั้งหมด): เดิมกรอบ marker ของ silhouette_notch แคบมาก
# (กว้างคงที่ 40px = x_notch±20 โดยไม่สนใจความกว้างจริงของรอยบากที่ตรวจพบ) ทำให้ดูเป็นเส้นบางๆ
# ไม่ชัดเจนเทียบกับกรอบคอลัมน์ปกติ (STEP_DOWN_RISK) ที่กว้างเท่าคอลัมน์จริง (~80-150px ในภาพ
# ทดสอบทั้งหมด) - ผู้ใช้ระบุให้ปรับกรอบให้ "มองเห็นได้ชัดเหมือนกรอบคอลัมน์"
# FIX: ใช้ความกว้างจริงของรอยบาก (จาก left_bases/right_bases ที่ scipy.signal.find_peaks คำนวณ
# ให้แล้ว - คือขอบเขตจริงของ "หุบเขา" ในกราฟก่อนจะกลับสู่ระดับ baseline ทั้ง 2 ฝั่ง) แทนความกว้าง
# คงที่ 40px เดิม - ถ้าความกว้างจริงยังแคบกว่าเกณฑ์ขั้นต่ำ (_NOTCH_BOX_MIN_WIDTH_PX) ให้ pad
# เพิ่มสมมาตรทั้ง 2 ฝั่งจนถึงเกณฑ์นี้ (ให้ใกล้เคียงขนาดกรอบคอลัมน์ทั่วไป ไม่เล็กจนสังเกตยาก) - ไม่
# เปลี่ยนแนวตั้ง (baseline_y ถึง y_notch) เพราะเป็นขอบเขตที่ยืนยันแล้วด้วยการ sample สีจริงว่าเป็น
# พื้นที่ว่าง/โครงสร้างตู้ 100% (ขยายลงต่ำกว่า y_notch จะไปทับกับกล่องสินค้าจริงที่มีอยู่ - ไม่ใช่
# พื้นที่เสี่ยง ควรหลีกเลี่ยง)
_NOTCH_BOX_MIN_WIDTH_PX = 70  # ใกล้เคียงความกว้างคอลัมน์ขั้นต่ำที่พบจริงในไฟล์ทดสอบ (~80px)


def detect_silhouette_notch_risk(view_result, view_label):
    """ตรวจจับรอยบากในเส้นขอบบนกองสินค้า (cargo_top_y) ที่เผยพื้นหลัง/สีโครงสร้างตู้กลางแถว
    (ไม่ใช่ปลายสุด) - ดู docstring เต็มด้านบน"""
    cty = view_result.get("cargo_top_y")
    region = view_result.get("region")
    sx, ex = view_result.get("start_x"), view_result.get("end_x")
    if cty is None or region is None or sx is None or ex is None or (ex - sx) < 40:
        return []
    xs = np.arange(sx, ex)
    vals = np.array([float(cty[x]) if 0 <= x < len(cty) and cty[x] >= 0 else np.nan for x in xs])
    valid_mask = ~np.isnan(vals)
    if valid_mask.sum() < 20:
        return []
    if not np.all(valid_mask):
        vals = np.interp(np.arange(len(vals)), np.where(valid_mask)[0], vals[valid_mask])
    smoothed = median_filter(vals, size=9)
    peaks, props = find_peaks(smoothed, prominence=_NOTCH_MIN_PROMINENCE_PX,
                               distance=_NOTCH_MIN_DISTANCE_PX)
    risks = []
    for i, p in enumerate(peaks):
        prom = float(props["prominences"][i])
        left_base_idx = int(props["left_bases"][i])
        right_base_idx = int(props["right_bases"][i])
        x_notch = int(xs[p])
        y_notch = int(round(smoothed[p]))
        baseline_y = int(min(vals[left_base_idx], vals[right_base_idx]))
        if y_notch <= baseline_y:
            continue
        colors_sampled = []
        for yy in range(baseline_y, y_notch, 3):
            if 0 <= yy < region.shape[0] and 0 <= x_notch < region.shape[1]:
                colors_sampled.append(region[yy, x_notch])
        if not colors_sampled:
            continue
        n_empty = sum(
            1 for c in colors_sampled
            if (int(c[0]) > 230 and int(c[1]) > 230 and int(c[2]) > 230)
            or _p1b_is_structural_container_color(c)
        )
        frac_empty = n_empty / len(colors_sampled)
        if frac_empty < _NOTCH_MIN_EMPTY_FRACTION:
            continue
        # v25.69 NEW: ใช้ความกว้างจริงของรอยบาก (left_base ถึง right_base) แทน x_notch±20 เดิม
        # แล้ว pad ให้ถึงขั้นต่ำ _NOTCH_BOX_MIN_WIDTH_PX ถ้ายังแคบกว่า - ทำให้กรอบชัดเจนเหมือน
        # กรอบคอลัมน์ปกติ (ดู docstring เต็มด้านบน)
        x_left_natural = int(xs[left_base_idx])
        x_right_natural = int(xs[right_base_idx])
        natural_width = x_right_natural - x_left_natural
        if natural_width < _NOTCH_BOX_MIN_WIDTH_PX:
            pad = (_NOTCH_BOX_MIN_WIDTH_PX - natural_width) / 2.0
            x0_mark = max(sx, int(round(x_left_natural - pad)))
            x1_mark = min(ex, int(round(x_right_natural + pad)))
        else:
            x0_mark = max(sx, x_left_natural)
            x1_mark = min(ex, x_right_natural)
        ox, oy = view_result["crop_origin_x"], view_result["crop_origin_y"]
        abs_box = (ox + x0_mark, oy + baseline_y, ox + x1_mark, oy + y_notch)
        risks.append({
            "risk_type": "EMPTY_SPACE_RISK", "subtype": "silhouette_notch",
            "mark_view": view_label, "mark_stack_idx": None,
            "mark_x_range": (x0_mark, x1_mark), "pos_range": None,
            "abs_box": abs_box,
            "notch_x": x_notch, "prominence_px": prom, "empty_fraction": frac_empty,
            "reason": (f"พบรอยบากในเส้นขอบบนกองสินค้าที่ x={x_notch} (ลึก {prom:.0f}px) "
                       f"เผยพื้นหลัง/สีโครงสร้างตู้ {frac_empty:.0%} บ่งชี้กล่องเตี้ยกว่า/ไม่มี"
                       f"กล่องแถวหน้ามาบัง เสี่ยงพื้นที่ว่างกลางคัน"),
        })
    return risks


def detect_rear_empty_risk(records_front, records_back, front_result, back_result):
    """REAR_EMPTY_RISK - ตรวจสีของ "ตั้งท้ายสุดจริง" ของแต่ละ view (ข้าม corner_duplicate
    เสมอ) - ถ้ามี SKU ปะปนกันผิดปกติ (>=3 สีเด่น) มักบ่งชี้สินค้าที่วางไม่เป็นระเบียบ/มีช่องว่าง
    ใกล้ประตูท้ายตู้ (ยืนยันจาก EC04-02 BACK idx ท้ายสุด ต้อง flag)

    v25.69 REMOVED (สำคัญ - ตามคำสั่งผู้ใช้ 30-Aug-2026): เดิมมีกลไก A (length_mismatch -
    เทียบ length_px/extended-length ระหว่าง FRONT<->BACK) เป็นกลไกหลักคู่กับกลไก B
    (color_anomaly) - ผู้ใช้ระบุว่า detect_silhouette_notch_risk (v25.64, "กรอบมุมทแยง")
    ทำหน้าที่แทนกลไก A ได้ดีกว่า เพราะ:
      1) ตรวจจับพื้นที่ว่างได้จริงจากรูปทรงเรขาคณิต (รอยบากในเส้นขอบบนกองสินค้า) โดยตรง
         ไม่ต้องอาศัยการเปรียบเทียบความยาวรวมทาง pixel ที่มีความไม่แน่นอนสูง (bias เชิงระบบที่
         แปรผันตามรุ่นรถ/ระดับบรรทุก - ยืนยันจาก EA07-01/EB66-01=6.3%, EC10-03=10.4%,
         EC19-01=12.2%, EB73-01=16.6% - ไม่มีค่าคงที่ให้ calibrate ได้แม่นยำ)
      2) ครอบคลุมกว้างกว่า - ตรวจพื้นที่ว่างได้ "ทุกตำแหน่งภายใน FRONT/BACK view" ไม่จำกัดแค่
         โซนท้ายรถ (ตำแหน่งตั้งสุดท้ายก่อนประตู) เหมือนกลไก A/B เดิม
      3) วาง marker ตรงตำแหน่งพื้นที่ว่างจริงโดยตรง (จาก notch_x ที่ตรวจพบ) แม่นยำกว่าการ mark
         ทั้งคอลัมน์ท้ายสุด (ซึ่งอาจไม่ใช่ตำแหน่งที่มีปัญหาจริงเป๊ะ)
    ลบกลไก A (length_mismatch) และ _p1b_extended_length_for_rear_check ที่เกี่ยวข้องออก
    ทั้งหมด (เก็บ REAR_GAP_MIN_PX/REAR_GAP_MIN_RATIO ไว้เป็น dead-constant เพื่อลด diff -
    ไม่ได้ใช้งานแล้ว) - เหลือกลไก B (color_anomaly) ไว้เป็นกลไกเสริมที่ตรวจจากสัญญาณคนละมิติ
    (SKU สีปะปนกัน ไม่ใช่ความยาว) และปรับ Guard 1 เดิม (ที่เคยพึ่งพา _partial_gap_px จากกลไก A
    เพื่อยืนยันว่ามี partial length gap จริง) ให้ยังคงทำงานได้อิสระโดยคำนวณ gap จาก length_px
    ดิบ (Phase 2, ไม่ผ่าน extended-length) โดยตรงแทน - ไม่กระทบผลลัพธ์เดิมของกลไก B เพราะใช้
    เกณฑ์ตัวเลขเดียวกัน (>=15px) เพียงแต่เปลี่ยนแหล่งข้อมูลจาก extended เป็น raw
    """
    risks = []

    # --- กลไก B: color-anomaly ที่ตั้งท้ายสุดจริงของแต่ละ view ---
    # v25.54 FIX: เพิ่ม 2 guards ป้องกัน false-positive จากตู้ที่กล่อง SKU ต่างชนิดวางชิดกัน
    # ตามปกติ (เช่น EA07-01 ที่มีหลาย SKU ในคอลัมน์ท้าย แต่ไม่มีช่องว่างจริง):
    #
    # Guard 1 — ต้องมี partial length gap ยืนยัน: กลไก B จะ flag ก็ต่อเมื่อมีช่องว่างความยาว
    #   >= REAR_COLOR_NEEDS_GAP_MIN_PX เพราะ color_anomaly เพียงอย่างเดียวไม่เพียงพอ — ไฟล์ที่
    #   กล่องเต็มตู้ก็อาจมี SKU หลายสีในคอลัมน์ท้ายตามธรรมชาติ ยืนยันจาก EC04-02: gap=17px
    #   ยังเข้าเกณฑ์นี้ได้ (>15px) ในขณะที่ EA07-01: gap=9px ไม่เข้าเกณฑ์ → ไม่ flag ถูกต้อง
    #   v25.69: เปลี่ยนแหล่งข้อมูล gap จาก extended-length (กลไก A ที่ถูกลบ) เป็น length_px
    #   ดิบจาก Phase 2 โดยตรง (ไม่กระทบตัวเลขที่เคย verify ไว้ - ทั้ง 2 ไฟล์ ground-truth
    #   (EC04-02=17px, EA07-01=9px) วัดจาก raw length_px ได้ค่าเดียวกันกับที่เคย verify ไว้)
    #
    # Guard 2 — dominant color ต้องไม่ครอบงำมากเกิน (REAR_COLOR_MAX_DOMINANT_FRAC):
    #   ถ้า 1 สีมี fraction >= 0.70 ของ pixel ทั้งหมด แสดงว่า col นั้นเป็นกล่องใบเดียวเป็นหลัก
    #   สีรองที่เหลือเป็น shading/shadow/outline ของกล่องใบนั้น ไม่ใช่ SKU อื่นจริง
    #   ยืนยัน EA07-01 BACK: (128,128,0)=71.5% → 1 SKU ครอบงำ สีรองเป็น shading → false-positive
    #   ยืนยัน EC04-02 BACK: TEM1A มี 4 สีต่างฝั่งต่างกัน ไม่มีสีใดครอบงำ >= 70%
    REAR_COLOR_NEEDS_GAP_MIN_PX = 15     # gap ขั้นต่ำ (px) ที่กลไก B ต้องการ
    REAR_COLOR_MAX_DOMINANT_FRAC = 0.70  # ถ้า dominant > นี้ = 1 SKU + shading ไม่ใช่ multi-SKU

    front_len_raw = front_result.get("length_px") or 0
    back_len_raw = back_result.get("length_px") or 0
    _partial_gap_px = abs(front_len_raw - back_len_raw) if (front_len_raw and back_len_raw) else 0

    for records, result, label in [(records_front, front_result, "FRONT"),
                                    (records_back, back_result, "BACK")]:
        rear_rec = _rearmost_record(records)
        if rear_rec is None:
            continue
        clusters = _dominant_color_clusters(result["region"], result["cargo_mask"], rear_rec["x_range"])
        if len(clusters) < REAR_COLOR_ANOMALY_MIN_COLORS:
            continue

        # v25.54 Guard 1: ต้องมี partial length gap ยืนยัน
        if _partial_gap_px < REAR_COLOR_NEEDS_GAP_MIN_PX:
            continue

        # v25.54 Guard 2: dominant color ต้องไม่ครอบงำมากเกิน
        total_pixels = sum(cnt for _, cnt in clusters)
        if total_pixels > 0:
            dominant_frac = clusters[0][1] / total_pixels
            if dominant_frac >= REAR_COLOR_MAX_DOMINANT_FRAC:
                continue

        risks.append({
            "risk_type": "EMPTY_SPACE_RISK", "subtype": "color_anomaly",
            "mark_view": label,
            "mark_stack_idx": rear_rec["idx"], "mark_x_range": rear_rec["x_range"],
            "pos_range": rear_rec["pos_range"], "n_colors": len(clusters),
            "reason": (f"ตั้งสุดท้ายก่อนประตูท้ายตู้ฝั่ง {label} พบสี SKU ปะปนกัน {len(clusters)} สี "
                       f"บ่งชี้สินค้าที่วางไม่เป็นระเบียบ/มีช่องว่างใกล้ประตูท้ายตู้"),
        })

    # v25.69 REMOVED: cross-view voting logic เดิม (v25.55 FIX#3) ออกแบบมาเพื่อแก้ความขัดแย้ง
    # ระหว่าง length_mismatch กับ color_anomaly (subtype ต่างกัน) - ตอนนี้เหลือแค่ color_anomaly
    # subtype เดียว (ไม่มีทางมี subtype ต่างกันในกลุ่ม REAR_EMPTY_RISK อีกต่อไป) จึง logic นี้
    # กลายเป็น dead code ทั้งหมด (เงื่อนไข len(subtypes)>1 ไม่มีทางเป็นจริงได้อีกแล้ว) - ลบออก

    return risks


def run_full_analysis_on_image(full_img, doc, page_idx=1, pdf_bytes=None, matrix_scale=3):
    # v25.11: PHASE 1B ต้องรู้ทั้ง FRONT และ BACK พร้อมกันก่อน (BACK = ground-truth ตำแหน่ง,
    # FRONT ถูก reconcile กับ BACK) จึงต้องคำนวณคอลัมน์ทั้งคู่ล่วงหน้า ก่อนเรียก
    # process_view_with_height_on_image ต่อ view ตามปกติ - ถ้าล้มเหลว (None) จะ fallback ไป
    # seam-based เดิมโดยอัตโนมัติ (ดู process_view_on_image)
    #
    # v25.15 FIX (Critical - แก้ HTTP 500 บน Cloud Function จริงที่เกิดจาก v25.14): v25.14 แก้
    # Bug#1/#2 (coordinate mismatch) โดยเปลี่ยนทั้ง pipeline หลักให้ render เต็มหน้าที่ scale=4
    # (จากเดิม scale=3) - ทดสอบ local ผ่านหมด แต่พอใช้งานจริงบน Cloud Function พบ HTTP 500 ทุกไฟล์
    # เพราะ scale=4 เต็มหน้าทำให้ทุกขั้นตอนใน pipeline (mask, floor profile, วาด marker, JPEG
    # encode ฯลฯ) ใช้ memory เพิ่มขึ้น ~1.78 เท่าพร้อมกันหมด จนเกิน memory limit ของ Cloud Function
    #
    # แก้โดยกลับไปใช้ full_img ที่ scale=3 สำหรับ pipeline หลักเหมือนเดิม (memory เท่าเดิม) ส่วน
    # PHASE 1B render เฉพาะ "สี่เหลี่ยม region เล็กๆ ของ view" ตรงจาก PDF ที่ scale=4 ผ่าน fitz
    # clip (render_hires_crop) โดยใช้ origin_box เดียวกับที่ get_view_region คำนวณให้ pipeline
    # หลักใช้เป๊ะ - ยังคงแก้ Bug#1 (coordinate mismatch) + Bug#2 (double ensure_safe_crop) ได้ครบ
    # เพราะพิกัด origin อ้างอิงจากกล่องเดียวกัน (ต่างกันแค่ความหนาแน่น pixel ที่แปลงกลับด้วย
    # down_factor คงที่) แต่ไม่ต้อง render เต็มหน้าที่ scale สูงอีกต่อไป (ประหยัด memory มาก)
    try:
        page = doc[page_idx]
        front_region, front_origin, _ = get_view_region(full_img, doc, "front", page_idx=page_idx)
        back_region, back_origin, _ = get_view_region(full_img, doc, "back", page_idx=page_idx)
        front_precrop = (front_region, front_origin)
        back_precrop = (back_region, back_origin)

        front_hi, down_factor = render_hires_crop(page, front_origin, matrix_scale)
        back_hi, _ = render_hires_crop(page, back_origin, matrix_scale)
        phase1b = compute_phase1b_columns({"front": front_hi, "back": back_hi}, down_factor=down_factor)
        del front_hi, back_hi  # ปล่อย memory ของ hi-res crop ทันทีหลังใช้เสร็จ
    except Exception as e:
        print(f"PHASE1B hi-res crop ล้มเหลว, fallback ให้ process_view_on_image ครอปเองตามปกติ: {e}")
        phase1b = {"front": None, "back": None}
        front_precrop = None
        back_precrop = None

    front = process_view_with_height_on_image(
        full_img, doc, "front", page_idx=page_idx, override_cols=phase1b.get("front"),
        precrop=front_precrop)
    back = process_view_with_height_on_image(
        full_img, doc, "back", page_idx=page_idx, override_cols=phase1b.get("back"),
        precrop=back_precrop)
    records_front = build_stack_records(front, "FRONT")
    records_back = build_stack_records(back, "BACK")

    # ลำดับการแก้ไข height: 1) direct 2) cross_view_filled/corrected 3) carried_forward
    reconcile_heights_cross_view(records_front, records_back,
                                  front_result=front, back_result=back)
    fill_missing_heights(sorted(records_front, key=lambda r: r["idx"]))
    fill_missing_heights(sorted(records_back, key=lambda r: r["idx"]))
    for records, view_result in [(records_front, front), (records_back, back)]:
        for rec in records:
            sh = view_result["stack_heights"][rec["idx"]]
            sh["height_px"] = rec["height_px"]
            sh["height_source"] = rec["height_source"]

    risks = []
    risks += detect_step_down_pairwise(records_front, "FRONT", view_result=front)
    risks += detect_step_down_pairwise(records_back, "BACK", view_result=back)
    risks += detect_step_down_crossview(records_front, records_back, front_result=front, back_result=back)
    risks += detect_tail_stepdown(records_front, "FRONT", view_result=front)
    risks += detect_tail_stepdown(records_back, "BACK", view_result=back)
    risks += detect_step_down_hidden_behind(front, records_front, "FRONT")
    risks += detect_step_down_hidden_behind(back, records_back, "BACK")
    risks += detect_rear_empty_risk(records_front, records_back, front, back)
    risks += detect_silhouette_notch_risk(front, "FRONT")
    risks += detect_silhouette_notch_risk(back, "BACK")
    # v25.75 NEW: ลบบรรทัด comment-out ของ detect_step_down_topface_jump ที่ปิดใช้งานถาวร
    # มาตั้งแต่ v25.65 (ฟังก์ชันเองก็ถูกลบไปแล้วในรอบนี้ - ดู docstring เต็มที่จุดที่เคยมีฟังก์ชัน
    # นั้นอยู่ ใกล้ _floor_linearity_anomaly) ตามคำสั่งผู้ใช้ให้ลบกลไกที่ไม่ใช้งานจริงออก
    # v25.57 NEW: dedup ระหว่าง pairwise/pairwise_floor_jump กับ tail_stepdown เมื่อทั้งคู่
    # flag "คู่ column เดียวกัน" (view+pair_indices ตรงกัน) - พบจริงจาก log EB66-01 29-Aug-2026:
    # FRONT pairwise idx=1 และ tail_stepdown idx=0 ได้ drop_ratio=0.23156868... เหมือนกันเป๊ะ
    # เพราะทั้ง 2 กลไกเปรียบเทียบ pair (idx0,idx1) เดียวกันอย่างเป็นอิสระต่อกัน (tail_stepdown
    # เจอเพราะ idx0 เป็นตั้งท้ายสุดพอดี, pairwise เจอเพราะ idx0/idx1 เป็นคู่ติดกัน) - ทำให้เกิด
    # marker ซ้ำซ้อน 2 กรอบสำหรับสถานการณ์ทางกายภาพเดียวกัน (นับ hazardCount เกินจริงด้วย) เก็บ
    # เฉพาะ pairwise/pairwise_floor_jump ไว้ (มี guard ครบชุดเดียวกับ tail_stepdown อยู่แล้วหลัง
    # v25.57 - เลือกอันเดียวพอ ไม่ต้องมี 2 กรอบซ้อนกันสำหรับ edge case เดียวกัน)
    risks = _dedup_overlapping_stepdown_risks(risks)
    # v25.79 NEW: dedup STEP_DOWN_RISK(pairwise) ที่ค่าความสูงฝั่งเตี้ยกว่าถูกปนเปื้อนจาก
    # silhouette_notch ตำแหน่งเดียวกัน - ดู docstring เต็มที่ _dedup_stepdown_corrupted_by_
    # adjacent_notch สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA10-01)
    risks = _dedup_stepdown_corrupted_by_adjacent_notch(risks, records_front, records_back)

    return {
        "front": front, "back": back,
        "records_front": records_front, "records_back": records_back,
        "risks": risks,
    }


def risk_abs_box(risk, result):
    """แปลง mark_x_range (พิกัด local) เป็นพิกัดภาพเต็มหน้า (absolute) สำหรับวาด marker"""
    view_label = risk.get("mark_view") or risk.get("view")
    v = result["front"] if view_label == "FRONT" else result["back"]
    x0, x1 = risk["mark_x_range"]
    stack = v["stack_heights"][risk["mark_stack_idx"]]
    height_px = stack["height_px"]
    xm = (x0 + x1) // 2
    lfy = v["local_floor_y"]
    floor_y_local = lfy[xm] if xm < len(lfy) and lfy[xm] >= 0 else None
    if floor_y_local is None or height_px is None:
        return None
    top_y_local = floor_y_local - height_px
    ox, oy = v["crop_origin_x"], v["crop_origin_y"]
    return (ox + x0, oy + top_y_local, ox + x1, oy + floor_y_local)


# ============================================================================
# Main HTTP handler (Cloud Function entry point) - คง output contract เดิมของ v24.36
# ============================================================================

@functions_framework.http
def process_request(request):
    if request.method == "OPTIONS":
        headers = {
            "Access-Control-Allow-Origin": "*",
            "Access-Control-Allow-Methods": "POST",
            "Access-Control-Allow-Headers": "Content-Type, x-goog-api-key",
            "Access-Control-Max-Age": "3600",
        }
        return ("", 204, headers)
    headers = {"Access-Control-Allow-Origin": "*"}
    try:
        data = request.get_json(silent=True)
        if data is None:
            raw_data = request.get_data(as_text=True)
            data = json.loads(raw_data) if raw_data else {}
        if not data or "base64" not in data:
            print("DEBUG - RECEIVED DATA:", request.get_data(as_text=True)[:500])
            return ({"error": "No base64 data provided"}, 400, headers)
        base64_str = data.get("base64")
        if "," in base64_str:
            base64_str = base64_str.split(",", 1)[1]
        pdf_bytes = base64.b64decode(base64_str)

        # v25.17 FIX (Critical): หา page index ที่มี Front/Back diagrams จริง แทน hardcode=1
        # ทำครั้งเดียวตรงนี้แล้วส่งให้ทุกฟังก์ชัน เพื่อรับประกันว่าทุกขั้นตอนทำงานบนหน้าเดียวกัน
        diagram_page_idx = _find_diagram_page_idx(pdf_bytes)
        print(f"Using diagram_page_idx={diagram_page_idx}")

        # v25.17 FIX: extract_sku_from_pdf รับ page_idx เพื่อสแกนหน้าที่ถูกต้อง
        # (auto-detect ด้วย _find_sku_page_idx ถ้าไม่ระบุ — แต่ส่งค่าชัดเจนจะดีกว่า)
        sku_list = extract_sku_from_pdf(pdf_bytes, page_idx=None)  # auto-detect แยกต่างหาก
        sku_str = ", ".join(sku_list) if sku_list else ""

        # v25.15 FIX (Critical): full_img ของ pipeline หลักกลับไปใช้ matrix_scale=3 (ค่าเดิม
        # ก่อน v25.14) - v25.14 เคยเปลี่ยนเป็น scale=4 เพื่อแก้ Bug#1 แต่ทำให้ Cloud Function ใช้
        # memory เกิน limit จน HTTP 500 ทุกไฟล์เมื่อใช้งานจริง (ดู docstring
        # run_full_analysis_on_image/render_hires_crop) ตอนนี้ PHASE 1B render เฉพาะ region เล็กๆ
        # ที่ scale=4 แยกต่างหาก (ไม่กระทบ pipeline หลัก) จึงไม่จำเป็นต้องยก full_img ทั้งหน้าขึ้น
        # scale=4 อีกต่อไป
        # v25.17 FIX: ใช้ diagram_page_idx แทน hardcode 1
        full_img, doc, page = render_full_page(pdf_bytes, page_idx=diagram_page_idx, matrix_scale=3)

        # layout label (เก็บไว้เพื่อ output contract เดิม - อนุมานจากทิศทาง Front/Back label)
        front_bb = _word_bbox_rotated(page, "Front")
        back_bb = _word_bbox_rotated(page, "Back")
        if front_bb and back_bb:
            fx0, fy0, fx1, fy1 = front_bb
            bx0, by0, bx1, by1 = back_bb
            f_cx, f_cy = (fx0 + fx1) / 2, (fy0 + fy1) / 2
            b_cx, b_cy = (bx0 + bx1) / 2, (by0 + by1) / 2
            layout = "LEFT_RIGHT" if abs(f_cx - b_cx) > abs(f_cy - b_cy) else "TOP_BOTTOM"
        else:
            layout = "TOP_BOTTOM"

        # v25.90 NEW: ตรวจสอบว่าไฟล์นี้เป็น wireframe (line-drawing ไม่มี
        # สีทึบ) หรือไฟล์สีปกติ - เช็คจาก FRONT region (crop มาแล้วครั้งเดียว
        # ผ่าน get_view_region เดียวกับที่ path สีเดิมใช้อยู่แล้ว ไม่เพิ่ม
        # การ render ซ้ำซ้อน) ถ้าเป็น wireframe ให้ branch ไปใช้กลไกเฉพาะ
        # (v25.90 wireframe module ด้านบน) แทน pipeline สีเดิมทั้งหมด -
        # ไม่กระทบ path สีเดิมแม้แต่บรรทัดเดียว (wireframe path แยกฟังก์ชัน
        # ทั้งหมด, ใช้แค่ get_view_region/render_hires_crop ร่วมกันเพื่อ
        # ความสอดคล้องของพิกัด full-page เดียวกัน)
        wf_check_region, _, _ = get_view_region(full_img, doc, "front", page_idx=diagram_page_idx)
        is_wireframe = is_wireframe_region(wf_check_region)
        print(f"is_wireframe={is_wireframe}")

        if is_wireframe:
            wf_result = run_wireframe_analysis_on_image(
                pdf_bytes, full_img, doc, page, diagram_page_idx, matrix_scale=3, hi_scale=8)
            risks = wf_result["risks"]
            result = None  # ไม่มี stack_heights/local_floor_y แบบ pipeline สีเดิม -
                           # ทุก risk ของ wireframe คำนวณ abs_box ไว้ตรงจุดแล้ว
                           # (ดู run_wireframe_analysis_on_image) จึงไม่ต้องพึ่ง
                           # risk_abs_box(risk, result) เดิมเลย (result=None จะไม่
                           # ถูกใช้งาน เพราะ risk.get("abs_box") มีค่าเสมอ)
        else:
            # v25.17 FIX: ใช้ diagram_page_idx แทน hardcode 1
            result = run_full_analysis_on_image(full_img, doc, page_idx=diagram_page_idx, pdf_bytes=pdf_bytes, matrix_scale=3)
            risks = result["risks"]

        img = PIL.Image.fromarray(full_img).convert("RGB")
        draw = PIL.ImageDraw.Draw(img)

        # v25.29 FIX (ตามที่ผู้ใช้ระบุ - ตรวจพบว่าเคยถูกลบทิ้งไปโดยไม่ตั้งใจตอนพัฒนาต่อจาก
        # v25.28 เป็น v25.30-36 เพราะใช้ v25.28 เป็นฐานแทนที่จะเป็น v25.29 - กู้คืน fix นี้กลับมา
        # ในรอบนี้): เดิม detected_hazards เก็บ 1 รายการต่อ (risk_type, view, idx) ที่ไม่ซ้ำกัน
        # แล้วพิมพ์ "คำแนะนำวิธีแก้ไข" (generate_action_report) เต็มทุกรายการ - ถ้าพบความเสี่ยง
        # ประเภทเดียวกันหลายจุด (เช่น STEP_DOWN_RISK 3 จุด) รายงานจะพิมพ์คำแนะนำชุดเดิมซ้ำกัน 3
        # รอบ ทำให้ยาวเกินความจำเป็นในการอ่าน (คำแนะนำแก้ไขของแต่ละ risk_type เป็นข้อความคงที่
        # ไม่ได้ขึ้นกับตำแหน่ง/จุดที่พบเลย)
        # FIX: จัดกลุ่มตาม "ประเภทความเสี่ยง" (risk_type) เท่านั้น - พิมพ์หัวข้อ + คำแนะนำ
        # เพียง "ครั้งเดียวต่อประเภท" แล้วต่อท้ายหัวข้อด้วย "จำนวนจุดที่นับได้" ของประเภทนั้น
        # แทนการพิมพ์ซ้ำตามจำนวนจุด - ยังคงวาดกรอบ (marker) บนภาพครบทุกจุดที่ตรวจพบเหมือนเดิม
        # ทุกประการ (ไม่กระทบการแสดงผลภาพ) และยังคงนับ hazardCount = จำนวนจุดทั้งหมดจริง (ไม่ใช่
        # จำนวนประเภท) เพื่อไม่ให้กระทบ WebApp/GAS ฝั่งรับผลที่อาจอ้างอิงค่านี้อยู่แล้ว
        all_hazard_points = []
        risk_type_counts = {}
        risk_type_order = []  # รักษาลำดับการพบครั้งแรกของแต่ละประเภท
         
        for risk in risks:
            risk_type = risk["risk_type"]
            # v25.57 FIX: เดิม print แสดง height_source=None เสมอ (ทุกไฟล์ ทุก subtype) เพราะ
            # key 'height_source'/'gap_px'/'gap_ratio' ไม่เคยถูกใส่ไว้ใน risk dict จริงเลย -
            # ทำให้ debug log ที่ผ่านมาไม่สามารถยืนยันได้ว่า guard ต่างๆ (STEP_DOWN_MIN_RELIABLE_
            # SAMPLES, STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO ฯลฯ) ทำงานถูกต้องหรือไม่ และไม่เห็น
            # ขนาด gap จริงของ REAR_EMPTY_RISK เลย (พบระหว่างวิเคราะห์ log EA07-01/EB66-01
            # 29-Aug-2026) - ตอนนี้ทุก risk dict ใส่ height_source/n_samples ไว้จริงแล้ว (ดู
            # detect_step_down_pairwise/crossview/tail_stepdown) และเพิ่ม gap_px/gap_ratio ที่
            # REAR_EMPTY_RISK เก็บไว้อยู่แล้วแต่ไม่เคยถูก print ออกมา
            print(f"[RISK] {risk['risk_type']}/{risk.get('subtype')} view={risk.get('mark_view')} "
                  f"idx={risk.get('mark_stack_idx')} pos={risk.get('pos_range')} "
                  f"drop_ratio={risk.get('drop_ratio')} gap_px={risk.get('gap_px')} "
                  f"gap_ratio={risk.get('gap_ratio')} height_source={risk.get('height_source')} "
                  f"n_samples={risk.get('n_samples')} pair_indices={risk.get('pair_indices')}")
            outline_color = RISK_COLORS.get(risk_type, "red")
            # v25.23 FIX: risk บาง subtype (hidden_behind) คำนวณ abs_box ไว้ตรงจุดตรวจจับเลย
            # (ไม่ได้ผูกกับ stack_heights index ปกติ) ใช้ค่านี้ก่อนถ้ามี ไม่งั้น fallback ไป
            # risk_abs_box เดิม
            box = risk.get("abs_box") or risk_abs_box(risk, result)
            if box:
                _draw_single_rectangle(draw, box, outline_color)
            else:
                print(f"Could not compute marker box for {risk_type} (view={risk.get('mark_view')}, "
                      f"idx={risk.get('mark_stack_idx')})")

            all_hazard_points.append(risk)
            if risk_type not in risk_type_counts:
                risk_type_counts[risk_type] = 0
                risk_type_order.append(risk_type)
            risk_type_counts[risk_type] += 1

        if all_hazard_points:
            status_text = f"พบจุดเสี่ยงอันตราย ({len(all_hazard_points)} จุด)"
            sep = "\n\n" + "-" * 50 + "\n\n"
            blocks = []
            for risk_type in risk_type_order:
                count = risk_type_counts[risk_type]
                title = f"ความเสี่ยง: {risk_type} (พบ {count} จุด)"
                detail = generate_action_report(risk_type, "", sku_str)
                blocks.append(f"[{title}]\n{detail}")
            action_text = sep.join(blocks)
        else:
            status_text = "ปลอดภัย (SAFE)"
            action_text = generate_action_report("SAFE", "")

        buffered = io.BytesIO()
        img.save(buffered, format="JPEG", quality=80)
        processed_image_url = f"data:image/jpeg;base64,{base64.b64encode(buffered.getvalue()).decode('utf-8')}"
        gc.collect()
        return ({
            "status": status_text,
            "hazardCount": len(all_hazard_points),
            "layout": layout,
            "actionRequired": action_text,
            "processedImageUrl": processed_image_url,
            "checkerVersion": "V25.92",
            "benchmarkMode": "v25_92_wireframe_empty_space_verified_mask_fix" if is_wireframe else
                             "v25_89_isolated_pair_apex_jump_guard_hidden_behind_color_check",
        }, 200, headers)
    except Exception as e:
        err_trace = traceback.format_exc()
        print("CRITICAL ERROR DETAILS:\n", err_trace)
        gc.collect()
        return ({"error": str(e), "trace": err_trace[-500:]}, 500, headers)

